/* ============================================================
   Barjanji.js — Kitab Maulid Barzanji (LENGKAP)
   ============================================================ */

window.KITAB = window.KITAB || {};
window.KITAB["Barjanji"] = {
    sebutan: "Bab",
    catatan: "Kitab Maulid Barzanji karya Syekh Ja'far bin Hasan al-Barzanjī.",
    bab: [
        {
            judul: "Hadiah Fatihah & Shalawat Pembuka",
            isi: [
                { ar: "بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيْمِ", tr: "Bismillāhir-raḥmānir-raḥīm", ket: "Dengan menyebut nama Allah Yang Maha Pengasih lagi Maha Penyayang." },
                { ar: "اِلَى حَضْرَةِ النَّبِيِّ الْمُصْطَفَى رَسُوْلِ اللهِ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَعَلَى آلِهِ وَأَصْحَابِهِ وَأَزْوَاجِهِ وَذُرِّيَّاتِهِ وَأَتْبَاعِهِ الْكِرَامِ خُصُوْصًا اِلَى حَضْرَةِ الشَّيْخِ السَّيِّدِ جَعْفَرِ بْنِ حَسَنِ الْبَرْزَنْجِي... شَيْئٌ لِلّٰهِ لَهُمُ الْفَاتِحَة...", tr: "Ilā ḥaḍrati an-nabiyyi al-muṣṭafā Rasūlillāhi Muḥammadin ṣallallāhu 'alayhi wa sallam wa 'alā ālihi wa aṣḥābihi wa azwājihi wa dhurriyyātihi wa atbā'ihi al-kirām khuṣūṣan ilā ḥaḍrati ash-shaykhi as-sayyidi Ja'far bin Ḥasan al-Barzanjī... Shay'un lillāhi lahumul-Fātiḥah...", ket: "Kepada hadirat Nabi pilihan, Rasulullah Muhammad shallallāhu 'alayhi wa sallam, beserta keluarga, sahabat-sahabat, istri-istri, keturunan, dan pengikut-pengikut beliau yang mulia. Terutama kepada hadirat Syekh Sayyid Ja'far bin Hasan al-Barzanjī... Sesuatu untuk Allah, bagi mereka Al-Fātiḥah...." },
                { ar: "اَللّٰهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ وَعَلٰى اٰلِهِ", tr: "Allâhumma shalli wa sallim wa bârik 'alaihi wa 'alâ âlihi", ket: "Ya Allah, limpahkan rahmat, keselamatan, serta keberkahan kepada Nabi Muhammad beserta keluarga beliau." }
            ]
        },
        {
            judul: "Ya Robbi Sholli",
            isi: [
                { ar: "بِسْمِ اللّٰهِ الرَّحْمنِ الرَّحِيْمِ", tr: "Bismillāhir-raḥmānir-raḥīm", ket: "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang." },
                { ar: "يَا رَبِّ صَلِّ عَلَي مُحَمَّدْ ۞ يَا رَبِّ صَلِّ عَلَيْهِ وَسَلِّمْ", tr: "Yā Rabbi ṣalli ‘alā Muḥammad ۞ Yā Rabbi ṣalli ‘alayhi wa sallim", ket: "Ya Alloh, curahkanlah rahmat Teruntuk Nabi Muhammad, Rahmat dan kemuliaan Beserta salam dan kesejahteraan." },
                { ar: "يَا رَبِّ بَلِّغْهُ الْوَسِيْلَةْ ۞ يَا رَبِّ خُصَّهُ بِالْفَضِيْلَةْ", tr: "Yā Rabbi balligh-hul wasīlah ۞ Yā Rabbi khuṣṣahū bil-faḍīlah", ket: "Ya Alloh, kabulkanlah doaku ini padanya, Dan tambahkanlah keistimewaannya Dengan kesempurnaan dalam keutamaannya." },
                { ar: "يَا رَبِّ وَارْضَ عَنِ الصَّحَابَةْ ۞ يَا رَبِّ وَارْضَ عَنِ السُّلَالَةْ", tr: "Yā Rabbi warḍa ‘aniṣ-ṣaḥābah ۞ Yā Rabbi warḍa ‘anis-sulālah", ket: "Ya alloh, tambahkanlah keridhoanMu Pada para sahabat NabiMu Dan generasi beliau Yang memperoleh kemuliaan dariMu." },
                { ar: "يَا رَبِّ وَارْضَ عَنِ الْمَشَاِيخْ ۞ يَا رَبِّ وَارْحَمْ وَالِدِيْنَا", tr: "Yā Rabbi warḍa ‘anil-masyāyikh ۞ Yā Rabbi warḥam wālidīnā", ket: "Ya Alloh, ridhoilah para guru kami, Kasihilah para orang tua kami." },
                { ar: "يَا رَبِّ وَارْحَمْنَا جَمِيْعًا ۞ يَا رَبِّ وَاْرحَمْ كُلَّ مُسْلِمْ", tr: "Yā Rabbi warḥamnā jamī‘an ۞ Yā Rabbi warḥam kulla muslim", ket: "Ya Alloh, kasihilah seluruh kehidupan kami, Dan seluruh umat islam, Saudara-saudara kami." },
                { ar: "يَا رَبِّ وَاغْفِرْ لِكُلِّ مُذْنِبْ ۞ يَارَبِّ لَا تَقْطَعْ رَجَانَا", tr: "Yā Rabbi waghfir likulli mudhnib ۞ Yā Rabbi lā taqṭa‘ rajānā", ket: "Ya Alloh, ampunilah semua pendosa Dan kami mohon Janganlah Engkau putuskan Segala harapan kami." },
                { ar: "يَا رَبِّ يَاسَامِعْ دُعَانَا ۞ يَارَبِّ بَلِّغْنَا نَزُوْرُهْ", tr: "Yā Rabbi yā sāmi‘ du‘ānā ۞ Yā Rabbi ballighnā nazūruh", ket: "Ya Alloh, Sang Yang Pengkabul doa kami, Kunjungkanlah kami ke hadirat sang nabi." },
                { ar: "يَا رَبِّ تَغْشَانَا بِنُوْرِهْ ۞ يَا رَبِّ حِفْظَانَكْ وَأَمَانَكْ", tr: "Yā Rabbi taghsyānā binūrih ۞ Yā Rabbi ḥifẓānak wa amānak", ket: "Semoga Engkau terpakan Cahayanya kepada kami. Ya alloh, kami memohon pelindungan Serta rasa aman berkat rahmatMu." },
                { ar: "يَا رَبِّ وَاسْكِنَّا جِنَانَكْ ۞ يَا رَبِّ أَجِرْنَا مِنْ عَذَابِكْ", tr: "Yā Rabbi waskinnā jinānak ۞ Yā Rabbi ajirnā min ‘adhābik", ket: "Izinkanlah kami menempati surgaMu Dan selamatkanlah kami dari siksaMu." },
                { ar: "يَا رَبِّ وَارْزُقْنَا الشَّهَادَةْ ۞ يَا رَبِّ حِطْنَا بِالسَّعَادَةْ", tr: "Yā Rabbi warzuqnā asy-syahādah ۞ Yā Rabbi ḥiṭnā bis-sa‘ādah", ket: "Ya Alloh, anugerahilah kami Untuk bisa memandangMu Dan selimutilah kami Dengan kebahagiaan dari sisiMu." },
                { ar: "يَا رَبِّ وَاصْلِحْ كُلَّ مُصْلِحْ ۞ يَا رَبِّ وَاكْفِ كُلَّ مُؤْذِيْ", tr: "Yā Rabbi waṣliḥ kulla muṣliḥ ۞ Yā Rabbi wakfi kulla mu’dhī", ket: "Ya Alloh, berkahilah hamba-hambaMu Yang menebar kebaikan di jalanMu Dan selamatkanlah hamba-hambaMu Dari segala musuh Yang menghalangi jalan mereka Yang berjuang di jalanMu." },
                { ar: "يَا رَبِّ نَخْتِمْ بِالْمُشَفَّعْ ۞ يَا رَبِّ صَلِّ عَلَيْهِ وَسَلِّمْ", tr: "Yā Rabbi nakhtim bil-musyaffa‘ ۞ Yā Rabbi ṣalli ‘alayhi wa sallim", ket: "Ya Alloh, kami akhiri doa ini Atas syafa'at yang Engkau anugerahkan Pada sang Nabi KekasihMu Dan sampaikanlah selalu padanya Segala rahmat dan kesejahteraan Yang agung dari haribaanMu." }
            ]
        },
        {
            judul: "Ya Rosulallah",
            isi: [
                { ar: "اَللّٰهُـمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", tr: "Allâhumma shalli wa sallim wa bârik ‘alaih", ket: "Ya Allah, berilah salawat dan salam serta berkah atas Nabi s.a.w." },
                { ar: "يَارَسُوْلَ اللّٰه سَلَامٌ عَلَيْكَ ۰۞۰ يَارَفِيْعَ اْلشَّانِ وَاْلدَّرَجِ", tr: "Yâ Rosûlallâh salâmun ‘alaik, yâ rofî’asy-syâni waddaroji", ket: "Wahai utusan Allah, semoga keselamatan tetap padamu, Wahai yang berbudi luhur dan bermartabat tinggi." },
                { ar: "عَطْفَةً يَاجِيْرَةََ اْلعَلَمِ ۰۞۰ يَاأُهَيْلَ اْلجُوْدِ وَاْلگَرَمِ", tr: "‘Athfatan yâ jîrotal ‘alami, yâ uhailal jûdi wal karomi", ket: "Rasa kasihmu wahai pemimpin tetangga, Wahai ahli dermawan dan pemurah hati." },
                { ar: "نَحْنُ جِيْرَانٌ بِذَا اْلحَرَمِ ۰۞۰ حَرَمِ اْلِإحْسَانِ وَاْلحَسَنِ", tr: "Nahnu jîrônu bidzâl haromi, haromil ihsâni wal hasani", ket: "Kami tetangga di tanah haram ini. Tanah haram tempat berbuat baik dan memberi kebaikan." },
                { ar: "نَحْنُ مِنْ قَوْمٍ بِهِ سَگنُوْا ۰۞۰ وَبِهٍ مِنْ خَوْفِهِمْ اَمِنُوْا", tr: "Nahnu min qoumin bihî sakanû, wa bihî min khoufihim âminû", ket: "Kami dari kaum yang tinggal di tempat itu. Tempat yang mereka merasa aman dari ketakutan." },
                { ar: "وَبِأَياَتِ اْلقُرْآَنِ عُنُوْا ۰۞۰ فَاتَّئِدْ فِيْنَا أَخَا اْلوَهَنِ", tr: "Wa bi âyâtil qur-ãni ‘unû, fatta-id fînâ akhôl wahani", ket: "Dengan ayat-ayat Al-Qu’an mereka mendapat inayah. Renungkanlah di hati kita, wahai yang berjiwa lemah." },
                { ar: "نَعْرِفُ اْلبَطْحَا وَتَعْرِفُنَا ۰۞۰ وَالصَّفَا وَاْلبَيْتُ يَأْلَفُنَا", tr: "Na’riful bath-hâ wa ta’rifunâ, wash-shofâ wal baitu ya,lafunâ", ket: "Kami mengenal padang pasir dan ia mengenal kami, Bukit Shafa dan Baitil-Haram menawan hati kami." },
                { ar: "وَلَنَا اْلمَعْلَى وَخَيْفُ مِنَا ۰۞۰ فَاعْلَمَنْ هَذَا وَكُنْ وَكُنِ", tr: "Wa lanâl Ma’lâ wa khoifu minâ, fa’laman hâdzâ wakun wakuni", ket: "Kami punya Ma’la dan masjid Kha’if di kota Mina. Maka ketahuilah ini dan wujudkanlah pula beribadah di tempat ini." },
                { ar: "وَلَنَا خَيْرٌ اْلأَنَامِ أَبُ ۰۞۰ وَعَلِيُّ اْلمُرْتَضَی حَسَبُ", tr: "Wa lanâ khoirul anâmi abu, wa ‘Aliyyul murtadlô hasabu", ket: "Kami mempunyai ayah sebaik-baik makhluk. Dan adalah keturunan Ali yang diridhai." },
                { ar: "وَإلىَ اْلسِّبْطَيْنِ نَنتَسِبُ ۰۞۰ نَسَبًامَافِيْهِ مِنْ دَخَنِ", tr: "Wa ila alssibtayni nantasiibu, Nasaban ma feehi min dakhani", ket: "Kita berasal dari dua suku, keturunan yang ada di dalamnya seperti asap." },
                { ar: "كَمْ إِمَامٍ بَعْدَهُ خَلَفُوْا ۰۞۰ مِنْهُ سَادَةٌبِذَاعُرِفُوْا", tr: "Kam 'imaamin ba'dahu khalafuu, Minhu saadaatun bizhaa'urifu", ket: "Setelah beberapa imam, terlahir pemimpin-pemimpin yang terkenal." },
                { ar: "وَبِهَذَاالْوَصْفِ قَدْوُصِفُوْا ۰۞۰ مِنْ قَدِيْمِ اْلدَّهْرِوَاْلزَّمَنِ", tr: "Wabi-haadza al-washfi qad wushifoo, Min qadeemid-dahri wal-zamani", ket: "Mereka telah digambarkan dengan sifat-sifat ini, Sejak dahulu kala dan zaman yang lalu." },
                { ar: "مِثْلُ زَيْنِ اْلعَابِدِيْنَ عَلِيْ ۰۞۰ وَابْنِهِ اْلبَاقِيْرِخَيْرِوَلِيْ", tr: "Mithlu zayni al-'aabidiina 'Ali, Wa ibnihi al-baariqir khairi walii", ket: "Seperti Zainul Abidin Ali, dan putranya Al Baqir yang mulia." },
                { ar: "وَالْإِمَامِ الصَّادِقِ الْحَفِلٍ ۰۞۰ وَعَلِيِِّ ذِي الْعُلَى الْيَقِنِ", tr: "Wal-'imaami al-saadiqil hafil, Wa 'Aliyyi dhil-'ula al-yaqini", ket: "Imam yang jujur dan amanah, Ali yang penuh keyakinan." },
                { ar: "فَهُمُ الْقَوْمُ الَّذِيْنَ هُدُوْا ۰۞۰ وَبِفَضْلِ اللّّٰهِ قَدْسَعِدُوْا", tr: "Fahumul-qawmu alladhiina huduu, Wa bifadlillahi qadsa'duu", ket: "Mereka adalah orang-orang yang mendapat petunjuk, dan dengan karunia Allah mereka bahagia." },
                { ar: "وَلِغَيْرِاللّّٰهِ مَاقَصَدُوْا ۰۞۰ وَمَعَ الْقُرْآنِ فِيْ قَرَنِ", tr: "Wa li-ghayrillahi maa qasaduu, Wa ma'a al-qur'aani fi qarni", ket: "Mereka tidak berniat untuk selain Allah, dan bersama Al-Quran di zaman mereka." },
                { ar: "أَهْلُ بَيْتِ الْمُصْطَفَى الطُّهُرِ ۰۞۰ هُمْ أَمَانُ الْأَرْضِ فَادَّكِرِ", tr: "Ahlu baitil mustafaa alth-thuhuri, Hum amaanul-ardhi faddakiri", ket: "Ahlul Bait sang pemilih yang suci, mereka adalah penjaga bumi, jangan lupakan." },
                { ar: "شُبِِّهُوْا بِالْأَنْجُمِ الزُّهُرِ ۰۞۰ مِثْلَ مَاقَدْجَاءَفِي السُّنُنِ", tr: "Shubbihuu bil-anjumi al-zuhuri, Mithla ma qad jaa'a fi al-sununi", ket: "Mereka dibandingkan dengan bintang-bintang terang, seperti yang telah disebutkan dalam hadis." },
                { ar: "وَسَفِيْنٌ لِلنَّجَاةِ إِذَا ۰۞۰ خِفْتَ مِنْ طُوْفَانِ كُلِِّ أَذَاى", tr: "Wa safiinul-lajati idhaa, Khifta min tufaani kulli-i adhaa", ket: "Mereka adalah kapal keselamatan ketika, takut akan badai di setiap waktu." },
                { ar: "فَانْجُ فِيْهَا لَاتَكُوْنُ كَذَا ۰۞۰ وَاعْتَصِمُوْبِاللّٰهِ وَاسْتَعِنِ", tr: "Fanju fiihaa la takuunu kadzaa, Wa'tasimuu billahi wasta'ini", ket: "Berlindunglah pada mereka sehingga tidak akan ada bahaya, berpeganglah pada Allah dan mintalah pertolongan." },
                { ar: "رَبّ فَانْفَعْنَا بِبَرْگتِهِمْ ۰۞۰ وَاهْدِنَااْلحُسْنَی بِحُرْمَتِهِمْ", tr: "Robbi fanfa’nâ bibarkatihim wahdinâl husnâ bi hurmatihim", ket: "Ya Allah, dengan barokah mereka, berila kami kemanfaatan. Dan dengan kehormatan mereka, tunjukkan kami kepada kebaikan." },
                { ar: "وَأُمِتْنَا فِی طَرِيْقَتِهِمْ ۰۞۰ وَمُعَافَاةٍ مِنَ الْفَتَنِ", tr: "Wa amitnâ fî thorîqotihim, wa mu’âfâtin minal fitani", ket: "Dan wafatkanlah kami di jalan mereka, dan selamat dari segala fitnah." }
            ]
        },
        {
            judul: "Inna Fatahna",
            isi: [
                { ar: "بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيْمِ", tr: "Bismillāhir-raḥmānir-raḥīm", ket: "Dengan nama Alloh yang Maha Pengasih lagi Maha Penyayang." },
                { ar: "اِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِيْنًاۙ ۞ لِّيَغْفِرَ لَكَ اللّٰهُ مَا تَقَدَّمَ مِنْ ذَنْۢبِكَ وَمَا تَاَخَّرَ وَيُتِمَّ نِعْمَتَهٗ عَلَيْكَ وَيَهْدِيَكَ صِرَاطًا مُّسْتَقِيْمًاۙ ۞ وَّيَنْصُرَكَ اللّٰهُ نَصْرًا عَزِيْزًا.", tr: "Inna fatahna laka fathan mubinan. Liyaghfiralakallahu ma taqaddama min dzanbika wama ta-akh-khara wa yutimma ni’matahu ‘alayka wa yahdiyaka shirathan mustaqima. wayansyurukallaahu nashron 'aziiza.", ket: "Sesungguhnya Kami (Allah) telah bukakan (memberikan kemenangan) kepada kamu, pembukaan (kemenangan) yang nyata. Karena Alloh akan mengampuni dosa-dosamu yang telah lalu dan yang akan datang, serta menyempurnakan nikmat-Nya (Alloh) kepadamu, dan memberikan petunjuk padamu jalan yang lurus. Dan Alloh akan memberikan pertolongan kepadamu dengan pertolongan yang nyata. (QS. Al-Fath: 1-3)" },
                { ar: "لَقَدْ جَاۤءَكُمْ رَسُوْلٌ مِّنْ اَنْفُسِكُمْ عَزِيْزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيْصٌ عَلَيْكُمْ بِالْمُؤْمِنِيْنَ رَءُوْفٌ رَّحِيْمٌ.", tr: "Laqad ja-akum rasulun min anfusikum ‘azizun ‘alayhi ma ‘anittum harishun ‘alaykum bil-mukminina raufun rahim.", ket: "Telah datang kepada kamu seorang utusan Allah dari jenis kamu sendiri, ia merasakan apa penderitaanmu, lagi sangat mengharapkan akan keselamatanmu, kepada orang yang beriman senantiasa merasa kasih sayang. (QS. At-Taubah: 128)" },
                { ar: "فَاِنْ تَوَلَّوْا فَقُلْ حَسْبِيَ اللّٰهُ لَآ اِلٰهَ اِلَّا هُوَ ۗ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيْمِ.", tr: "Fa in tawallau fa qul ḥasbiyallāhu lā ilāha illā huw, 'alaihi tawakkaltu wa huwa rabbul-'arsyil-'aẓīm.", ket: "Maka jika mereka berpaling (dari keimanan), maka katakanlah (Muhammad), “Cukuplah Allah bagiku; tidak ada tuhan selain Dia. Hanya kepada-Nya aku bertawakal, dan Dia adalah Tuhan yang memiliki ‘Arsy (singgasana) yang agung.” (QS. At-Taubah: 129)" },
                { ar: "اِنَّ اللّٰهَ وَمَلٰۤىِٕكَتَهٗ يُصَلُّوْنَ عَلَى النَّبِيِّۗ يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا صَلُّوْا عَلَيْهِ وَسَلِّمُوْا تَسْلِيْمًا.", tr: "Innallaha wa malaikatahu yushalluna ‘alann nabi, ya ayyuhalladzina amanu shallu ‘alayhi wa sallimu taslima.", ket: "Sesungguhnya Allah dan para malaikat-Nya selalu bersholawat untuk Nabi, wahai orang-orang yang beriman! Bersholawat dan salamlah untuknya (Nabi Muhammad saw). (QS. Al-Ahzab: 56)" },
                { ar: "اَلّٰلهُـمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهْ", tr: "Allâhumma sholli wa sallim wa bârik ‘alaih", ket: "Ya Alloh tetapkanlah limpahan rahmat dan salam serta keberkahan kepadanya Nabi Muhammad." }
            ]
        },
        {
            judul: "Al Barjanji (Pembuka)",
            isi: [
                { ar: "۞الْجَنَّةُ وَ نَعِيْمُهَا سَعْدٌ لِمَنْ يُصَلِّيْ ۞ وَ يُسَلِّمُ وَ يُبَارِكُ عَلَيْهِ۞", tr: "Al-jannatu wa na‘īmuhā sa‘dun liman yuṣallī ۞ wa yusallimu wa yubāriku ‘alayh", ket: "Surga dan kenikmatannya sebagai keberuntungan bagi siapa saja yang bershalawat dan memohonkan selamat serta berkah atas Nabi." },
                { ar: "بِسْمِ اللّٰهِ الرَّحْمنِ الرَّحِيْمِ", tr: "Bismillāhir-raḥmānir-raḥīm", ket: "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang." },
                { ar: "أَبْتَدِئُ الْإِمْلَاءَ بِاسْمِ الذَّاتِ الْعَلِيَّةِ مُسْتَدِرًا فَيْضَ الْبَرَكَاتِ عَلَى مَا أَنَالَهُ وَ أَوْلَاهُ؟", tr: "Abtadi’ul imlā’a bismidz-dzātil ‘aliyyati mustadirran faiḍal barakāti ‘alā mā anālahu wa aulāh", ket: "1. Saya mulai penulisan kitab (kisah Maulid Nabi) ini dengan menyebut nama Allah Yang Maha Agung, seraya memohon limpahan berkah atas apa yang telah diberikan-Nya." },
                { ar: "وَ أُثَنِّيْ بِحَمْدٍ مَوَارِدُهُ سَائِغَةٌ هَنِيَّةٌ؟", tr: "Wa utsannī biḥamdin mawāriduhū sā’ighatun haniyyah", ket: "2. Dan juga saya memanjatkan puja dan puji, dengan pujian yang tak ada henti-hentinya." },
                { ar: "مُمْتَطِيًا مِنَ الشُّكْرِ الْجَمِيْلِ مَطَايَاهُ؟", tr: "Mumtaṭiyan minasy-syukril jamīli maṭāyāh", ket: "3. Dan seraya mempersembahkan sedalam-dalamnya rasa syukur yang baik." },
                { ar: "وَ أُصَلِّيْ وَ أُسَلِّمُ عَلَى النُّوْرِ الْمَوْصُوْفِ بِالتَّقَدُّمِ وَ الْأَوَّلِيَّةِ؟", tr: "Wa uṣallī wa usallimu ‘alan-nūril mauṣūfi bit-taqaddumi wal awwaliyyah", ket: "4. Dan saya mengucapkan shalawat dan salam atas “Nūr” (Muḥammad) yang bersifat mendahului dan mengawali." },
                { ar: "الْمُنْتَقِلِ فِي الْغُرَرِ الْكَرِيْمَةِ وَ الْجِبَاهِ؟", tr: "Al-muntaqili fil ghuraril karīmati wal jibāh", ket: "5. Nūr yang senantiasa berpindah-pindah dari dahi ke dahi para leluhurnya, orang-orang yang terkemuka." },
                { ar: "وَ اَسْتَمْنِحُ اللّٰهَ تَعَالَى رِضْوَانًا يَخُصُّ الْعِتْرَةَ الطَّاهِرَةَ النَّبَوِيَّةَ؟", tr: "Wa astamniḥullāha ta‘ālā riḍwānan yakhuṣṣul ‘itrataṭ-ṭāhiratan-nabawiyyah", ket: "6. Dan saya memohon keridhaan Allah ta‘ala, khusus bagi para keluarga Nabi yang suci." },
                { ar: "وَ يَعُمُّ الصَّحَابَةَ وَ الْأَتْبَاعَ وَ مَنْ وَالَاهُ؟", tr: "Wa ya‘ummush-ṣaḥābata wal atbā‘a wa man wālāh", ket: "7. Dan semoga melimpah ruah pula kepada para sahabatnya, para pengikutnya dan orang-orang yang mencintainya." },
                { ar: "وَ اَسْتَجْدِيْهِ هِدَايَةً لِسُلُوْكِ السُّبُلِ الْوَاضِحَةِ الْجَلِيَّةِ؟", tr: "Wa astajdīhi hidāyatan lisulūkis-subulil wāḍiḥatil jaliyyah", ket: "8. Dan saya memohon hidayah, agar kita semua dapat menempuh jalan yang sudah jelas dan terang." },
                { ar: "وَ حِفْظًا مِنَ الْغَوَايَةِ فِيْ خِطَطِ الْخَطَإِ وَ خُطَاهُ؟", tr: "Wa ḥifẓan minal ghawāyati fī khiṭaṭil khaṭa’i wa khuṭāh", ket: "9. Dan saya memohon perlindungan, agar terpelihara dari kesalahan-kesalahan dalam penulisan kisah ini." },
                { ar: "وَ اَنْشُرُ مِنْ قِصَّةِ الْمَوْلِدِ النَّبَوِيِّ بُرُوْدًا حِسَانًا عَبْقَرِيَّةً؟", tr: "Wa ansyuru min qiṣṣatil maulidin-nabawiyyi burūdan ḥisānan ‘abqariyyah", ket: "10. Dan saya beberkan kisah Maulid Nabi dengan cara yang elok dan indah." },
                { ar: "نَاظِمًا مِنَ النَّسَبِ الشَّرِيْفِ عِقْدًا تُحَلَّى الْمَسَامِعُ بِحُلَاهُ؟", tr: "Nāẓiman minan-nasabisy-syarīfi ‘iqdan tuḥallal masāmi‘u biḥulāh", ket: "11. Sambil merangkai untaian nasab mulia yang terasa manis bagi para pendengarnya." },
                { ar: "وَ اَسْتَعِيْنُ بِحَوْلِ اللّٰهِ تَعَالَى وَقُوَّتِهِ الْقَوِيَّةِ؟", tr: "Wa asta‘īnu biḥaulillāhi ta‘ālā wa quwwatihil qawiyyah", ket: "12. Kemudian, saya memohon pertolongan kepada Allah, dengan segala daya dan kekuatan dari Allah ta‘ālā." },
                { ar: "فَإِنَّهُ لَا حَوْلَ وَ لَا قُوَّةَ إِلَّا بِاللّٰهِ؟", tr: "Fa innahū lā ḥaula wa lā quwwata illā billāh", ket: "13. Karena tiada daya dan kekuatan kecuali dengan pertolongan Allah." }
            ]
        },
        {
            judul: "Al Barjanji (Nasab Nabi)",
            isi: [
                { ar: "عَطِّرِاللّٰهُـمَّ قَبْرَهُ الْكَرِيْمِ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمٍ", tr: "‘Aththirillāhumma qabrahul karīm ۞ bi‘arfin syadziyyin min ṣalātin wa taslīm", ket: "Semoga Allah mengharumkan dan mewangikan kuburnya (Nabi) yang mulia, dengan keharuman wangi-wangian salawat dan salam sejahtera." },
                { ar: "بِسْمِ اللّٰهِ الرَّحْمنِ الرَّحِيْمِ", tr: "Bismillāhir-raḥmānir-raḥīm", ket: "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang." },
                { ar: "وَ بَعْدُ فَأَقُوْلُ: هُوَ سَيِّدُنَا مُحَمَّدُ بْنُ عَبْدِ اللّٰهِ بْنِ عَبْدِ الْمُطَّلِبِ وَ اسْمُهُ شَيْبَةُ الْحَمْدِ حُمِدَتْ خِصَالُهُ السَّنِيَّةُ؟", tr: "Wa ba‘du fa aqūlu: Huwa sayyidunā Muḥammadubnu ‘Abdillāhibni ‘Abdil Muṭṭhalib, wasmuhū Syaibatul Ḥamdi ḥumidat khiṣāluhus-saniyyah.", ket: "Wa ba‘du, maka saya katakan: Beliau adalah Muḥammad bin ‘Abdillāh bin ‘Abd-il-Muththalib, dan disebut orang juga dengan Syaibat-ul-Ḥamdi, yang terpuji budi pekertinya yang luhur." },
                { ar: "اِبْنِ هَاشِمٍ وَاسْمُهُ عَمْرُو بْنُ عَبْدِ مَنَافٍ وَاسْمُهُ الْمُغِيْرَةُ الَّذِيْ يَنْتَمِي الْاِرْتِقَاءُ لِعُلْيَاهُ؟", tr: "Ibn Hāsyim, wasmuhū ‘Amrubnu ‘Abdi Manāf, wasmuhul Mughīratul-ladzī yantamīl irtiqā’u li‘ulyāh.", ket: "Bin Hāsyim dan juga bernama ‘Amr, bin ‘Abdi Manāf dan juga bernama Mughīrah yang senantiasa bertambah-tambah ketinggian derajatnya." },
                { ar: "اِبْنِ قُصَيِّ وَاسْمُهُ مُجَمِّعٌ سُمِّيَ بِقُصَيِّ لِتَقَاصِيْهِ فِيْ بِلَادِ قُضَاعَةَ الْقَصِيَّةِ؟", tr: "Ibn Quṣayyi wasmuhū Mujammi‘, summiya bi Quṣayyi litaqāṣīhi fī bilādi Quḍā‘atil qaṣiyyah.", ket: "Bin Qushayyi dan juga dipanggil orang dengan Mujammi‘. Dan dia disebut Qushayyi, karena jauhnya berkelana di tanah Qudhā‘ah yang terpencil dari kota Makkah." },
                { ar: "إِلَى أَنْ أَعَادَهُ اللّٰهُ تَعَالَى إِلَى الْحَرَمِ الْمُحْتَرَمِ فَحَمَى حِمَاهُ؟", tr: "Ilā an a‘ādahullāhu ta‘ālā ilal ḥaramil muḥtaram fa ḥamā ḥimāh.", ket: "Sehingga Allah mengembalikan beliau dan menetapkannya di tanah suci Makkah, lalu dia menjaga kesucian kota Makkah." },
                { ar: "اِبْنِ كِلَابٍ وَاسْمُهُ حَكِيْمُ بْنُ مُرَّةَ بْنِ كَعْبِ بْنِ لُؤَيِّ بْنِ غَالِبٍ بْنِ فِهْرٍ وَاسْمُهُ قُرَيْشٌ وَ إِلَيْهِ تُنْسَبُ الْبُطُوْنُ الْقُرَشِيَّةُ؟", tr: "Ibn Kilāb wasmuhū Ḥakīmubnu Murrah, ibnu Ka‘ab, ibnu Lu’ayyi, ibnu Ghālib, ibni Fihr, wasmuhū Quraisy, wa ilaihi tunsabul buṭūnul Qurasyiyyah.", ket: "Bin Kilāb dan juga dipanggil Ḥakīm bin Murrah, bin Ka‘ab, bin Lu’ayyi, bin Ghālib, bin Fihr dan disebut orang dengan nama Quraisy. Dan dengan nama Quraisy itulah, kemudian keturunan Fihr dinamakan suku Quraisy." },
                { ar: "وَ مَا فَوْقَهُ كِنَانِيٌّ كَمَا جَنَحَ إِلَيْهِ الْكَثِيْرُ وَارْتَضَاهُ؟", tr: "Wa mā fauqahū Kināniyyun kamā janaḥa ilaihil katsīru wartaḍāh.", ket: "Dan keturunan sebelum Quraisy disebut suku Kinānah. Demikianlah menurut keterangan yang telah disepakati ahli riwayat." },
                { ar: "اِبْنِ مَالِكِ بْنِ النَّضْرِ بْنِ كِنَانَةَ بْنِ خُزَيْمَةَ بْنِ مُدْرِكَةَ ابْنِ إِلْيَاسَ وَ هُوَ أَوَّلُ مَنْ أَهْدَى الْبُدْنَ إِلَى الرِّحَابِ الْحَرَمِيَّةِ؟", tr: "Ibni Mālikibni Naḍribni Kinānatabni Khuzaimatabni Mudrikatabni Ilyāsa, wa huwa awwalu man ahdal budna ilar-riḥābil ḥaramiyyah.", ket: "Bin Mālik, bin Nadhr bin Kinānah, bin Khuzaimah, bin Mudrikah bin Ilyās, dialah yang pertama menghadiahkan unta yang disembelih di bumi haram kota Makkah." },
                { ar: "وَ سُمِعَ فِيْ صُلْبِهِ النَّبِيُّ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ ذَكَرَ اللّٰهَ تَعَالَى وَ لَبَّاهُ؟", tr: "Wa sumi‘a fī ṣulbihin-nabiyyu ṣallallāhu ‘alaihi wa sallama dzakarallāha ta‘ālā wa labbāh.", ket: "Dari tulang belakang beliau, didengar Nabi s.a.w. berdzikir dan bertalbiyyah kepada Allah." },
                { ar: "اِبْنِ مُضَرَ بْنِ نِزَارِ بْنِ مَعَدِّ بْنِ عَدْنَانَ، وَ هٰذَا سِلْكٌ نَّظَمَتْ فَرَائِدُهُ بَنَانُ السُّنَّةِ السَّنِيَّةِ؟", tr: "Ibni Muḍarabni Nizāribni Ma‘addibni ‘Adnān, wa hādzā silkun naẓamat farā’iduhū banānus-sunnatis-saniyyah.", ket: "Bin Mudhar, bin Nizār, bin Ma‘add, bin ‘Adnān. Demikianlah nasab beliau Nabi Muḥammad s.a.w. menurut jalan riwayat ‘Ulamā’ muḥadditsīn, bagaikan butir-butir permata indah." },
                { ar: "وَ رَفْعُهُ إِلَى الْخَلِيْلِ إِبْرَاهِيْمَ أَمْسَكَ عَنْهُ الشَّارِعُ وَ أَبَاهُ؟", tr: "Wa raf‘uhū ilal khalīli Ibrāhīma amsaka ‘anhusy-syāri‘u wa abāh.", ket: "Nasab beliau s.a.w. ke atas sampai kepada al-Khalīl Ibrāhīm a.s. Beliau enggan dan melarang menyebutnya sampai kepadanya." },
                { ar: "وَ عَدْنَانُ بِلَا رَيْبٍ عِنْدَ ذَوِي الْعُلُوْمِ النَّسَبِيَّةِ؟", tr: "Wa ‘Adnānu bilā raibin ‘inda dzawil ‘ulūmin nasabiyyah.", ket: "‘Adnān, menurut keterangan ‘ulamā’ yang ahli tentang nasab, tanpa diragukan lagi." },
                { ar: "إِلَى الذَّبِيْحِ إِسْمٰعِيْلَ نِسْبَتُهُ وَ مُنْتَمَاهُ؟", tr: "Iladz-dzabīḥi Ismā‘īla nisbatuhū wa muntamāh.", ket: "Bernasab dan berkesinambungan kepada Nabi Ismā‘īl yang telah menjalani perintah untuk berqurban jiwa." },
                { ar: "فَأَعْظِمْ بِهِ مِنْ عِقْدٍ تَأَلَّقَتْ كَوَاكِبُهُ الدُّرِّيَّةُ؟", tr: "Fa a‘ẓim bihī min ‘iqdin ta’allaqat Kawākibuhud-durriyyah.", ket: "Alangkah hebatnya nasab beliau ini, yang tersunting sebagai butir-butir permata, penghias bintang-bintang gemerlapan." },
                { ar: "وَ كَيْفَ لَا وَ السَّيِّدُ الْأَكْرَمُ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ وَاسِطَتُهُ الْمُنْتَقَاهُ؟", tr: "Wa kaifa lā was-sayyidul akramu ṣallallāhu ‘alaihi wa sallama wāsiṭatuhul muntaqāh.", ket: "Mengapa tidak, bukankah beliau s.a.w. yang mulia adalah Nabi seluruh makhluk terpilih?" },
                { ar: "نَسَبٌ تَحْسِبُ الْعُلَا بِحُلَاهُ ۞ قَلَّدَتْهَا نُجُوْمَهَا الْجَوْزَاءُ ۞", tr: "Nasabun taḥsibul ‘ulā biḥulāh ۞ Qalladat-hā nujūmahal jauzā’", ket: "15. Nasab beliau s.a.w. terhitung nasab mulia, bagaikan sekumpulan bintang kejora." },
                { ar: "حَبَّذَا عِقْدُ سُوْدَدٍ وَ فَخَارٍ ۞ اَنْتَ فِيْهِ الْيَتِيْمَةُ الْعَصْمَاءُ", tr: "Ḥabbadzā ‘iqdu sudadin wa fakhār ۞ Anta fīhil yatīmatul ‘aṣmā’", ket: "16. Ibarat kalung mutiara hiasan megah, di dalamnya, engkau sangat berharga dan terpelihara." },
                { ar: "وَ أَكْرِمْ بِهِ مِنْ نَسَبٍ طَهَّرَهُ اللّٰهُ تَعَالَى مِنْ سِفَاحِ الْجَاهِلِيَّةِ؟", tr: "Wa akrim bihī min nasabin ṭahharahullāhu ta‘ālā min sifāḥil jāhiliyyah.", ket: "17. Alangkah mulia nasab yang telah disucikan Allah ta‘ālā dari perbuatan keji di masa Jahiliyyah." },
                { ar: "أَوْرَدَ الزَّيْنُ الْعِرَاقِيُّ وَارِدَهُ فِيْ مَوْرِدِهِ الْهَنِيِّ وَ رَوَاهُ؟", tr: "Aurodaz-zainul ‘Irāqiyyu wāridahū fī mauridihil haniyyi wa rawāh.", ket: "18. Demikianlah, menurut keterangan yang telah diriwayatkan oleh Syaikh Zain-ul-‘Irāqiy di dalam kitabnya yang bernama “Maurid-ul-Haniy.”" },
                { ar: "حَفِظَ الْإِلٰهُ كَرَامَةً لِمُحَمَّدٍ ۞ آبَاءَهُ الْأَمْجَادَ صَوْنًا لِاسْمِهِ ۞", tr: "Ḥafiẓal ilāhu karāmatan li Muḥammad ۞ Ābā’ahul amjāda ṣaunan lismih", ket: "19. Tuhan (Allah) telah memelihara kemuliaan Nabi Muḥammad, terhadap bapak-bapaknya yang mulia, demi memelihara namanya." },
                { ar: "تَرَكُوا السِّفَاحَ فَلَمْ يُصِبْهُمْ عَارُهُ ۞ مِنْ اٰدَمٍ وَّ إِلٰى أَبِيْهِ وَ أُمِّهِ", tr: "Taraku as-sifāḥa falam yuṣibhum ‘āruh ۞ Min Ādama wa ilā abīhi wa ummih", ket: "20. Mereka tinggalkan perzinaan, maka mereka senantiasa tak tercela sejak Nabi Ādam hingga ibu bapaknya." },
                { ar: "سَرَاةٌ سَرٰى نُوْرُ النُّبُوَّةِ فِيْ أَسَارِيْرِ غُرَرِهِمُ الْبَهِيَّةِ؟", tr: "Sarātun sarā nūrun-nubuwwati fī asārīri ghurarihimul bahiyyah.", ket: "21. Nūr kenabian Muḥammad selalu berpindah dan memancar dari pelipis ke pelipis nenek moyangnya dengan cerlang-cemerlang." },
                { ar: "وَ بَدَرَ بَدْرُهُ فِيْ جَبِيْنِ جَدِّهِ عَبْدِ الْمُطَّلِبِ وَ ابْنِهِ عَبْدِ اللّٰهِ؟", tr: "Wa badara badruhū fī jabīni jaddihī ‘Abdil Muṭṭhalibi wabnihī ‘Abdillāh.", ket: "22. Dan nampak jelas kecermelangannya pada kening kakeknya ‘Abd-ul-Muththalib dan putranya ‘Abdullāh." }
            ]
        },
        {
            judul: "Al Barjanji (Cahaya Nabi & Masa Kehamilan)",
            isi: [
                { ar: "عَطِّرِاللّٰهُـمَّ قَبْرَهُ الْكَرِيْمِ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمٍ", tr: "‘Aththirillāhumma qabrahul karīm ۞ bi‘arfin syadziyyin min ṣalātin wa taslīm", ket: "Semoga Allah mengharumkan dan mewangikan kuburnya (Nabi) yang mulia, dengan keharuman wangi-wangian salawat dan salam sejahtera." },
                { ar: "بِسْمِ اللّٰهِ الرَّحْمنِ الرَّحِيْمِ", tr: "Bismillāhir-raḥmānir-raḥīm", ket: "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang." },
                { ar: "وَلَمَّا أَرَادَ اللّٰهُ تَعَالَى إِبْرَازَ حَقِيْقَتِهِ الْمُحَمَّدِيَّةِ؟", tr: "Wa lammā arādallāhu ta‘ālā ibrāza ḥaqīqatihil muḥammadiyyah.", ket: "Ketika Allah ta‘ālā hendak menjelmakan hakekat Nabi Muḥammad s.a.w." },
                { ar: "وَ إِظْهَارَهُ جِسْمًا وَ رُوْحًا بِصُوْرَتِهِ وَ مَعْنَاهُ؟", tr: "Wa iẓhārahū jisman wa rūḥan biṣūratihī wa ma‘nāh.", ket: "Dan mewujudkan jasmani dan rohaninya dengan bentuk rupanya dan sifatnya di alam dunia." },
                { ar: "نَقَلَهُ إِلَى مَقَرِّهِ مِنْ صَدَفَةِ آمِنَةَ الزُّهْرِيَّةِ؟", tr: "Naqalahū ilā maqarrihī min ṣadafati Āminataz-Zuhriyyah.", ket: "Maka Allah memindahkan tempat nūr tersebut kepada Āminah yang suci." },
                { ar: "وَ خَصَّهَا الْقَرِيْبُ الْمُجِيْبُ بِأَنْ تَكُوْنَ أُمًّا لِمُصْطَفَاهُ؟", tr: "Wa khaṣṣahal qarībul mujību bi’an takūna umman li muṣṭafāh.", ket: "Dan Allah mengkhususkan kepadanya, sebagai ibu dari Nabi yang terpilih." },
                { ar: "وَ نُوْدِيَ فِي السَّمٰوَاتِ وَ الْأَرْضِ بِحَمْلِهَا لِأَنْوَارِهِ الذَّاتِيَّةِ؟", tr: "Wa nūdiya fis-samāwāti wal arḍi biḥamlihā li anwārihidz-dzātiyyah.", ket: "Dan diumumkan ke seluruh penjuru langit dan bumi, bahwa nūr-nya telah dikandung ibunya." },
                { ar: "وَ صَبَا كُلُّ صَبٍّ لِهُبُوْبِ نَسِيْمِ صَبَاهُ؟", tr: "Wa ṣabā kullu ṣabbin lihubūbi nasīmi ṣabāh.", ket: "Angin-angin sepoi semilir bertiup, maka seluruh makhluk senantiasa rindu dan berharap dengan kelahirannya." },
                { ar: "وَ كُسِيَتِ الْأَرْضُ بَعْدَ طُوْلِ جَدْبِهَا مِنَ النَّبَاتِ حُلَلًا سُنْدُسِيَّةً؟", tr: "Wa kusiyatil arḍu ba‘da ṭūli jadbiḥā minan-nabāti ḥulalan sundusiyyah.", ket: "Dan bumi yang telah bertahun-tahun gersang, mulai tumbuh tanamannya menjadi bumi yang sangat subur." },
                { ar: "وَ أَيْنَعَتِ الثِّمَارُ وَأَدْنَى الشَّجَرُ لِلْجَانِيْ جنَاَهُ؟", tr: "Wa aina‘atits-tsimāru wa adnan-syajaru lil-jānī janāh.", ket: "Buah-buahan segera menjadi masak, cabang dan dahannya melengkung dan merendah, memudahkan pemetik untuk memetiknya." },
                { ar: "وَ نَطَقَتْ بِحَمْلِهِ كُلُّ دَابَّةٍ لِقُرَيْشٍ بِفِصَاحِ الْأَلْسُنِ الْعَرَبِيَّةِ؟", tr: "Wa naṭaqat biḥamlihī kullu dābbatin li Quraisyin bifīṣāḥil alsunil ‘arabiyyah.", ket: "Dan seluruh binatang peliharaan suku Quraisy memperbincangkan hamilnya Āminah dengan ucapan yang fasih." },
                { ar: "وَ خَرَّتِ الْأَسِرَّةُ وَ الْأَصْنَامُ عَلَى الْوُجُوْهِ وَ الْأَفْوَاهُ؟", tr: "Wa kharratil asirratu wal aṣnāmu ‘alal wujūhi wal afwāh.", ket: "Dan seluruh singgasana kerajaan bergoncang, dan berhala-berhala pun terjungkal berantakan." },
                { ar: "وَ تَبَاشَرَتْ وُحُوْشُ الْمَشَارِقِ وَ الْمَغَارِبِ وَ دَوَابُّهَا الْبَحْرِيَّةُ؟", tr: "Wa tabāsyarat wuḥūsyul masyāriqi wal maghāribi wa dawābbuhal baḥriyyah.", ket: "Binatang-binatang liar di belahan bumi sebelah timur dan barat serta binatang laut pun ikut riang gembira." },
                { ar: "وَاحْتَسَتِ الْعَوَالِمُ مِنَ السُّرُوْرِ كَأْسَ حُمَيَّاهُ؟", tr: "Waḥtasatil ‘awālimu minas-surūri ka’sa ḥumayyāh.", ket: "Seluruh penghuni alam berpesta pora, bergembira bersama, mereguk berita gembira." },
                { ar: "وَ بُشِّرَتِ الْجِنُّ بِإِظْلَالِ زَمَنِهِ وَانْتَهَكَتِ الْكَهَانَةُ وَ رَهِبَتِ الرُّهْبَانِيَّةْ؟", tr: "Wa busyiratil jinnu bi iẓlāli zamanihī wantahakatil kahānatu wa rahibatir-rubbāniyyah.", ket: "Segenap bangsa jinn diberikan rasa kesenangan, sedangkan ahli nujum, tukang sihir, tertimpa kerusakan serta para pendeta Nashrani menjadi gentar hatinya, karena merasa ketakutan." },
                { ar: "وَ لَهِجَ بِخَبَرِهِ كُلُّ حِبْرٍ خَبِيْرٍ وَ فِيْ حُلَا حُسْنِهِ تَاهَ؟", tr: "Wa lahija bikhabarihī kullu ḥibrin khabīrin wa fī ḥulā ḥusnihī tāh.", ket: "Tetapi, orang-orang cerdik pandai yang telah mengerti tentang kehadiran Nabi akhir zaman dari kitab-kitab yang terdahulu, bertekun menceritakan kebaikan sifat-sifat Nabi ini." },
                { ar: "وَ اُتِيَتْ أُمُّهُ فِى الْمَنَامِ فَقِيْلَ لَهَا إِنَّكِ قَدْ حَمَلْتِ بِسَيِّدِ الْعَالَمِيْنَ وَ خَيْرِ الْبَرِيَّةِ؟", tr: "Wa utiyat ummuhū fil manāmi fa qīla lahā innaki qad ḥamalti bi sayyidil ‘ālamīna wa khairil bariyyah.", ket: "Ketika Āminah sedang tidur, ia bermimpi, ada suatu suara berkata: “Wahai Āminah, sesungguhnya engkau telah mengandung penghulu umat manusia seluruh dunia dan sebaik-baik makhluk." },
                { ar: "وَ سَمِّيْهِ إِذَا وَضَعْتِهِ مُحَمَّدًا لِأَنَّهُ سَتُحْمَدُ عُقْبَاهُ؟", tr: "Wa sammīhi idzā waḍa‘tihī Muḥammadan li’annahū satuḥmadu ‘uqbāh.", ket: "Bila engkau telah melahirkannya, berilah ia nama Muḥammad, karena kelak, ia akan terpuji." }
            ]
        },
        {
            judul: "Al Barjanji (Kelahiran Nabi)",
            isi: [
                { ar: "عَطِّرِاللّٰهُـمَّ قَبْرَهُ الْكَرِيْمِ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمٍ", tr: "‘Aththirillāhumma qabrahul karīm ۞ bi‘arfin syadziyyin min ṣalātin wa taslīm", ket: "Semoga Allah mengharumkan dan mewangikan kuburnya (Nabi) yang mulia, dengan keharuman wangi-wangian salawat dan salam sejahtera." },
                { ar: "بِسْمِ اللّٰهِ الرَّحْمنِ الرَّحِيْمِ", tr: "Bismillāhir-raḥmānir-raḥīm", ket: "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang." },
                { ar: "وَ لَمَّا تَمَّ مِنْ حَمْلِهِ شَهْرَانِ عَلٰى مَشْهُوْرِ الْأَقْوَالِ الْمَرْوِيَّةْ؟", tr: "Wa lammā tamma min ḥamlihī syahrāni ‘alā masyhūril aqwālil marwiyyah.", ket: "Ketika beliau dalam kandungan cukup sempurna dua bulan, menurut qaul yang masyhur yang telah diriwayatkan." },
                { ar: "تُوُفِّيَ بِالْمَدِيْنَةِ الْمُنَوَّرَةِ أَبُوْهُ عَبْدُ اللّٰهِ؟", tr: "Tuwuffiya bil-Madīnatil Munawwarati abūhu ‘Abdullāh.", ket: "Maka wafatlah ayahnya yang bernama ‘Abdullāh di kota Madīnah." },
                { ar: "وَ كَانَ قَدِ اجْتَازَ بِأَخْوَالِهِ بَنِيْ عَدِيٍّ مِنَ الطَّائِفَةِ النَّجَّارِيَّةِ؟", tr: "Wa kāna qadijtāza bi akhwālihī Banī ‘Adiyyin minaṭ-ṭā’ifatil Najjāriyyah.", ket: "Pada waktu itu ‘Abdullāh dalam perjalanan menuju saudara-saudara ibunya Bani ‘Adiy dari suku Najjār." },
                { ar: "وَ مَكَثَ فِيْهِمْ شَهْرًا سَقِيْمًا يُعَانُوْنَ سُقْمَهُ وَ شَكْوَاهُ؟", tr: "Wa makatsa fīhim syahran saqīman yu‘ānūna suqmahū wa syakwāh.", ket: "Di sana ‘Abdullāh tinggal bersama mereka selama satu bulan dalam keadaan sakit payah, di bawah perawatan mereka." },
                { ar: "وَ لَمَّا تَمَّ مِنْ حَمْلِهِ عَلَى الرَّاجِحِ تِسْعَةُ أَشْهُرٍ قَمَرِيَّةٍ؟", tr: "Wa lammā tamma min ḥamlihī ‘alar-rājiḥi tis‘atu asyhur qamariyyah.", ket: "Ketika beliau sudah cukup sempurna sembilan bulan dalam kandungan menurut pendapat yang rajih." },
                { ar: "وَاٰنَ لِلزَّمَانِ أَنْ يَنْجَلِيَ عَنْهُ صَدَاهُ؟", tr: "Wa āna liz-zamāni an yanjalī ‘anhu ṣadāh.", ket: "Dan sudah masanya beliau akan lahir." },
                { ar: "حَضَرَ أُمَّهُ لَيْلَةَ مَوْلِدِهِ آسِيَةُ وَ مَرْيَمُ فِيْ نِسْوَةٍ مِنَ الْحَظِيْرَةِ الْقُدْسِيَّةِ؟", tr: "Ḥaḍara ummahū lailata maulidihī Āsiyatu wa Maryamu fī niswatin minal ḥaẓīratil qudsiyyah.", ket: "Maka pada malam itu, datanglah Siti Āsiah dan Siti Maryam beserta para pengiringnya, terdiri daripada bidadari-bidadari dari surga berkunjung kepada Āminah." },
                { ar: "وَ أَخَذَهَا الْمَخَاضُ فَوَلَدَتْهُ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ نُوْرًا يَتَلَأْلَأُ سَنَاهُ؟", tr: "Wa akhadzahal makhāḍu fa waladathu ṣallallāhu ‘alaihi wa sallama nūran yatala’la’u sanāh.", ket: "Dan tak lama kemudian, ibunya bersalin, dan lahirlah Muḥammad s.a.w. dengan bercahaya yang sangat cemerlang, sehingga memenuhi seluruh angkasa raya." },
                { ar: "وَ مُحَيًّا كَالشَّمْسِ مِنْكَ مُضِيْءٌ؟", tr: "Wa muḥayyan kasy-syamsi minka muḍī’.", ket: "Wajahnya bagaikan matahari yang bersinar terang." },
                { ar: "أَسْفَرَتْ عَنْهُ لَيْلَةٌ غَرَّاءُ؟", tr: "Asfarat ‘anhu lailatun gharra’.", ket: "Cahayanya laksana bulan purnama." },
                { ar: "لَيْلَةُ الْمَوْلِدِ الَّذِيْ كَانَ لِلدِّيْنِ سُرُوْرٌ بِيَوْمِهِ وَازْدِهَاءُ؟", tr: "Lailatul maulidil-ladzī kāna lid-dīni surūrun bi yaumihī wazdihā’.", ket: "Malam kelahiran, bagi orang yang beragama menjadikan kegembiraan dan kemegahan pada hari siangnya." },
                { ar: "يَوْمَ نَالَتْ بِوَضْعِهِ ابْنَةُ وَهَبٍ مِنْ فَخَارٍ مَا لَمْ تَنَلْهُ النّسَاءُ؟", tr: "Yauma nālat bi waḍ‘ihibnatu Wahbin min fakhārin mā lam tanalhun-nisā’.", ket: "Kelahiran beliau merupakan hari kejayaan yang diperoleh Āminah, kejayaan yang belum pernah diperoleh wanita-wanita lain." },
                { ar: "وَ أَتَتْ قَوْمَهَا بِأَفْضَلَ مِمَّا حَمَلَتْ قَبْلُ مَرْيَمُ الْعَذْرَاءُ؟", tr: "Wa atat qaumahā bi afḍala mimmā ḥamalat qablu Maryamul ‘adzrā’.", ket: "Putra yang dilahirkannya adalah lebih utama daripada putra yang dikandung Maryam, yang lahir sebelum itu." },
                { ar: "مَوْلِدٌ كَانَ مِنْهُ فِيْ طَالِعِ الْكُفْرِ وَ بَالٌ عَلَيْهِمُ وَ وَبَاءُ؟", tr: "Maulidun kāna minhu fī ṭāli‘il kufri wabālun ‘alaihimu wa wabā’.", ket: "Hari kelahiran beliau pada pandangan orang kafir merupakan suatu bencana dan malapetaka baginya." },
                { ar: "وَ تَوَالَتْ بُشْرَى الْهَوَاتِفِ أَنْ قَدْ وُلِدَ الْمُصْطَفَى وَ حَقَّ الْهَنَاءُ؟", tr: "Wa tawālat busyral hawātifi an qad wulidal muṣṭafā wa ḥaqqal hanā’.", ket: "Suara-suara berita gembira terus mengalir bahwasanya telah lahir nabi pilihan dan harus bersukaria." },
                { ar: "هٰذَا وَ قَدِ اسْتَحْسَنَ الْقِيَامَ عِنْدَ ذِكْرِ مَوْلِدِهِ الشَّرِيْفِ أَئِمَّةٌ ذَوُوْا رِوَايَةٍ وَ رَوِيَّةٍ؟", tr: "Hādzā wa qad istaḥsanal qiyāma ‘inda dzikri maulidihisy-syarīfi a’immatun dzawū riwāyatin wa rawiyyah.", ket: "Di sini, sebaiknya para hadirin berdiri, pada saat diceriterakan tentang kelahiran beliau. Demikianlah menurut riwayat ‘Ulamā’ Mutaqaddimīn." },
                { ar: "فَطُوْبَى لِمَنْ كَانَ تَعْظِيْمُهُ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ غَايَةَ مَرَامِهِ وَ مَرْمَاهُ؟", tr: "Fa ṭūbā liman kāna ta‘ẓīmuhū ṣallallāhu ‘alaihi wa sallama ghāyata marāmihī wa marmāh.", ket: "Berbahagialah, bagi orang yang memiliki hasrat menghormati lahirnya Nabi s.a.w." }
            ]
        },
        {
            judul: "Al Barjanji (Kelahiran & Masa Kecil)",
            isi: [
                { ar: "عَطِّرِاللّٰهُـمَّ قَبْرَهُ الْكَرِيْمِ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمٍ", tr: "‘Aththirillāhumma qabrahul karīm ۞ bi‘arfin syadziyyin min ṣalātin wa taslīm", ket: "Semoga Allah mengharumkan dan mewangikan kuburnya (Nabi) yang mulia, dengan keharuman wangi-wangian salawat dan salam sejahtera." },
                { ar: "بِسْمِ اللّٰهِ الرَّحْمنِ الرَّحِيْمِ", tr: "Bismillāhir-raḥmānir-raḥīm", ket: "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang." },
                { ar: "وَ بَرَزَ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ وَاضِعًا يَّدَيْهِ عَلَى الْأَرْضِ رَافِعًا رَأْسَهُ إِلَى السَّمَاءِ الْعَلِيَّةِ؟", tr: "Wa baraza ṣallallāhu ‘alaihi wa sallama wāḍi‘ay yadayhi ‘alal arḍi rāfi‘ar ra’sahū ilas-samā’il ‘aliyyah.", ket: "Nabi Muḥammad s.a.w. lahir dalam posisi telungkup, dengan meletakkan dua belah tangannya di permukaan bumi dan mengangkat kepalanya menengadah ke langit yang tinggi." },
                { ar: "مُوْمِيًا بِذٰلِكَ الرَّفْعِ إِلَى سُوْدَدِهِ وَعُلَاهُ؟", tr: "Mūmiyan bidzālikar-raf‘i ilā sūdadihī wa ‘ulāh.", ket: "Ini merupakan suatu lambang keagungan dan ketinggian martabatnya." },
                { ar: "وَ مُشِيْرًا إِلٰى رِفْعَةِ قَدْرِهِ عَلٰى سَائِرِ الْبَرِيَّةِ؟", tr: "Wa musyīran ilā rif‘ati qadrihī ‘alā sā’iril bariyyah.", ket: "Dan menunjukkan kepada ketinggian derajatnya melebihi seluruh manusia." },
                { ar: "وَ أَنَّهُ الْحَبِيْبُ الَّذِيْ حَسُنَتْ طِبَاعُهُ وَ سَجَايَاهُ؟", tr: "Wa annahul ḥabībul-ladzī ḥasunat ṭibā‘uhū wa sajāyāh.", ket: "Bahwasanya dia adalah kekasih Allah yang bagus watak dan budi pekertinya." },
                { ar: "وَ دَعَتْ أُمُّهُ عَبْدَ الْمُطَّلِبِ وَ هُوَ يَطُوْفُ بِهَاتِيْكَ الْبَنِيَّةِ؟", tr: "Wa da‘at ummuhū ‘Abdal Muṭṭhalibi wa huwa yaṭūfu bi hātīkal baniyyah.", ket: "Dan ibunya memanggil ‘Abd-ul-Muththalib, yang ketika itu sedang melakukan tawaf mengelilingi Ka‘bah." },
                { ar: "فَأَقْبَلَ مُسْرِعًا وَ نَظَرَ إِلَيْهِ وَ بَلَغَ مِنَ السُّرُوْرِ مُنَاهُ؟", tr: "Fa aqbala musri‘an wa naẓara ilaihi wa balagha minas-surūri munāh.", ket: "Lalu dia segera menghadap dan melihatnya dengan rasa hati yang bergembira." },
                { ar: "وَ أَدْخَلَهُ الْكَعْبَةَ الْغَرَّاءَ وَ قَامَ يَدْعُوْ بِخُلُوْصِ النِّيَّةِ؟", tr: "Wa adkhalahul ka‘batal gharrā’a wa qāma yad‘ū bikhulūṣin-niyyah.", ket: "Muḥammad s.a.w. dibawanya masuk ke dalam Ka‘bah, seraya memanjatkan doa dengan niat hati yang setulusnya." },
                { ar: "وَ يَشْكُرُ اللّٰهَ تَعَالَى عَلَى مَا مَنَّ بِهِ عَلَيْهِ وَ أَعْطَاهُ؟", tr: "Wa yasykurullāha ta‘ālā ‘alā mā manna bihī ‘alaihi wa a‘ṭāh.", ket: "Dan dia lalu bersyukur kepada Allah ta‘ālā atas anugerah yang baru diterimannya itu." },
                { ar: "وَ وُلِدَ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ نَظِيْفًا مَخْتُوْنًا مَقْطُوْعَ السُّرِّ بِيَدِ الْقُدْرَةِ الْإِلٰهِيَّةِ؟", tr: "Wa wulida ṣallallāhu ‘alaihi wa sallama naẓīfan makhtūnan maqṭū‘as-surri bi yadil qudratil ilāhiyyah.", ket: "Muḥammad s.a.w. dilahirkan dalam keadaan sudah bersih, sudah dikhitan dan sudah putus pusarnya dengan kekuasaan Allah." },
                { ar: "طَيِّبًا دَهِيْنًا مَكْحُوْلَةً بِكُحْلِ الْعِنَايَةِ عَيْنَاهُ؟", tr: "Ṭayyiban dahīnan makḥūlatan bikuḥlil ‘ināyati ‘aināh.", ket: "Harum wangi bau kasturi, dan bercelak dua belah matanya." },
                { ar: "وَقِيْلَ خَتَنَهُ جَدُّهُ بَعْدَ سَبْعِ لَيَالٍ سَوِيَّةٍ؟", tr: "Wa qīla khatanahū jadduhū ba‘da sab‘i layālin sawiyyah.", ket: "Ada riwayat yang mengatakan, bahwa dia dikhitankan kakeknya sesudah malam yang ketujuh." },
                { ar: "وَ أَوْلَمَ وَ أَطْعَمَ وَ سَمَّاهُ مُحَمَّدًا وَ أَكْرَمَ مَثْوَاهُ؟", tr: "Wa aulama wa aṭ‘ama wa sammāhu Muḥammadan wa akrama matswāh.", ket: "Dengan mengadakan walimah dan jamuan makan, dan menamakannya dengan nama Muḥammad, serta memuliakan derajatnya yang tinggi." }
            ]
        },
        {
            judul: "Al Barjanji (Peristiwa Ajaib Kelahiran Nabi)",
            isi: [
                { ar: "عَطِّرِاللّٰهُـمَّ قَبْرَهُ الْكَرِيْمِ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمٍ", tr: "‘Aththirillāhumma qabrahul karīm ۞ bi‘arfin syadziyyin min ṣalātin wa taslīm", ket: "Semoga Allah mengharumkan dan mewangikan kuburnya (Nabi) yang mulia, dengan keharuman wangi-wangian salawat dan salam sejahtera." },
                { ar: "بِسْمِ اللّٰهِ الرَّحْمنِ الرَّحِيْمِ", tr: "Bismillāhir-raḥmānir-raḥīm", ket: "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang." },
                { ar: "وَ ظَهَرَ عِنْدَ وِلَادَتِهِ خَوَارِقُ وَ غَرَائِبُ غَيْبِيَّةٌ؟", tr: "Wa ẓahara ‘inda wilādatihī khawāriqu wa gharā’ibu ghaibiyyah.", ket: "Pada waktu kelahiran Nabi s.a.w., terjadilah berbagai hal yang luar biasa, dan keanehan-keanehan yang bersifat ghaib." },
                { ar: "إِرْهَاصًا لِنُبُوَّتِهِ وَ إِعْلَامًا بِأَنَّهُ مُخْتَارُ اللّٰهِ تَعَالَى وَ مُجْتَبَاهُ؟", tr: "Irhāṣan li nubuwwatihī wa i‘lāman bi annahū mukhtārullāhi ta‘ālā wa mujtabāh.", ket: "Sebagai pertanda ketetapan kenabiannya, dan pemberitahuan bahwa beliau adalah sebagai Nabi pilihan Allah ta‘ālā." },
                { ar: "فَزِيْدَتِ السَّمَاءِ حِفْظًا وَ رُدَّ عَنْهَا الْمَرَدَةُ وَ ذَوُوا النُّفُوْسِ الشَّيْطَانِيَّةِ؟", tr: "Fa zīdatis-samā’i ḥifẓan wa rudda ‘anhā maradatu wa dzawun-nufūsisy-syaiṭāniyyah.", ket: "Maka pada waktu itu, langit ditingkatkannya penjagaannya dan semua pendurhaka dan pengacau dari makhluk-makhluk halus bangsa jinn dan syaithan, diusir dari langit." },
                { ar: "وَ رَجَمَتْ نُجُوْمُ النَّيِّرَاتِ كُلَّ رَجِيْمٍ فِيْ حَالِ مَرْقَاهُ؟", tr: "Wa rajamat nujūmun nayyirāti kulla rajīmin fī ḥāli marqāh.", ket: "Bintang-bintang berapi menghantam syaithan-syaithan yang memaksakan diri hendak naik ke atas." },
                { ar: "وَ تَدَلَّتْ إِلَيْهِ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ الْأَنْجُمُ الزُّهْرِيَّةُ؟", tr: "Wa tadallat ilaihi ṣallallāhu ‘alaihi wa sallamal anjumuz-zuhriyyah.", ket: "Bintang-bintang Zuhrah merendah ikut menghormati beliau s.a.w." },
                { ar: "وَاسْتَنَارَتْ بِنُوْرِهَا وِهَادُ الْحَرَمِ وَرُبَاهُ؟", tr: "Wastanārat binūrihā wihādul ḥarami wa rubāh.", ket: "Dan memancarkan sinarnya yang terang cemerlang sampai ke dataran rendah bumi haram dan dataran tingginya." },
                { ar: "وَ خَرَجَ مَعَهُ نُوْرٌ أَضَاءَتْ لَهُ قُصُوْرُ الشَّامِ الْقَيْصَرِيَّةِ؟", tr: "Wa kharaja ma‘ahū nūrun aḍā’at lahū quṣūrusy-syāmil qaiṣariyyah.", ket: "Dan bersamaan dengan itu keluarlah cahaya yang menerangi gedung-gedung bertingkat di negeri Syām." },
                { ar: "فَرَاٰهَا مَنْ بِبِطَاحِ مَكَّةَ دَارُهُ وَ مَغْنَاهُ؟", tr: "Fa ra’āhā man bibiṭāḥi makkata dāruhū wa maghnāh.", ket: "Sehingga seluruh penduduk kota Makkah dapat menyaksikannya." },
                { ar: "وَانْصَدَعَ الْإِيْوَانُ بِالْمَدَآئِنِ الْكِسْرَوِيَّةِ؟", tr: "Wanṣada‘al īwānu bil madā’inil kisrawiyyah.", ket: "Seluruh pendapa istana di kerajaan Kisra luluh lantak berserakan." },
                { ar: "اَلَّذِيْ رَفَعَ أَنُوْشَرْوَانَ سَمْكَهُ وَ سَوَّاهُ؟", tr: "Alladzī rafa‘a Anūsyarwāna samkahū wa sawwāh.", ket: "Yang telah dibangun dan ditinggikan oleh Anūsyarwān." },
                { ar: "وَ سَقَطَ أَرْبَعَ عَشْرَةَ مِنْ شُرُفَاتِهِ الْعُلْوِيَّةِ؟", tr: "Wa saqaṭa arba‘ata ‘asyrata min syurafātihil ‘ulwiyyah.", ket: "Empat belas menara tinggi yang menjulang ke angkasa runtuh berantakan." },
                { ar: "وَ كُسِرَ مُلْكُ كِسْرَى لِهَوْلِ مَا أَصَابَهُ وَ عَرَاهُ؟", tr: "Wa kusira mulku Kisrā lihauli mā aṣābahū wa ‘arāh.", ket: "Hancur luluhlah kemaharajaan Kaisar, karena tergoncang dengan kejadian besar kelahiran Nabi s.a.w." },
                { ar: "وَ خَمَدَتِ النِّيْرَانُ الْمَعْبُوْدَةُ بِالْمَمَالِكِ الْفَارِسِيَّةِ؟", tr: "Wa khamadatinnīrānul ma‘būdatu bil mamālikil fārisiyyah.", ket: "Semua api pemujaan di seluruh tanah jajahan Persi padam seketika." },
                { ar: "لِطُلُوْعِ بَدْرِهِ الْمُنِيْرِ وَ إِشْرَاقِ مُحَيَّاهُ؟", tr: "Liṭulū‘i badrihil munīri wa isyrāqi muḥayyāh.", ket: "Karena terbitnya purnama Muḥammad s.a.w. yang bersinar terang." },
                { ar: "وَ غَاضَتْ بُحَيْرَةُ سَاوَةَ وَ كَانَتْ بَيْنَ هَمَذَانَ وَ قُمَّ مِنَ الْبِلَادِ الْعَجَمِيَّةِ؟", tr: "Wa ghāḍat buḥairatu Sāwata wa kānat baina Hamadzāna wa Qumma minal bilādil ‘ajamiyyah.", ket: "Danau Sāwah terletak di antara kota Hamdān dan Qumma menjadi kering." },
                { ar: "وَ جَفَّتْ إِذْ كَفَّ وَاكِفُ مَوْجِهَا الثَّجَّاجَ يَنَابِيْعُ هَاتِيْكَ الْمِيَاهِ؟", tr: "Wa jaffat idz kaffa wākifu maujihas-tsajjāja yanābī‘u hātīkal miyāh.", ket: "Dan mata air yang biasa mengalirkan airnya tidak lagi mengalirkan air, karena dilanda kekeringan." },
                { ar: "وَ فَاضَ وَادِيْ سَمَاوَةَ وَ هِيَ مَفَازَةٌ فِيْ فَلَاةٍ وَ بَرِيَّةٍ؟", tr: "Wa fāḍa wādī Samāwata wa hiya mafāzatun fī falātin wa bariyyah.", ket: "Padahal lembah Samāwah pada padang belantara dan daratannya melimpah airnya." },
                { ar: "لَمْ يَكُنْ بِهَا قَبْلُ مَآءٌ يَنْقَعُ لِلظَّمْآنِ اللَّهَاةَ.", tr: "Lam yakun bihā qablu mā’un yanqa‘u liẓ-ẓam’ānil lahāh.", ket: "Padahal sejak dahulu kala di sana tidak terdapat air setetespun yang dapat menghilangkan haus anak lidah orang yang sedang dahaga." },
                { ar: "وَ كَانَ مَوْلِدُهُ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ بِالْمَوْضِعِ الْمَعْرُوْفِ بِالْعَرَاصِ الْمَكِّيَّةِ؟", tr: "Wa kāna mauliduhū ṣallallāhu ‘alaihi wa sallama bil mauḍi‘il ma‘rūfi bil ‘arāṣil makkiyyah.", ket: "Adapun tempat kelahiran Nabi s.a.w. adalah disebut tempat yang terkenal dengan nama kampung ‘Irāsh di Makkah." },
                { ar: "وَ الْبَلَدِ الَّذِيْ لَا يُعْضَدُ شَجَرُهُ وَ لَا يُخْتَلٰى خُلَاهُ؟", tr: "Wal baladil-ladzī lā yu‘ḍadu syajaruhū wa lā yukhtalā khulāh.", ket: "Yaitu kota yang kayunya haram ditebang dan rumputnya haram dicabut." },
                { ar: "وَاخْتُلِفَ فِيْ عَامِ وِلَادَتِهِ وَ فِيْ شَهْرِهَا وَ فِيْ يَوْمِهَا عَلٰٓى أَقْوَالٍ لِلْعُلَمَاءِ مَرْوِيَّةٍ؟", tr: "Wakhtulifa fī ‘āmi wilādatihī wa fī syahrihā wa fī yaumihā ‘alā aqwālin lil ‘ulamā’i marwiyyah.", ket: "Mengenai tahun, bulan dan hari kelahirannya, masih belum disepakati oleh ‘Ulama’ ahli riwayat." },
                { ar: "وَ الرَّاجِحُ أَنَّهَا قُبَيْلَ فَجْرِ يَوْمِ الْإِثْنَيْنِ ثَانِيَ عَشَرَ شَهْرِ رَبِيْعُ الْأَوَّلِ مِنْ عَامِ الْفِيْلِ الَّذِيْ صَدَّهُ اللّٰهُ عَنِ الْحَرَمِ وَ حَمَاهُ.", tr: "War-rājiḥu annahā qubaila fajri yaumil itsnaini tsāniya ‘asyara syahri Rabī‘il Awwali min ‘āmil fīlil-ladzī ṣaddahullāhu ‘anil ḥarami wa ḥamāh.", ket: "Tetapi, menurut qaul (pendapat) yang paling kuat adalah: Sebelum Shubuḥ pada hari Senin, tanggal 12 Rabī‘-ul-Awwal, tahun Gajah, yang pada tahun itu Allah menghalau pasukan gajah Raja Abrahah yang hendak menghancurkan Ka‘bah, dari tanah Makkah." }
            ]
        },
        {
            judul: "Al Barjanji (Masa Menyusui)",
            isi: [
                { ar: "عَطِّرِاللّٰهُـمَّ قَبْرَهُ الْكَرِيْمِ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمٍ", tr: "‘Aththirillāhumma qabrahul karīm ۞ bi‘arfin syadziyyin min ṣalātin wa taslīm", ket: "Semoga Allah mengharumkan dan mewangikan kuburnya (Nabi) yang mulia, dengan keharuman wangi-wangian salawat dan salam sejahtera." },
                { ar: "بِسْمِ اللّٰهِ الرَّحْمنِ الرَّحِيْمِ", tr: "Bismillāhir-raḥmānir-raḥīm", ket: "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang." },
                { ar: "وَ أَرْضَعَتْهُ أُمُّهُ أَيَّامًا ثُمَّ أَرْضَعَتْهُ ثُوَيْبَةُ الْأَسْلَمِيَّةُ؟", tr: "Wa arḍa‘athu ummuhū ayyāman tsumma arḍa‘athu Tsuwaibatul Aslamiyyah.", ket: "Beliau disusui oleh ibunya dalam waktu beberapa hari, lalu beliau disusui oleh Tsuwaibah al-Aslamiyyah." },
                { ar: "الَّتِيْ أَعْتَقَهَا أَبُوْ لَهَبٍ حِيْنَ وَافَتْهُ عِنْدَ مِيْلَادِهِ عَلَيْهِ الصَّلَاةُ وَ السَّلَامُ بِبُشْرَاهُ؟", tr: "Allatī a‘taqahā Abū Lahabin ḥīna wāfathu ‘inda mīlādihī ‘alaihiṣ-ṣalātu was-salāmu bi busyarāh.", ket: "Wanita yang dimerdekakan Abū Lahab, ketika dia didatangi Tsuwaibah dengan membawa kabar gembira tentang kelahiran beliau s.a.w." },
                { ar: "فَأَرْضَعَتْهُ مَعَ ابْنِهَا مَسْرُوْحٍ وَ أَبِيْ سَلَمَةَ وَ هِيَ بِهِ حَفِيَّةٌ؟", tr: "Fa arḍa‘athu ma‘abnihā Masrūḥin wa Abī Salamata wa hiya bihī ḥafiyyah.", ket: "Beliau disusui oleh Tsuwaibah yang bersamaan dengan menyusui anaknya sendiri yang bernama Masrūḥ dan Abū Salamah." },
                { ar: "وَ أَرْضَعَتْ قَبْلَهُ حَمْزَةَ الَّذِيْ حُمِدَ فِيْ نُصْرَةِ الدِّيْنِ سُرَاهُ؟", tr: "Wa arḍa‘at qablahū Ḥamzatal-ladzī ḥumida fī nuṣratid-dīni surāh.", ket: "Sedangkan sebelumnya, dia itu pernah menyusui Ḥamzah yang menjadi pembela agama Allah." },
                { ar: "وَ كَانَ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ يُبْعَثُ إِلَيْهَا مِنَ الْمَدِيْنَةِ بِصِلَةٍ وَ كِسْوَةٍ هِيَ بِهَا حَرِيَّةٌ؟", tr: "Wa kāna ṣallallāhu ‘alaihi wa sallama yub‘atsu ilaihā minal Madīnati bi ṣilatin wa kiswatin hiya bihā ḥariyyah.", ket: "Dan beliau ketika di Madīnah selalu mengirimkan barang hadiah dan barang pakaian kepada Tsuwaibah, ia bergembira sekali menerimanya." },
                { ar: "إِلٰٓى أَنْ أَوْرَدَ هَيْكَلَهَا رَآئِدُ الْمَنُوْنِ الضَّرِيْحَ وَ وَارَاهُ؟", tr: "Ilā an aurāda haikalahā rā’idul manūnil ḍarīḥa wa wārāh.", ket: "Hingga akhirnya Tsuwaibah menemui ajalnya dan dimakamkan." },
                { ar: "قِيْلَ عَلَى دِيْنِ قَوْمِهَا الْفِئَةِ الْجَاهِلِيَّةِ؟", tr: "Qīla ‘alā dīni qaumihal fi’atil jāhiliyyah.", ket: "Menurut sebagian keterangan, ada yang mengatakan bahwa Tsuwaibah meninggal dunia masih tetap menganut agama kaumnya yang Jahiliyyah." },
                { ar: "وَ قِيْلَ أَسْلَمَتْ أَثْبَتَ الْخِلَافَ ابْنُ مَنْدَهْ وَ حَكَاهُ؟", tr: "Wa qīla aslamat atsbatal khilāfa ibnu Mandah wa ḥakāh.", ket: "Dan menurut keterangan yang lain, bahwa ia (Tsuwaibah) telah menganut agama Islam. Perbedaan ini diriwayatkan oleh Ibnu Mandah." },
                { ar: "ثُمَّ أَرْضَعَتْهُ الْفَتَاةُ حَلِيْمَةُ السَّعْدِيَّةُ؟", tr: "Tsumma arḍa‘athul fatātu Ḥalīmatus-Sa‘diyyah.", ket: "Kemudian, beliau disusui oleh Ḥalīmah as-Sa‘diyyah." },
                { ar: "وَ كَانَ قَدْ رَدَّ كُلٌّ مِنَ الْقَوْمِ ثَدْيَهَا لِفَقْرِهَا وَ أَبَاهُ؟", tr: "Wa kāna qad radda kullun minal qaumi tsadyahā lifaqrihā wa abāh.", ket: "Oleh karena kemiskinannya, maka tak ada seorang pun yang menyusukan anaknya kepada Ḥalīmah as-Sa‘diyyah." },
                { ar: "فَأَخْصَبَ عَيْشُهَا بَعْدَ الْمَحْلِ قَبْلَ الْعَشِيَّةِ؟", tr: "Fa akhṣaba ‘aisyahā ba‘dal maḥli qablal ‘asyiyyah.", ket: "Semenjak Ḥalīmah menyusui beliau s.a.w., lalu menjadi lapang kehidupannya." },
                { ar: "وَ دَرَّ ثَدْيٰهَا بِدُرِّ دَرٍّ لَبَنَهُ الْيَمِيْنُ مِنْهُمَا وَ لَبَنَ الْآخَرُ أَخَاهُ؟", tr: "Wa darra tsadyāhā bidurri darrin labanahul yamīnu minhumā wa labanal ākharu akhāh.", ket: "Buah dadanya menjadi deras berisi air susu, yang sebelah kanan disediakan untuk Nabi s.a.w. dan yang lain untuk menyusukan saudara susuannya." },
                { ar: "وَ أَصْبَحَتْ بَعْدَ الْهُزَالِ وَ الْفَقْرِ غَنِيَّةً؟", tr: "Wa aṣbaḥat ba‘dal huzāli wal faqri ghaniyyah.", ket: "Akhirnya, Ḥalīmah menjadi orang yang kaya raya sesudah hidup dalam kemiskinan." },
                { ar: "وَ سَمِنَتِ الشَّارِفُ لَدَيْهَا وَ الشِّيَاهُ؟", tr: "Wa saminatisy-syārifu ladaihā wasy-syiyāh.", ket: "Unta dan kambingnya semuanya menjadi gemuk." },
                { ar: "وَ انْجَابَ عَنْ جَانِبِهَا كُلُّ مُلِمَّةٍ وَ رَزِيَّةٍ؟", tr: "Wanjāba ‘an jānibihā kullu mulimmatin wa raziyyah.", ket: "Dan segala marabahaya dan bencana yang berada di sekitarnya menjadi hilang lenyap." },
                { ar: "وَ طَرَّزَ السَّعْدُ بُرْدَ عَيْشِهَا الْهَنِيِّ وَ وَشَاهُ؟", tr: "Wa ṭarrazas-sa‘du burda ‘aisyahal haniyyi wa wasyāh.", ket: "Akhirnya Ḥalīmah menjadi seorang kaya raya dan terpuji." }
            ]
        },
        {
            judul: "Al Barjanji (Masa Pertumbuhan & Pembelahan Dada)",
            isi: [
                { ar: "عَطِّرِاللّٰهُـمَّ قَبْرَهُ الْكَرِيْمِ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمٍ", tr: "‘Aththirillāhumma qabrahul karīm ۞ bi‘arfin syadziyyin min ṣalātin wa taslīm", ket: "Semoga Allah mengharumkan dan mewangikan kuburnya (Nabi) yang mulia, dengan keharuman wangi-wangian salawat dan salam sejahtera." },
                { ar: "بِسْمِ اللّٰهِ الرَّحْمنِ الرَّحِيْمِ", tr: "Bismillāhir-raḥmānir-raḥīm", ket: "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang." },
                { ar: "وَ كَانَ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ يَشِبُّ فِي الْيَوْمِ شَبَابَ الصَّبِيِّ فِي الشَّهْرِ بِعِنَايَةٍ رَبَّانِيَّةٍ؟", tr: "Wa kāna ṣallallāhu ‘alaihi wa sallama yasyibbu fil yaumi syabābaṣ-ṣabiyyi fisy-syahri bi‘ināyatin rabbāniyyah.", ket: "Pertumbuhan Nabi s.a.w. dalam sehari sama seperti sebulan bagi anak-anak biasa. Hal yang semacam itu berkat mendapat pertolongan Allah ta‘ālā." },
                { ar: "فَقَامَ عَلَى قَدَمَيْهِ فِيْ ثَلَاثٍ وَ مَشٰى فِيْ خَمْسٍ، وَ قَوِيَتْ فِيْ تِسْعٍ مِنَ الشُّهُوْرِ بِفَصِيْحِ النُّطْقِ قُوَاهُ؟", tr: "Fa qāma ‘alā qadamaihi fī tsalātsin wa masyā fī khamsin, wa qawiyat fī tis‘in minasy-syuhūri bi faṣīḥin-nuṭqi quwāh.", ket: "Dalam usia tiga bulan, beliau sudah pandai berdiri tegak, dalam usia lima bulan sudah pandai berjalan sendiri, dan sesudah usia sembilan bulan berbicara dengan fasih." },
                { ar: "وَ شَقَّ الْمَلَكَانِ صَدْرَهُ الشَّرِيْفَ لَدَيْهَا وَ أَخْرَجَا مِنْهُ عَلَقَةً دَمَوِيَّةً؟", tr: "Wa syaqqal malakāni ṣadrahuy-syarīfa ladaihā wa akhrajā minhu ‘alaqatan damawiyyah.", ket: "Dan pada suatu ketika beliau didatangi dua malaikat yang membelah dadanya dan membuang darah-darah hitamnya." },
                { ar: "وَ أَزَالَا مِنْهُ حَظَّ الشَّيْطَانِ وَ بِالثَّلْجِ غَسَلَاهُ؟", tr: "Wa azālā minhu ḥaẓẓasy-syaiṭāni wa bits-tsalji ghasalāh.", ket: "Dan menghilangkan tempat syaithan bersamayam, dan membasuhnya dengan es." },
                { ar: "وَ مَلَاٰهُ حِكْمَةً وَّ مَعَانِيَ إِيْمَانِيَّةً؟", tr: "Wa malā’hu ḥikmatan wa ma‘āniya īmāniyyah.", ket: "Seterusnya diisi dengan hikmah dan rahasia-rahasia iman." },
                { ar: "ثُمَّ خَاطَاهُ وَ بِخَاتَمِ النُّبُوَّةِ خَتَمَاهُ؟", tr: "Tsumma khāṭāhu wa bi khātamin-nubuwwati khatamāh.", ket: "Kemudian mengatupkannya kembali seperti semula, lalu dicap dengan tanda kenabian." },
                { ar: "وَ وَزَنَاهُ فَرَجَحَ بِأَلْفٍ مِنْ أُمَّتِهِ أُمَّةِ الْخَيْرِيَّةِ؟", tr: "Wa wazanāhu fa rajaḥa bi alfim min ummatihī ummatil khairiyyah.", ket: "Lalu Beliau s.a.w. ditimbang dan dibandingkan hasilnya, ternyata berat keluhurannya dapat melebihi seribu orang pilihan dari umatnya." },
                { ar: "وَ نَشَأَ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ عَلٰى أَكْمَلِ الْأَوْصَافِ مِنْ حَالِ صِبَاهُ؟", tr: "Wa nasya’a ṣallallāhu ‘alaihi wa sallama ‘alā akmaliṣ-ṣifāti min ḥāli ṣibāh.", ket: "Semenjak kecil Beliau s.a.w. dibesarkan dengan sifat-sifat yang lebih sempurna dari lainnya." },
                { ar: "ثُمَّ رَدَّتْهُ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ إِلَى أُمِّهِ وَ هِيَ بِهِ غَيْرُ سَخِيَّةٍ؟", tr: "Tsumma raddathu ṣallallāhu ‘alaihi wa sallama ilā ummihī wa hiya bihī ghairu sakhiyyah.", ket: "Dengan rasa berat hati, Ḥalīmah lalu menyerahkannya kembali kepada ibunya sendiri." },
                { ar: "حَذَرًا مِنْ أَنْ يُصَابَ بِمَصَابِ حَادِثٍ تَخْشَاهُ؟", tr: "Ḥadzaran min an yuṣāba bimaṣābi ḥāditsin takhsyāh.", ket: "Karena rasa khawatir, apabila terjadi sesuatu musibah yang menimpa diri Muḥammad." },
                { ar: "وَ وَفَدَتْ عَلَيْهِ حَلِيْمَةُ فِيْ أَيَّامِ خَدِيْجَةَ السَّيِّدَةِ الْوَضِيَّةِ؟", tr: "Wa wafadat ‘alaihi Ḥalīmatun fī ayyāmi Khadījatas-sayyidatil waḍiyyah.", ket: "Dan tatkala Beliau s.a.w. sudah nikah dengan Sayyidah Khadījah, Ḥalīmah baru dapat berkunjung kembali kepada beliau." },
                { ar: "فَحَبَاهَا مِنْ حَبَآئِهِ الْوَافِرُ بِحِبَاهُ؟", tr: "Fa ḥabāhā min ḥabā’ihil wāfiru biḥibāh.", ket: "Lalu Beliau s.a.w. juga memberikan hadiah yang cukup berharga kepadanya (Ḥalīmah)." },
                { ar: "وَ قَدِمَتْ عَلَيْهِ يَوْمَ حُنَيْنٍ فَقَامَ إِلَيْهَا وَ أَخَذَتْهُ الْأَرْيَحِيَّةُ؟", tr: "Wa qadimat ‘alaihi yauma Ḥunainin fa qāma ilaihā wa akhadzat-hul aryaḥiyyah.", ket: "Dan ketika terjadi peristiwa perang Ḥunain, Ḥalīmah sempat berkunjung lagi kepada Beliau. Kedatangan Ḥalīmah disambut oleh Beliau s.a.w. dengan segala rasa hormat dan penuh gembira." },
                { ar: "وَ بَسَطَ لَهَا مِنْ رِدَائِهِ الشَّرِيْفِ بِسَاطَ بِرِّهِ وَ نَدَاهُ؟", tr: "Wa basaṭa lahā min ridā’ihisy-syarīfi bisāṭa birrihī wa nadāh.", ket: "Lalu Beliau s.a.w. membentangkan tikar kambalnya yang bagus kepadanya." },
                { ar: "وَ الصَّحِيْحُ أَنَّهَا أَسْلَمَتْ مَعَ زَوْجِهَا وَ الْبَنِيْنَ وَ الذُّرِّيَّةِ؟", tr: "Waṣ-ṣaḥīḥu annahā aslamat ma‘a zaujihā wal banīna wadz-dzurriyyah.", ket: "Menurut pendapat yang shaḥīḥ, sesungguhnya Ḥalīmah masuk agama Islam bersama suaminya dan anak-anaknya serta seluruh keluarganya." },
                { ar: "وَ قَدْ عَدَّهُمَا فِي الصَّحَابَةِ جَمْعٌ مِنْ ثِقَاتِ الرُّوَاةِ؟", tr: "Wa qad ‘addahumā fiṣ-ṣaḥābati jam‘un min tsiqātir-ruwāh.", ket: "Bahkan menurut segolongan para rawi yang dapat dipercaya, bahwa kedua suami istri itu termasuk golongan para sahabat." }
            ]
        },
        {
            judul: "Al Barjanji (Masa Kecil & Perjalanan ke Syam)",
            isi: [
                { ar: "عَطِّرِاللّٰهُـمَّ قَبْرَهُ الْكَرِيْمِ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمٍ", tr: "‘Aththirillāhumma qabrahul karīm ۞ bi‘arfin syadziyyin min ṣalātin wa taslīm", ket: "Semoga Allah mengharumkan dan mewangikan kuburnya (Nabi) yang mulia, dengan keharuman wangi-wangian salawat dan salam sejahtera." },
                { ar: "بِسْمِ اللّٰهِ الرَّحْمنِ الرَّحِيْمِ", tr: "Bismillāhir-raḥmānir-raḥīm", ket: "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang." },
                { ar: "وَ لَمَّا بَلَغَ عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ أَرْبَعَ سِنِيْنَ خَرَجَتْ بِهِ أُمُّهُ إِلَى الْمَدِيْنَةِ النَّبَوِيَّةِ؟", tr: "Wa lammā balagha ‘alaihiṣ-ṣalātu was-salāmu arba‘a sinīna kharajat bihī ummuhū ilal Madīnatil Nabawiyyah.", ket: "Ketika Beliau s.a.w. telah berusia empat tahun, Beliau dibawa oleh ibunya ke Madīnah." },
                { ar: "ثُمَّ عَادَتْ فَوَافَتْهَا بِالْأَبْوَاءِ أَوْ بِشِعْبِ الْحَجُوْنِ الْوَفَاةُ؟", tr: "Tsumma ‘ādat fa wāfathā bil Abwā’i au bi syi‘bil Ḥajūnil wafāh.", ket: "Ketika dalam perjalanan pulang, lalu ibunya wafat di kota Abwā’ atau Ḥajūn." },
                { ar: "فَحَمَلَتْهُ حَاضِنَتُهُ أُمُّ أَيْمَنَ الْحَبَشِيَّةُ؟", tr: "Fa ḥamalathu ḥāḍinatuhū Ummu Aimanil Ḥabasyiyyah.", ket: "Kemudian Beliau dibawa pulang oleh Ummu Aiman, dan Beliau lalu diasuh olehnya." },
                { ar: "الَّتِيْ زَوَّجَهَا بَعْدُ مِنْ زَيْدِ بْنِ حَارِثَةَ مَوْلَاهُ؟", tr: "Allatī zauwajahā ba‘du min Zaidibni Ḥāritsata maulāh.", ket: "Yang kelak (sesudah beliau menjadi nabi), Ummu Aiman dikawinkan dengan Zaid bin Ḥāritsah, hamba yang telah Beliau merdekakan." },
                { ar: "وَ أَدْخَلَتْهُ عَلَى جَدِّهِ عَبْدِ الْمُطَّلِبِ فَضَمَّهُ إِلَيْهِ وَ رَقَّ لَهُ وَ أَعْلَا رُقِيَّهُ؟", tr: "Wa adkhalathu ‘alā jaddihī ‘Abdil Muṭṭhalibi fa ḍammahū ilaihi wa raqqa lahū wa a‘lā ruqiyyah.", ket: "Sesungguhnya di Makkah, Beliau s.a.w. diserahkan kepada kakeknya, ‘Abd-ul-Muththalib. ‘Abd-ul-Muththalib menerimanya dengan rasa penuh kasih-sayang dan dijaga keluhuran pribadinya." },
                { ar: "وَ قَالَ إِنَّ لِابْنِيْ هذَا شَأْنًا عَظِيْمًا، فَبَخٍ بَخٍ لِمَنْ وَقَّرَهُ وَ وَالَاهُ؟", tr: "Wa qāla inna libnī hādzā sya’nan ‘aẓīman, fa bakhin bakhin liman waqqarahū wa wālāh.", ket: "Berkatalah ‘Abd-ul-Muththalib seraya memeluk Muḥammad s.a.w.: “Cucuku ini benar-benar mempunyai urusan yang besar, beruntung sekali orang yang memuliakan dan mengasihinya.”" },
                { ar: "وَ لَمْ تَشْكُ فِيْ صَبَاهُ جُوْعًا وَ لَا عَطَشًا قَطُّ نَفْسُهُ الْأَبِيَّةُ؟", tr: "Wa lam tasyku fī ṣabāhu jū‘an wa lā ‘aṭasyan qaṭṭu nafsuhul abiyyah.", ket: "Semasa kecilnya, Beliau s.a.w. tidak pernah mengeluh lapar dan dahaga kepada orang lain." },
                { ar: "وَ كَثِيْرًا مَا غَذَى فَاغْتَذٰى بِمَآءِ زَمْزَمَ فَأَشْبَعَهُ وَ أَرْوَاهُ؟", tr: "Wa katsīran mā ghaddzā faghtadzā bimā’i Zamzama fa asyba‘ahū wa arwāh.", ket: "Seringkali di waktu pagi Beliau s.a.w. hanya meminum air zamzam yang bagi beliau sudah cukup dapat mengenyangkan memuaskan dahaganya." },
                { ar: "وَ لَمَّا أُنِيْخَتْ بِفِنَاءِ جَدِّهِ عَبْدِ الْمُطَّلِبِ مَطَايَا الْمَنِيَّةِ؟", tr: "Wa lammā unīkhat bi finā’i jaddihī ‘Abdil Muṭṭhalibi maṭāyal maniyyah.", ket: "Dan tatkala Beliau s.a.w. sudah ditinggal mati oleh ‘Abd-ul-Muththalib." },
                { ar: "كَفَلَهُ عَمُّهُ أَبُوْ طَالِبٍ شَقِيْقٌ أَبِيْهِ عَبْدِ اللّٰهِ؟", tr: "Kafalahū ‘ammuhū Abū Thālibin syaqīqu abīhi ‘Abdillāh.", ket: "Maka Beliau s.a.w. diasuh oleh pamannya Abū Thālib, yaitu adik dari ayahnya, yang bernama ‘Abdullāh." },
                { ar: "فَقَامَ بِكَفَالَتِهِ بِعَزْمٍ قَوِيٍّ وَ هِمَّةٍ وَ حَمِيَّةٍ؟", tr: "Fa qāma bi kafālatihī bi ‘azmin qawiyyin wa himmatin wa ḥamiyyah.", ket: "Pamannya sendiri, selama mengasuh Beliau s.a.w. itu dengan penuh semangat dan cita-cita, serta melindungi." },
                { ar: "وَ قَدَّمَهُ عَلَى النَّفْسِ وَ الْبَنِيْنَ وَ رَبَّاهُ؟", tr: "Wa qaddamahū ‘alan-nafsi wal banīna wa rabbāh.", ket: "Bahkan kepentingan Beliau s.a.w. lebih diutamakan daripada kepentingan dirinya sendiri dan anak-anaknya." },
                { ar: "وَ لَمَّا بَلَغَ إِثْنَى عَشَرَ سَنَةً رَحَلَ بِهِ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ عَمُّهُ أَبُوْ طَالِبٍ إِلَى الْبِلَادِ الشَّامِيَّةِ؟", tr: "Wa lammā balagha itsnā ‘asyrata sanatan raḥala bihī ṣallallāhu ‘alaihi wa sallama ‘ammuhū Abū Thālibin ilal bilādisy-syāmiyyah.", ket: "Ketika Beliau s.a.w. berumur dua belas tahun, maka beliau diajak pamannya berangkat ke negara Syām." },
                { ar: "وَ عَرَفَهُ الرَّاهِبُ بَحِيْرَا بِمَا حَازَهُ مِنْ وَصْفِ النُّبُوَّةِ وَ حَوَاهُ؟", tr: "Wa ‘arafahur-rāhibu Baḥīrā bimā ḥāzahū min waṣfin-nubuwwati wa ḥawāh.", ket: "Lalu pendeta Buḥairā mengenalinya dari tanda-tanda kenabian pada diri Beliau s.a.w." },
                { ar: "وَ قَالَ إِنِّيْ أُرَاهُ سَيِّدَ الْعَالَمِيْنَ وَ رَسُوْلَ اللّٰهِ وَ نَبِيَّهُ؟", tr: "Wa qāla innī arāhu sayyidal ‘ālamīna wa Rasūlallāhi wa nabiyyah.", ket: "Pendeta itu berkata kepada Abū Thālib: “Saya tahu persis tentang anak ini, Dia kelak akan menjadi Penghulu seluruh alam ini, akan menjadi Rasūlullāh dan Nabi-Nya.”" },
                { ar: "قَدْ سَجَدَ لَهُ الشَّجَرُ وَ الْحَجَرُ وَ لَا يَسْجُدَانِ إِلَّا نَبِيٍّ أَوَّاهٍ؟", tr: "Qad sajada lahuy-syajaru wal ḥajaru wa lā yasjudāni illā nabiyyin awwāh.", ket: "Buktinya, semua batu dan pepohonan tunduk takluk, semuanya bersujud kepadanya. Hal seperti ini hanya terjadi terhadap diri seorang Nabi yang sangat lembut hatinya." },
                { ar: "وَ إِنَّا لَنَجِدُ نَعْتَهُ فِي الْكُتُبِ الْقَدِيْمَةِ السَّمَاوِيَّةِ؟", tr: "Wa innā lanajidu na‘tahū fil kutubil qadīmatis-samāwiyyah.", ket: "Sesungguhnya kami telah menemukan sifat-sifatnya pada kitab-kitab Samāwi yang terdahulu." },
                { ar: "وَ بَيْنَ كَتِفَيْهِ خَاتَمُ النُّبُوَّةِ قَدْ عَمَّهُ النُّوْرُ وَ عَلَاهُ؟", tr: "Wa baina katifaihi khātamun-nubuwwati qad ‘ammahun-nūru wa ‘alāh.", ket: "Dan di antara dua tulang belikatnya ada tanda Cap Kenabian yang diliputi dengan cahaya terang." },
                { ar: "وَ أَمَرَ عَمَّهُ بِرَدِّهِ إِلَى مَكَّةَ تَخَوُّفًا عَلَيْهِ مِنْ أَهْلِ دِيْنِ الْيَهُوْدِيَّةِ؟", tr: "Wa amara ‘ammahū biraddihī ilā Makkata takhawwufan ‘alaihi min ahlidīnil yahūdiyyah.", ket: "Pendeta itu, menyuruh Abū Thālib, agar beliau s.a.w. segera dibawa pulang ke Makkah, karena dikhawatirkan ancaman orang-orang kafir Yahudi." },
                { ar: "فَرَجَعَ بِهِ وَ لَمْ يُجَاوِزْ مِنَ الشَّامِ الْمُقَدَّسِ بُصْرَاهُ؟", tr: "Fa raja‘a bihī wa lam yujāwiz minasy-syāmil muqaddasi buṣrāh.", ket: "Lalu Abū Thālib pulang dengan membawa Beliau sebelum sampai ke negeri Syām yang suci." }
            ]
        },
        {
            judul: "Al Barjanji (Perdagangan & Pernikahan)",
            isi: [
                { ar: "عَطِّرِاللّٰهُـمَّ قَبْرَهُ الْكَرِيْمِ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمٍ", tr: "‘Aththirillāhumma qabrahul karīm ۞ bi‘arfin syadziyyin min ṣalātin wa taslīm", ket: "Semoga Allah mengharumkan dan mewangikan kuburnya (Nabi) yang mulia, dengan keharuman wangi-wangian salawat dan salam sejahtera." },
                { ar: "بِسْمِ اللّٰهِ الرَّحْمنِ الرَّحِيْمِ", tr: "Bismillāhir-raḥmānir-raḥīm", ket: "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang." },
                { ar: "وَ لَمَّا بَلَغَ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ خَمْسًا وَ عِشْرِيْنَ سَنَةً سَافَرَ إِلَى بُصْرَى فِيْ تِجَارَةٍ لِخَدِيْجَةَ الْفَتِيَّةِ؟", tr: "Wa lammā balagha ṣallallāhu ‘alaihi wa sallama khamsan wa ‘isyrīna sanatan sāfara ilā Buṣrā fī tijāratin li Khadījatal fatiyyah.", ket: "Ketika Beliau s.a.w. genap berusia dua puluh lima tahun, maka Beliau pergi berdagang ke negeri Syām, untuk memperdagangkan dagangan Khadījah." },
                { ar: "وَ مَعَهُ غُلَامُهَا مَيْسَرَةُ يَخْدُمُهُ عَلَيْهِ الصَّلَاةُ وَ السَّلَامُ وَ يَقُوْمُ بِمَا عَنَاهُ؟", tr: "Wa ma‘ahū ghulāmuhā Maisaratun yakhdumuhū ‘alaihiṣ-ṣalātu was-salāmu wa yaqūmu bimā ‘anāh.", ket: "Beliau disertai pembantu Siti Khadījah yang bernama Maisarah untuk membantu pekerjaannya selama dalam perjalanan dan selama berada di negeri Syām." },
                { ar: "فَنَزَلَ تَحْتَ شَجَرَةِ لَدَا صَوْمِعَةِ نَسْطُوْرَا رَاهِبِ النَّصْرَانِيَّةِ؟", tr: "Fa nazala taḥta syajaratin ladā ṣaumi‘ati Nasṭhūrā rāhibin-naṣrāniyyah.", ket: "Di tengah perjalanan, Beliau berhenti untuk beristirahat di bawah kayu dekat rumah tempat peribadatan seorang pendeta bernama Nasthūr." },
                { ar: "فَعَرَفَهُ الرَّاهِبُ إِذْ مَالَ إِلَيْهِ ظِلُّهَا الْوَارِفُ وَ آوَاهُ؟", tr: "Fa ‘arafahur-rāhibu idz māla ilaihi ẓilluhal wārifu wa āwāh.", ket: "Maka pendeta itu segera dapat mengetahuinya, di kala bayang-bayang pohon itu memanjang dan melebar menaungi beliau dari teriknya panas matahari." },
                { ar: "وَ قَالَ مَا نَزَلَ تَحْتَ هٰذِهِ الشَّجَرَةِ قَطُّ إِلَّا نَبِيٌّ ذُوْ صِفَاتٍ نَقِيَّةٍ؟", tr: "Wa qāla mā nazala taḥta hādzihisy-syajarati qaṭṭu illā nabiyyun dzū ṣifātin naqiyyah.", ket: "Pendeta itu berkata: “Tiada seorang jua pun yang berhenti di bawah pohon ini, melainkan nabi yang mempunyai sifat-sifat yang suci.”" },
                { ar: "وَ رَسُوْلٌ قَدْ خَصَّهُ اللّٰهُ تَعَالَى بِالْفَضَائِلِ وَ حَبَاهُ؟", tr: "Wa rasūlun qad khaṣṣahullāhu ta‘ālā bil faḍā’ili wa ḥabāh.", ket: "Dan Rasūl yang diistimewakan dan diberi anugerah dengan sifat-sifat utama." },
                { ar: "ثُمَّ قَالَ لِمَيْسَرَةَ أَفِيْ عَيْنَيْهِ حُمْرَةُ ࣙاسْتِظْهَارًا لِلْعَلَامَةِ الْخَفِيَّةِ؟", tr: "Tsumma qāla li Maisarata a fī ‘ainaihi ḥumratun istiẓhāran lil ‘alāmatil khafiyyah.", ket: "Pendeta bertanya kepada Maisarah: “Adakah pada dua matanya terdapat tanda kemerah-merahan?”" },
                { ar: "فَأَجَابَهُ بِنَعَمْ فَحَقَّ لَدَيْهِ مَا ظَنَّهُ فِيْهِ وَ تَوَخَّاهُ؟", tr: "Fa ajābahū bi na‘am fa ḥaqqa ladaihi mā ẓannahū fīhi wa takhawwāh.", ket: "Maisarah menjawab: “Betul, ada.” Maka sang pendeta meyakini dugaannya itu, lalu ia pun menjalin persaudaraan dengan nabi." },
                { ar: "وَقَالَ لِمَيْسَرَةَ: لَا تُفَارِقْهُ وَكُنْ مَعَهُ بِصِدْقِ عَزْمٍ وَحُسْنِ طَوِيَّةٍ؟", tr: "Wa qāla li Maisarata: Lā tufāriqhu wa kun ma‘ahū biṣidqi ‘azmin wa ḥusni ṭawiyyah.", ket: "Dan Sang Pendeta berpesan kepada Maisarah: “Orang ini janganlah anda tinggalkan seorang saja, dampingilah dia dengan tujuan hati yang benar dan sebaik perlindungan." },
                { ar: "فَإِنَّهُ مِمَّنْ أَكْرَمَهُ اللهُ تَعَالَى بِالنُّبُوَّةِ وَاجْتَبَاهُ؟", tr: "Fa innahū mimman akramahullāhu ta‘ālā bin-nubuwwati wajtabāh.", ket: "Karena sesungguhnya dia termasuk dari golongan orang yang dimuliakan Allah ta‘ālā dengan sifat kenabian dan dipilih-Nya menjadi nabi.”" },
                { ar: "ثُمَّ عَادَ إِلَى مَكَّةَ فَرَأَتْهُ خَدِيْجَةُ مُقْبِلاً وَهِيَ بَيْنَ نِسْوَةٍ فِيْ عِلِّيَّةٍ؟", tr: "Tsumma ‘āda ilā Makkata fa ra’athu Khadījatu muqbilaw wa hiya baina niswatin fī ‘illiyyah.", ket: "Kemudian dia kembali ke Makkah, ketika itu Khadījah ditemani oleh beberapa inangnya melihatnya dari atas rumah." },
                { ar: "وَ مَلَكَانِ عَلَى رَأْسِهِ الشَّرِيْفِ مِنْ وَهَجِ الشَّمْسِ قَدْ أَظَلَّاهُ؟", tr: "Wa malakāni ‘alā ra’sihisy-syarīfi min wahajisy-syamsi qad aẓallāh.", ket: "Sedangkan dua malaikat menaungi (memayungi) kepalanya dari teriknya panas matahari." },
                { ar: "وَأَخْبَرَهَا مَيْسَرَةُ بِأَنَّهُ رَأَى ذٰلِكَ فِي السَّفَرِ كُلِّهِ وَبِمَا قَالَ لَهُ الرَّاهِبُ وَأَوْدَعَهُ لَدَيْهِ مِنَ الْوَصِيَّةِ؟", tr: "Wa akhbarahā Maisaratun bi annahū ra’ā dzālika fis-safari kullihī wa bimā qāla lahur-rāhibu wa auda‘ahū ladaihi minal waṣiyyah.", ket: "Akhirnya Maisarah melaporkan seluruhnya kepada Khadījah tentang peristiwa yang terjadi selama dalam perjalanan, dan melaporkan wasiat yang telah disampaikan oleh pendeta Nasthūr itu." },
                { ar: "وَ ضَاعَفَ اللّٰهُ فِيْ تِلْكَ التِّجَارَةِ رِبْحَهَا وَ نَمَّاهُ؟", tr: "Wa ḍā‘afallāhu fī tilkat-tijārati ribḥahā wa nammāh.", ket: "Dan ternyata harta yang diperdagangkan Beliau s.a.w. itu dilipatkan oleh Allah dalam keuntungannya." },
                { ar: "فَبَانَ لِخَدِيْجَةَ بِمَا رَأَتْ وَ مَا سَمِعَتْ أَنَّهُ رَسُوْلُ اللّٰهِ تَعَالَى إِلَى الْبَرِيَّةِ؟", tr: "Fa bāna li Khadījata bimā ra’at wa mā sami‘at annahū rasūlullāhi ta‘ālā ilal bariyyah.", ket: "Berdasarkan apa yang disaksikannya sendiri, dan apa yang telah didengarnya dari Maisarah, maka mengertilah Khadījah, bahwa sesungguhnya Beliau adalah Pesuruh Allah (Rasūlullāh) untuk seluruh makhluk." },
                { ar: "الَّذِيْ خَصَّهُ اللّٰهُ تَعَالَى بِقُرْبِهِ وَاصْطَفَاهُ؟", tr: "Alladzī khaṣṣahullāhu ta‘ālā biqurabihī waṣṭafāh.", ket: "Yang telah diistimewakan oleh Allah ta‘ālā dan dipilihnya." },
                { ar: "فَخَطَبَتْهُ لِنَفْسِهَا لِتَشُمَّ مِنَ الْإِيْمَانِ بِهِ طِيْبَ رَيَّاهُ؟", tr: "Fa khaṭabathu linafsihā litasymma minal īmāni bihī ṭība rayyāh.", ket: "Kemudian Khadījah melamarkan dirinya, dengan maksud agar ia dapat merasakan bau iman dan kesegarannya." },
                { ar: "فَأَخْبَرَ صَلَّى اللّٰهُ عَلَيْهِ وَسَلَّمَ أَعْمَامَهُ بِمَا دَعَتْهُ إِلَيْهِ هٰذِهِ الْبَرَّةُ التَّقِيَّةُ؟", tr: "Fa akhbara ṣallallāhu ‘alaihi wa sallama a‘māmahū bimā da‘athu ilaihi hādzihil barratut taqiyyah.", ket: "Maka Beliau s.a.w. memberitahukan maksud Khadījah itu kepada paman-pamannya untuk dimintai pertimbangan." },
                { ar: "فَرَغِبُوْا فِيْهَا لِفَضْلٍ وَ دِيْنٍ وَ جَمَالٍ وَ مَالٍ وَ حَسَبٍ وَ نَسَبٍ كُلٌّ مِنَ الْقَوْمِ يَهْوَاهُ؟", tr: "Fa raghibū fīhā lifaḍlin wa dīnin wa jamālin wa mālin wa ḥasabin wa nasabin kullun minal qaumi yahwāh.", ket: "Mereka juga ikut menyetujuinya, karena keutamaannya, agamanya, kecantikannya, hartanya, dan nasabnya. Dan seluruh golongan beliau sendiri juga mendukungnya." },
                { ar: "وَ خَطَبَ أَبُوْ طَالِبٍ وَ أَثْنَى عَلَيْهِ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ بَعْدَ أَنْ حَمِدَ اللّٰهَ بِمَحَامِدَ سَنِيَّةٍ؟", tr: "Wa khaṭaba Abū Thālibin wa atsnā ‘alaihi ṣallallāhu ‘alaihi wa sallama ba‘da an ḥamidallāha bimaḥāmida saniyyah.", ket: "Abū Thālib pada acara pinangan itu berkhutbah memuji Nabi s.a.w. setelah memuja kepada Allah dengan puji-pujian." },
                { ar: "وَ قَالَ: هُوَ وَاللّٰهِ بَعْدُ لَهُ نَبَأٌ عَظِيْمٌ، يُحْمَدُ فِيْهِ مَسْرَاهُ؟", tr: "Wa qāla: Huwa wallāhi ba‘du lahū naba’un ‘aẓīmun, yuḥmadu fīhi masrāh.", ket: "Abū Thālib berkata: “Demi Allah, Dia mengemban urusan yang besar yang akan terpuji kesudahannya.”" },
                { ar: "فَزَوَّجَهَا مِنْهُ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ أَبُوْهَا، وَ قِيْلَ: عَمُّهَا، وَ قِيْلَ: أَخُوْهَا لِسَابِقِ سَعَادَتِهَا الْأَزَلِيَّةِ؟", tr: "Fa zauwajahā minhu ṣallallāhu ‘alaihi wa sallama abūhā, wa qīla: ‘ammuhā, wa qīla: akhūhā lisābiqi sa‘ādatihal azaliyyah.", ket: "Lalu Khadījah dinikahkan oleh ayahnya sendiri, dan ada yang mengatakan pamannya, dan ada yang mengatakan saudaranya. Kebahagiaan Khadījah yang semacam ini karena memang sudah didahului ketentuannya pada zaman azali." },
                { ar: "وَ أَوْلَدَهَا كُلَّ أَوْلَادِهِ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ إِلَّا الَّذِيْ بِاسْمِ الْخَلِيْلِ سَمَّاهُ.", tr: "Wa auladahā kulla aulādihī ṣallallāhu ‘alaihi wa sallama illal-ladzī bismil khalīli sammāh.", ket: "Dari perkawinan itu, Beliau s.a.w. memperoleh anak yang cukup banyak, kesemuanya beribukan Khadījah, kecuali seorang anak yang bernama Ibrāhīm. (Adapun Ibrāhīm adalah beribukan Mariyah, seorang istri Rasūlullāh s.a.w. berasal dari Mesir)." }
            ]
        },
        {
            judul: "Al Barjanji (Pembangunan Ka'bah & Hajar Aswad)",
            isi: [
                { ar: "عَطِّرِاللّٰهُـمَّ قَبْرَهُ الْكَرِيْمِ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمٍ", tr: "‘Aththirillāhumma qabrahul karīm ۞ bi‘arfin syadziyyin min ṣalātin wa taslīm", ket: "Semoga Allah mengharumkan dan mewangikan kuburnya (Nabi) yang mulia, dengan keharuman wangi-wangian salawat dan salam sejahtera." },
                { ar: "بِسْمِ اللّٰهِ الرَّحْمنِ الرَّحِيْمِ", tr: "Bismillāhir-raḥmānir-raḥīm", ket: "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang." },
                { ar: "وَ لَمَّا بَلَّغَ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ خَمْسًا وَ ثَلٰثِيْنَ سَنَةً بَنَتْ قُرَيْشٌ ࣙالْكَعْبَةَ لِانْصِدَاعِهَا بِالسُّيُوْلِ الْأَبْطَحِيَّةِ؟", tr: "Wa lammā ballagha ṣallallāhu ‘alaihi wa sallama khamsan wa tsalātsīna sanatan banat Quraisyunil Ka‘bata linṣidā‘ihā bis-suyūlil abṭaḥiyyah.", ket: "Ketika Beliau s.a.w. berumur tiga puluh lima tahun, kaum Quraisy berupaya membangun Ka‘bah, karena pecah sebab dilanda banjir yang berasal dari lembah Abthah." },
                { ar: "وَ تَنَازَعُوْا فِيْ رَفْعِ الْحَجَرِ الْأَسْوَدِ، فَكُلٌّ أَرَادَ رَفْعَهُ وَ رَجَاهُ؟", tr: "Wa tanāza‘ū fī raf‘il ḥajaril aswadi, fa kullun arāda raf‘ahū wa rajāh.", ket: "Dan mereka bersengketa dalam hal meletakkan Ḥajar Aswad. Karena setiap golongan berkehendak untuk mengangkat dan meletakkan kembali pada tempatnya yang sama." },
                { ar: "وَ عَظُمَ الْقِيْلُ وَ الْقَالُ، وَ تَحَالَفُوْا عَلَى الْقِتَالِ، وَ قَوِيَتِ الْعَصَبِيَّةُ؟", tr: "Wa ‘aẓumal qīlu wal qālu, wa taḥālafū ‘alal qitāli, wa qawiyatil ‘aṣabiyyah.", ket: "Pertengkaran semakin menjadi-jadi dan peperangan hampir saja terjadi, sedangkan fanatisme suku semakin kuat bergolong-golong." },
                { ar: "ثُمَّ تَدَاعَوْا إِلَى الْإِنْصَافِ، وَ فَوَّضُوا الْأَمْرَ إِلَى ذِيْ رَأْيٍ صَآئِبٍ وَ أَنَاةٍ؟", tr: "Tsumma tadā‘au ilal inṣāfi, wa fawwaḍul amra ilā dzī ra’yin ṣā’ibin wa anāh.", ket: "Kemudian mereka mengadakan perdamaian dan mencari jalan keluarnya dan menyerahkan persoalan tersebut kepada pendapat yang benar." },
                { ar: "فَحَكَمَ بِتَحْكِيْمِ أَوَّلِ دَاخِلٍ مِنْ بَابِ السَّدَنَةِ الشَّيْبِيَّةِ؟", tr: "Fa ḥakama bitaḥkīmi awwali dākhilin min bābis-sadanatisy-syaibiyyah.", ket: "Mereka bersepakat, bahwa siapa saja nanti yang mula-mula sekali memasuki dari pintu tirai juru kunci Ka‘bah itulah orang yang berhak untuk menjadi hakim dalam persoalan ini." },
                { ar: "فَكَانَ النَّبِيُّ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ أَوَّلَ دَاخِلٍ، فَقَالُوْا: هذَا الْأَمِيْنُ، وَ كُلُّنَا نَقْبَلُهُ وَ نَرْضَاهُ؟", tr: "Fa kānan-nabiyyu ṣallallāhu ‘alaihi wa sallama awwala dākhilin, fa qālū: Hādzal amīnu, wa kullunā naqbalihū wa narḍāh.", ket: "Ternyata Beliau s.a.w. yang mula-mula sekali memasukinya. Maka, berteriaklah mereka secara serempak: “Inilah dia al-Amīn, kami semua menerima dan meridhai.”" },
                { ar: "فَاَخْبَرُوْهُ بِأَنَّهُمْ رَضُوْهُ أَنْ يَكُوْنَ صَاحِبَ الْحُكْمِ فِيْ هٰذَا الْمُلِمِّ وَ وَلِيَّهُ؟", tr: "Fa akhbarūhu bi annahum raḍūhu an yakūna ṣāḥibal ḥukmi fī hādzal mulimmi wa waliyyah.", ket: "Lalu, berceritalah mereka kepada Beliau s.a.w., bahwa mereka telah senang hati manakala beliau yang memutuskan dan mengaturnya." },
                { ar: "فَوَضَعَ الْحَجَرَ فِيْ ثَوْبٍ، ثُمَّ أَمَرَ أَنْ تَرْفَعَهُ الْقَبَائِلُ جَمِيْعًا إِلَى مُرْتَقَاهُ؟", tr: "Fa waḍa‘al ḥajara fī tsaubin, tsumma amara an tarfa‘ahul qabā’ilu jamī‘an ilā murtaqāh.", ket: "Akhirnya Beliau meletakkan Ḥajar Aswad pada kain, kemudian mereka disuruh mengangkatnya bersama-sama menuju ke tempat asalnya." },
                { ar: "فَرَفْعُوْهُ إِلَى مَقَرِّهِ مِنْ رُكْنِ هَاتِيْكَ الْبَنِيَّةِ؟", tr: "Fa raf‘ūhu ilā maqarrihī min rukni hātīkal baniyyah.", ket: "Mereka dengan serentak mengangkat Ḥajar Aswad menuju ke sudut Ka‘bah." },
                { ar: "وَ وَضَعَهُ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ بِيَدِهِ الشَّرِيْفَةِ فِيْ مَوْضِعِهِ الْآنَ وَ بَنَاهُ.", tr: "Wa waḍa‘ahū ṣallallāhu ‘alaihi wa sallama bi yadihisy-syarīfati fī mauḍi‘ihil āna wa banāh.", ket: "Kemudian, oleh Beliau s.a.w. batu itu diletakkan kembali pada tempat semula, sehingga sampai sekarang." }
            ]
        },
        {
            judul: "Al Barjanji (Awal Turunnya Wahyu)",
            isi: [
                { ar: "عَطِّرِاللّٰهُـمَّ قَبْرَهُ الْكَرِيْمِ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمٍ", tr: "‘Aththirillāhumma qabrahul karīm ۞ bi‘arfin syadziyyin min ṣalātin wa taslīm", ket: "Semoga Allah mengharumkan dan mewangikan kuburnya (Nabi) yang mulia, dengan keharuman wangi-wangian salawat dan salam sejahtera." },
                { ar: "بِسْمِ اللّٰهِ الرَّحْمنِ الرَّحِيْمِ", tr: "Bismillāhir-raḥmānir-raḥīm", ket: "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang." },
                { ar: "وَ لَمَّا كَمُلَ لَهُ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ أَرْبَعُوْنَ سَنَةً عَلَى أَوْفَقِ الْأَقْوَالِ لِذَوِي الْعَالِمِيَّةِ،", tr: "Wa lammā kamula lahū ṣallallāhu ‘alaihi wa sallama arba‘ūna sanatan ‘alā aufaqil aqwāli lidzawil ‘ālimiyyah.", ket: "Ketika usia Beliau s.a.w. genap empat puluh tahun, dengan mengikuti Qaul ‘ulama’ ahli sejarah." },
                { ar: "بَعَثَهُ اللّٰهُ تَعَالَى لِلْعَالَمِيْنَ بَشِيْرًا وَ نَذِيْرًا فَعَمَّهُمْ بِرُحْمَاهُ؟", tr: "Ba‘atsahullāhu ta‘ālā lil ‘ālamīna basyīran wa nadzīran fa ‘ammahum biruḥmāh.", ket: "Maka Allah ta‘ālā mengangkat Beliau menjadi Rasūl-Nya sebagai pembawa berita gembira dan pembawa peringatan, dengan maksud untuk umat seluruh alam." },
                { ar: "وَ بُدِئَ إِلَى تَمَامِ سِتَّةِ أَشْهُرٍ بِالرُّؤْيَا الصَّادِقَةِ الْجَلِيَّةِ؟", tr: "Wa budi’a ilā tamāmi sittati asyhurin bir-ru’yāṣ-ṣādiqatil jaliyyah.", ket: "Pada enam bulan pertama, Beliau mendapat impian-impian yang benar dan nyata." },
                { ar: "فَكَانَ لَا يَرَى رُؤْيًا إِلَّا جَآءَتْ مِثْلَ فَلَقِ صُبْحٍ أَضَآءَ سَنَاهُ؟", tr: "Fa kāna lā yarā ru’yan illā jā’at mitsla falaqi ṣubḥin aḍā’a sanāh.", ket: "Setiap kali Beliau s.a.w. bermimpi, beliau melihat seolah-olah ada sinar matahari pagi yang memancar cemerlang membelah kegelapan ufuk timur." },
                { ar: "وَ إِنَّمَا ابْتُدِئَ بِالرُّؤْيَا تَمْرِيْنًا لِلْقُوَّةِ الْبَشَرِيَّةِ؟", tr: "Wa innamabtudi’a bir-ru’yā tamrīnan lil quwwatil basyariyyah.", ket: "Sesungguhnya pada waktu menjelang pengangkatannya itu dimulai impian-impian, dimaksudkan untuk menggembleng jiwa insaninya, agar beliau mempunyai dasar yang kokoh dan kuat." },
                { ar: "لِئَلَّا يَفْجَأَهُ الْمَلَكُ بِصَرِيْحِ النُّبُوَّةِ، فَلَا تَقْوَاهُ قُوَاهُ؟", tr: "Li’allā yafja’ahul malaku biṣarīḥin-nubuwwati, falā taqwāhu quwāh.", ket: "Agar tidak merasa gentar dan cukup mampu daya kekuataannya, manakala menghadapi malaikat Jibrīl a.s., yang akan menyampaikan wahyunya." },
                { ar: "وَ حُبِّبَ إِلَيْهِ الْخَلَاءُ، فَكَانَ يَتَعَبَّدُ بِحِرَآءِ اللَّيَالِيَ الْعَدَدِيَّةَ؟", tr: "Wa ḥubbiba ilaihil khalā’u, fa kāna yata‘abbadu biḥirā’il layāliyal ‘adadiyyah.", ket: "Dalam pada itu, Beliau s.a.w. memang senang bersunyi diri, sedangkan tempat peribadatannya adalah Gua Ḥirā’, sampai bermalam-malam lamanya." },
                { ar: "إِلَى أَنْ أَتَاهُ فِيْهِ صَرِيْحُ الْحَقِّ وَ وَافَاهُ؟", tr: "Ilā an atāhu fīhi ṣarīḥul ḥaqqi wa wāfāh.", ket: "Hingga datang malaikat Jibrīl menyampaikan wahyu." },
                { ar: "وَ ذٰلِكَ فِيْ يَوْمِ الْإِثْنَيْنِ لِسَبْعَ عَشَرَةَ لَيْلَةً خَلَّتْ مِنْ شَهْرِاللَّيْلَةِ الْقَدْرِيَّةِ؟", tr: "Wa dzālika fī yaumil itsnaini lisab‘a ‘asyrata lailatan khallat min syahril lailatil qadriyyah.", ket: "Ketika itu, bertepatan pada hari Senin tanggal 17 Ramadhān." },
                { ar: "وَ ثَمَّ أَقْوَالٌ: لِسَبْعٍ، أَوْ لِأَرْبَعٍ وَ عِشْرِيْنَ مِنْهُ، أَوْ لِثَمَانٍ مِنْ شَهْرِ مَوْلِدِهِ الَّذِيْ بَدَا فِيْهِ بَدْرُ مُحَيَّاهُ؟", tr: "Wa tsamma aqwālun: lisab‘in, au li’arba‘in wa ‘isyrīna minhu, au litsamānin min syahri maulidihil-ladzī badā fīhi badru muḥayyāh.", ket: "Ada beberapa pendapat yang mengatakan, bahwa hal itu terjadi pada tanggal 27/28 Ramadhān, dan ada juga yang mengatakan tanggal 8 Rabī‘-ul-Awwal." },
                { ar: "فَقَالَ لَهُ: اِقْرَأْ، فَأَبَى فَغَطَّهُ غَطَّةً قَوِيَّةً؟", tr: "Fa qāla lahū: Iqra’, fa abā fa ghaṭṭahū ghaṭṭatan qawiyyah.", ket: "Pada waktu itu malaikat Jibrīl mengatakan: “Bacalah!”, tetapi Beliau tidak membaca. Lalu Jibrīl memeluknya dengan pelukan yang kuat." },
                { ar: "ثُمَّ قَالَ لَهُ: اِقْرَأْ، فَأَبَى فَغَطَّهُ ثَانِيَةً حَتَّى بَلَغَ مِنْهُ الْجَهْدُ وَ غَطَّاهُ؟", tr: "Tsumma qāla lahū: Iqra’, fa abā fa ghaṭṭahū tsāniyatan ḥattā balagha minhul jahdu wa ghaṭṭāh.", ket: "Kemudian Jibrīl berkata lagi: “Bacalah!”, tetapi Beliau tetap tidak membaca. Lalu dipeluknya untuk yang kedua kalinya, sehingga pelukannya menjadi erat, dan sukar untuk dilepaskan." },
                { ar: "ثُمَّ قَالَ لَهُ: اِقْرَأْ، فَأَبَى فَغَطَّهُ ثَالِثَةً لِيَتَوَجَّهَ إِلَى مَا سَيُلْقَى إِلَيْهِ بِجَمْعِيَّةِ؟", tr: "Tsumma qāla lahū: Iqra’, fa abā fa ghaṭṭahū tsāalitsatan liyatawajjaha ilā mā sayulqā ilaihi bijam‘iyyah.", ket: "(Demikianlah hingga tiga kali Jibrīl menyuruh Beliau s.a.w. membaca, tetapi Beliau masih tetap tidak membaca, karena tidak tahu apa yang dibaca.) Lalu dipeluknya lagi untuk ketiga kalinya. Hal ini dilakukan oleh Jibrīl, dengan maksud agar Beliau s.a.w. siap untuk menerima wahyu yang akan disampaikan kepadanya." },
                { ar: "وَ يُقَابِلَهُ بِجِدٍّ وَاجْتِهَادٍ وَ يَتَلَقَّاهُ؟", tr: "Wa yuqābilahū bijiddin wajtihādin wa yatalaqqāh.", ket: "Setelah Beliau s.a.w. untuk menerima wahyu, maka wahyu suci diterimakannya." },
                { ar: "ثُمَّ فَتَرَ الْوَحْيُ ثَلَاثَ سِنِيْنَ، أَوْ ثَلَاثِيْنَ شَهْرًا، لِيَشْتَاقَ إِلَى انْتِشَاقِ هَاتِيْكَ النَّفَحَاتِ الشَّذِيَّةِ؟", tr: "Tsumma fataral waḥyu tsalātsa sinīna, au tsalātsīna syahran, liyasytaqa ilan tisyaqi hātīkan nafaḥāatisy-syadziyyah.", ket: "Sesudah itu, terputuslah wahyu hingga tiga tahun lamanya, atau tiga puluh bulan, dengan tujuan agar Beliau s.a.w. merasa rindu kepadanya." },
                { ar: "ثُمَّ أُنْزِلَتْ عَلَيْهِ { يَا أَيُّهَا الْمُدَّثِّر } فَجَاءَهُ جِبْرِيْلُ بِهَا وَ نَادَاهُ؟", tr: "Tsumma unzilat ‘alaihi {Yā Ayyuhal Muddatstsir} fa jā’ahū Jibrīlu bihā wa nādāh.", ket: "Kemudian, turun lagi wahyu/ayat yang berbunyi “Yā Ayyuh-al-Muddatstsir” (Hai orang yang berkemul (berselimut))." },
                { ar: "فَكَانَ لِنُبُوَّتِهِ فِيْ تَقَدُّمِ { اِقْرَأْ بِاسْمِ رَبِّكَ } شَاهِدٌ عَلَى أَنَّ لَهَا السَّابِقِيَّةَ؟", tr: "Fa kāna linubuwwatihī fī taqaddumi {Iqra’ bismi rabbika} syāhidun ‘alā anna lahās-sābiqiyyah.", ket: "Wahyu Pertama yang mendahuluinya adalah surat al-‘Alaq." },
                { ar: "وَ التَّقَدُّمَ عَلَى رِسَالَتِهِ بِالْبَشَارَةِ وَ النَّذَارَةِ لِمَنْ دَعَاهُ.", tr: "Wat-taqadduma ‘alā risālatihī bilbasyārati wan-nadzārati liman da‘āh.", ket: "Yang menjadi saksi pengangkatannya menjadi Rasūl dengan membaca berita gembira dan peringatan orang yang diserunya." }
            ]
        },
        {
            judul: "Al Barjanji (Dakwah Terang-terangan & Ujian)",
            isi: [
                { ar: "عَطِّرِاللّٰهُـمَّ قَبْرَهُ الْكَرِيْمِ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمٍ", tr: "‘Aththirillāhumma qabrahul karīm ۞ bi‘arfin syadziyyin min ṣalātin wa taslīm", ket: "Semoga Allah mengharumkan dan mewangikan kuburnya (Nabi) yang mulia, dengan keharuman wangi-wangian salawat dan salam sejahtera." },
                { ar: "بِسْمِ اللّٰهِ الرَّحْمنِ الرَّحِيْمِ", tr: "Bismillāhir-raḥmānir-raḥīm", ket: "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang." },
                { ar: "وَ أَوَّلُ مَنْ آمَنَ بِهِ مِنَ الرِّجَالِ: أَبُوْ بَكْرٍ صَاحِبُ الْغَارِ وَ الصِّدِّيْقِيَّةِ؟", tr: "Wa awwalu man āmana bihī minar-rijāli: Abū Bakrin ṣāḥibul ghāri waṣ-ṣiddīqiyyah.", ket: "Orang lelaki pertama yang beriman kepada Nabi s.a.w. adalah Abū Bakar Shiddīq, orang yang menemani beliau ketika bersembunyi di gua Tsur, (ia digelari ash-Shiddīq, karena merupakan orang pertama yang membenarkan peristiwa Isrā’)." },
                { ar: "وَ مِنَ الصِّبْيَانِ: عَلِيٌّ، وَ مِنَ النِّسَاءِ: خَدِيْجَةُ الَّتِيْ ثَبَّتَ اللّٰهُ بِهَا قَلْبَهُ وَ وَقَاهُ؟", tr: "Wa minaṣ-ṣibyāni: ‘Aliyyun, wa minan-nisā’i: Khadījatul-latī tsabbatallāhu bihā qalbahū wa waqāh.", ket: "Dan dari golongan anak kecil, adalah ‘Alī bin Abī Thālib, dan dari golongan orang-orang perempuan adalah Khadījah yang dengannya Allah menenangkan hati Beliau dan melindunginya." },
                { ar: "وَ مِنَ الْمَوَالِيْ: زَيْدُ ابْنُ حَارِثَةَ، وَ مِنَ الْأَرِقَّاءِ: بِلَالٌ الَّذِيْ عَذَّبَهُ فِي اللّٰهِ أُمَيَّةُ؟", tr: "Wa minal mawālī: Zaidubnu Ḥāritsah, wa minal ariqqā’i: Bilālunil-ladzī ‘adzdzabahū fillāhi Umayyah.", ket: "Dari kalangan hamba sahaya yang sudah merdeka, adalah Zaid bin Ḥāritsah, dan dari hamba sahaya yang belum bebas adalah Bilāl bin Rabāḥ yang karena imannya kepada Allah, ia disiksa oleh tuannya yang bernama Umayyah." },
                { ar: "وَ أَوْلَاهُ مَوْلَاهُ أَبُوْ بَكْرٍ مِنَ الْعِتْقِ مَا أَوْلَاهُ؟", tr: "Wa aulāhu maulāhu Abū Bakrin minal ‘itqi mā aulāh.", ket: "Yang kemudian ditebus Abū Bakar Shiddīq untuk dimerdekakan." },
                { ar: "ثُمَّ أَسْلَمَ: عُثْمَانُ، وَ سَعْدٌ، وَ سَعِيْدٌ، وَ طَلْحَةٌ، وَ ابْنُ عَوْفٍ، وَ ابْنُ عَمَّتِهِ صَفِيَّةُ؟", tr: "Tsumma aslama: ‘Utsmānu, wa Sa‘dun, wa Sa‘īdun, wa Ṭalḥatun, wabnu ‘Aufin, wabnu ‘ammatihī Ṣafiyyah.", ket: "Seterusnya berturut-turut masuk Islam: ‘Utsmān bin ‘Affān, Sa‘ad bin Abī Waqqāsh, Sa‘īd bin Zaid, Thalḥah bin ‘Ubaidillāh, ‘Abd-ur-Raḥmān bin ‘Auf, Zubair bin ‘Awwām, saudara lelaki sepupu Nabi s.a.w. dan anak lelaki Shaffiyyah." },
                { ar: "وَ غَيْرُهُمْ مِمَّنْ أَنْهَلَهُ الصِّدِّيْقُ رَحِيْقَ التَّصْدِيْقِ وَ سَقَاهُ؟", tr: "Wa ghairuhum mimman anhalahuṣ-ṣiddīqu raḥīqat-taṣdīqi wa saqāh.", ket: "Adapun selain orang-orang tersebut masuk Islam atas usaha dan jasa Abū Bakar Shiddīq." },
                { ar: "وَ مَا زَالَتْ عِبَادَتُهُ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ وَ أَصْحَابُهُ مَخْفِيَّةً؟", tr: "Wa mā zālat ‘ibādatuhū ṣallallāhu ‘alaihi wa sallama wa aṣḥābuhū makhfiyyah.", ket: "Pada waktu itu, Beliau s.a.w. dan para sahabat masih sembunyi-sembunyi dalam menjalankan ibadahnya." },
                { ar: "حَتَّى أُنْزِلَتْ عَلَيْهِ { فَاصْدَعْ بِمَا تُؤْمَرُ } فَجَهَرَ بِدُعَاءِ الْخَلْقِ إِلَى اللّٰهِ؟", tr: "Ḥattā unzilat ‘alaihi {Faṣda‘ bimā tu’maru} fa jahara bidu‘ā’il khalqi ilallāh.", ket: "Sehingga turun ayat surat al-Ḥijr, ayat 94, barulah Beliau s.a.w. bangkit menyeru umat dengan terang-terangan agar beriman kepada Allah." },
                { ar: "وَ لَمْ يَبْعُدْ مِنْهُ قَوْمُهُ حَتَّى عَابَ آلِهَتَهُمْ وَ أَمَرَ بِرَفْضِ مَا سِوَى الْوَحْدَانِيَّةِ؟", tr: "Wa lam yab‘ud minhu qaumuhū ḥattā ‘āba ālihatuhum wa amara birafḍi mā siwal waḥdāniyyah.", ket: "Kaumnya tidak menjauhi dan memusuhi Beliau sampai ketika Beliau mencela sesembahan-sesembahan mereka dan menyuruh mereka meninggalkan penyembahan selain hanya kepada Allah Yang Maha Esa." },
                { ar: "فَتَجَرَّؤُا عَلَى مُبَارَزَتِهِ بِالْعَدَاوَةِ وَ أَذَاهُ؟", tr: "Fa tajarra’ū ‘alā mubārazatihī bil ‘adāwati wa adzāh.", ket: "Ajakan Beliau ini ditentang oleh kaum musyrikin dengan permusuhan terbuka dan penganiayaan terhadap para sahabatnya." },
                { ar: "وَ اشْتَدَّ عَلَى الْمُسْلِمِيْنَ الْبَلَاءُ، فَهَاجَرُوْا فِيْ سَنَةِ خَمْسٍ إِلَى النَّاحِيَةِ النَّجَاشِيَّةِ؟", tr: "Wasytadda ‘alal muslimīnal balā’u, fa hājarū fī sanati khamsin ilan nāḥiyatin najāsyiyyah.", ket: "Oleh karenanya, kaum muslimin mendapatkan tekanan yang sangat berat. Sehingga pada tahun kelima dari kenabian terpaksa mereka berhijrah ke Ḥabasyah." },
                { ar: "وَ حَدَبَ عَلَيْهِ عَمُّهُ أَبُوْ طَالِبٍ، فَهَابَهُ كُلٌّ مِنَ الْقَوْمِ وَ تَحَامَاهُ؟", tr: "Wa ḥadaba ‘alaihi ‘ammuhū Abū Thālibin, fa hābahū kullun minal qaumi wa taḥāmāh.", ket: "Melihat keadaannya yang semacam ini, pamannya, Abū Thālib merasa kasihan kepadanya, akhirnya pamannya membela Beliau dengan sekuat-kuatnya, sehingga mereka merasa takut dan tidak berani mengganggu Beliau." },
                { ar: "وَ فُرِضَ عَلَيْهِ قِيَامُ بَعْضٍ مِنَ السَّاعَاتِ اللَّيْلِيَّةِ؟", tr: "Wa furiḍa ‘alaihi qiyāmu ba‘ḍin minas-sā‘ātil layliyyah.", ket: "Pada mulanya, Beliau diwajibkan Allah ta‘ālā melakukan shalat malam." },
                { ar: "ثُمَّ نُسِخَ بِقَوْلِهِ تَعَالَى: { فَاقْرَءُوْا مَا تَيَسَّرَ مِنْهُ وَ أَقِيْمُوا الصَّلَاةَ}", tr: "Tsumma nusikha biqaulihī ta‘ālā: {Faqra’ū mā tayassara minhu wa aqīmuṣ-ṣalāta}", ket: "Kemudian kewajiban dibatalkan dengan turunnya ayat (Maka bacalah apa yang sudah dipermudahkan darinya (al-Qur’ān) dan dirikanlah shalat.)" },
                { ar: "وَ فُرِضَ عَلَيْهِ رَكْعَتَانِ بِالْغَدَاةِ وَ رَكْعَتَانِ بِالْعَشِيَّةِ؟", tr: "Wa furiḍa ‘alaihi rak‘atāni bil ghadāti wa rak‘atāni bil ‘asyiyyah.", ket: "Lalu beliau diwajibkan melakukan shalat dua raka‘at di waktu pagi dan dua raka‘at waktu malam hari." },
                { ar: "ثُمَّ نُسِخَ بِإِيْجَابِ الصَّلَوَاتِ الْخَمْسِ فِيْ لَيْلَةِ مَسْرَاهُ؟", tr: "Tsumma nusikha bi ījābiṣ-ṣalawātil khamsi fī lailati masrāh.", ket: "Kemudian diganti dengan kewajiban melakukan shalat lima waktu pada malam Isrā’." },
                { ar: "وَ مَاتَ أَبُوْ طَالِبٍ فِيْ نِصْفِ شَوَّالٍ مِنْ عَاشِرِ الْبِعْثَةِ وَ عَظُمَتْ بِمَوْتِهِ الرَّزِيَّةُ؟", tr: "Wa māta Abū Thālibin fī niṣfi syawwālin min ‘āsyiril bi‘tsati wa ‘aẓumat bimautihil razziyyah.", ket: "Abū Thālib meninggal pada tanggal 15 bulan Syawwāl tahun kesepuluh dari kenabian, dan dengan sepeninggalnya itu bertambah besar pula bencana (yang menimpa Beliau dan para sahabatnya)." },
                { ar: "وَ تَلَتْهُ خَدِيْجَةُ بَعْدَ ثَلَاثَةِ أَيَّامٍ، وَ شَدَّ الْبَلَاءُ عَلَى الْمُسْلِمِيْنَ عُرَاهُ؟", tr: "Wa talathu Khadījatu ba‘da tsalātsati ayyāmin, wa syaddal balā’u ‘alal muslimīna ‘urāh.", ket: "Tiga hari kemudian, menyusul lagi Khadījah wafat, sehingga bertambah besarlah musibah yang menimpa kaum muslimin pada saat itu." },
                { ar: "وَ أَوْقَعَتْ قُرَيْشٌ بِهِ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ كُلَّ أَذِيَّةٍ؟", tr: "Wa auqa‘at Quraisyun bihī ṣallallāhu ‘alaihi wa sallama kulla adziyyah.", ket: "Penganiayaan kaum Quraisy terhadap Beliau s.a.w. semakin leluasa dan menjadi-jadi." },
                { ar: "وَ أَمَّ الطَّائِفَ يَدْعُوْا ثَقِيْفًا، فَلَمْ يُحْسِنُوْا بِالْإِجَابَةِ قِرَاهُ؟", tr: "Wa ammal ṭā’ifa yad‘ū Tsaqīfan, fa lam yuḥsinū bil ijābati qirāh.", ket: "Akhirnya Beliau s.a.w. pergi ke Thā’if untuk menyerukan Islam kepada kaum Bani Tsaqīf. Akan tetapi sembutan mereka tidak menyenangkan." },
                { ar: "فَأَغْرَوْا بِهِ السُّفَهَاءَ وَ الْعَبِيْدَ فَسَبُّوْهُ بِأَلْسِنَةٍ بَذِيَّةٍ؟", tr: "Fa aghrau bihis-sufahā’a wal ‘abīda fa sabbūhu bi alsinatin badziyyah.", ket: "Bahkan mereka ramai-ramai mengusir Beliau dengan segala ucapan-ucapan yang kotor lagi keji." },
                { ar: "وَ رَمَوْهُ بِالْحِجَارَةِ حَتَّى خُضِبَتْ بِالدِّمَاءِ نَعْلَاهُ؟", tr: "Wa ramauhu bil ḥijārati ḥattā khuḍibat bid-dimā’i na‘lāh.", ket: "Mereka melontari batu kepadanya, sehingga kasutnya berlumuran darah." },
                { ar: "ثُمَّ عَادَ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ إِلَى مَكَّةَ حَزِيْنًا، فَسَأَلَهُ مَلَكُ الْجِبَالُ فِيْ إِهْلَاكِ أَهْلِهَا ذَوِي الْعَصَبِيَّةِ؟", tr: "Tsumma ‘āda ṣallallāhu ‘alaihi wa sallama ilā Makkata ḥazīnan, fa sa’alahū malakul jibāli fī ihlāki ahlihā dzawil ‘aṣabiyyah.", ket: "Kemudian Beliau s.a.w. pulang kembali ke Makkah dengan menanggung luka-luka dan hati yang tersayat pedih. Lalu malaikat penjaga gunung bermohon kepada Beliau s.a.w. akan menghancurkan kaum penentang yang berkeras hati." },
                { ar: "فَقَالَ: ( إِنِّيْ أَرْجُوْ أَنْ يُخْرِجَ اللّٰهُ مِنْ أَصْلَابِهِمْ مَنْ يَتَوَلَّاهُ )", tr: "Fa qāla: (Innī arjū an yukhrijallāhu min aṣlābihim man yatawallāh)", ket: "Maka jawabnya: “Saya mengharap agar Allah mengeluarkan dari diri mereka itu generasi berikutnya yang mau beriman dan menghambakan diri kepada Allah ta‘ālā.”" }
            ]
        },
        {
            judul: "Al Barjanji (Peristiwa Isra' Mi'raj)",
            isi: [
                { ar: "عَطِّرِاللّٰهُـمَّ قَبْرَهُ الْكَرِيْمِ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمٍ", tr: "‘Aththirillāhumma qabrahul karīm ۞ bi‘arfin syadziyyin min ṣalātin wa taslīm", ket: "Semoga Allah mengharumkan dan mewangikan kuburnya (Nabi) yang mulia, dengan keharuman wangi-wangian salawat dan salam sejahtera." },
                { ar: "بِسْمِ اللّٰهِ الرَّحْمنِ الرَّحِيْمِ", tr: "Bismillāhir-raḥmānir-raḥīm", ket: "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang." },
                { ar: "ثُمَّ أُسْرِيَ بِرُوْحِهِ وَ جَسَدِهِ يَقَظَةً مِنَ الْمَسْجِدِ الْحَرَامِ إِلَى الْمَسْجِدِ الْأَقْصَى وَ رِحَابِهِ الْقُدْسِيَّةِ؟", tr: "Tsumma usriya birūḥihī wa jasadihī yaqaẓatan minal masjidil ḥarāmi ilal masjidil aqṣā wa riḥābihil qudsiyyah.", ket: "Kemudian Beliau s.a.w. di-isrā’-kan dengan jiwa dan raganya dari Masjid-il-Ḥarām ke Masjid-il-Aqshā." },
                { ar: "وَ عُرِجَ بِهِ إِلَى السَّموَاتِ، فَرَأَى آدَمَ فِي الْأُوْلَى؟", tr: "Wa ‘urija bihī ilas-samawāti, fa ra’ā Ādama fil ūlā.", ket: "Dan di-mi‘rāj-kan ke langit berlapis tujuh. Di langit pertama, Beliau berjumpa dengan Nabi Ādam." },
                { ar: "وَ قَدْ جَلَّلَهُ الْوَقَارُ وَ عَلَاهُ؟", tr: "Wa qad jallalahul waqāru wa ‘alāh.", ket: "Yang telah diagungkan kemuliaan dan ketinggian derajatnya." },
                { ar: "وَ رَاَى فِى الثَّانِيَةِ عِيْسَى ابْنَ مَرْيَمَ الْبَتُوْلِ الْبَرَّةِ التَّقِيَّةِ؟", tr: "Wa ra’ā fits-tsāniyati ‘Īsabna Maryamal batūlil barratit taqiyyah.", ket: "Di langit kedua, Beliau bertemu dengan Nabi ‘Īsā bin Maryam, (Maryam adalah) seorang gadis yang suci dari perbuatan noda, lagi bertaqwa kepada Allah ta‘ālā." },
                { ar: "وَ ابْنَ خَالَتِهِ يَحْيَى الَّذِيْ أُوْتيَ الْحُكْمَ فِيْ حَلِ صِبَاهُ؟", tr: "Wabna khālatihī Yaḥyal-ladzī ūtiyal ḥukma fī ḥali ṣibāh.", ket: "Dan di sana juga bertemu dengan Nabi Yaḥyā, saudara lelaki sepupu Nabi ‘Īsā, yang sudah alim sejak kecil." },
                { ar: "وَ رَأَى فِي الثَّالِثَةِ يُوْسُفَ بِصُوْرَتِهِ الْجَمَالِيَّةِ؟", tr: "Wa ra’ā fits-tsālitsati Yūsufa biṣūratihil jamāliyyah.", ket: "Di langit ketiga, Beliau bertemu dengan Nabi Yūsuf, nabi yang sangat elok dan menarik hati." },
                { ar: "وَ فِي الرَّابِعَةِ إِدْرِيْسَ الَّذِيْ رَفَعَ اللّٰهُ مَكَانَهُ وَ أَعْلَاهُ؟", tr: "Wa fir-rābi‘ati Idrīsal-ladzī rafa‘allāhu makānahū wa a‘lāh.", ket: "Di langit keempat, Beliau bertemu dengan Nabi Idrīs, nabi yang ditinggikan derajatnya di hadapan Allah ta‘ālā." },
                { ar: "وَ فِي الْخَامِسَةِ هَارُوْنَ الْمُحَبَّبَ فِي الْأُمَّةِ الْإِسْرَائِيْلِيَّةِ؟", tr: "Wa fil khāmisati Hārūnal muḥabbaba fil ummatil isrā’īliyyah.", ket: "Di langit kelima, Beliau bertemu dengan Nabi Hārūn, nabi yang amat disukai oleh kaum Bani Isrā‘īl." },
                { ar: "وَ فِي السَّادِسَةِ مُوْسَى الَّذِيْ كَلَّمَهُ اللّٰهُ وَ نَاجَاهُ؟", tr: "Wa fis-sādisati Mūsal-ladzī kallamahullāhu wa nājāh.", ket: "Di langit keenam, Beliau bertemu dengan Nabi Mūsā, nabi yang diajak bicara langsung oleh Allah ta‘ālā dan bermunajat kepada-Nya." },
                { ar: "وَ فِي السَّابِعَةِ إِبْرَاهِيْمَ الَّذِيْ جَاءَ رَبَّهُ بِسَلَامَةِ الْقَلْبِ وَ الطَّوِيَّةِ؟", tr: "Wa fis-sābi‘ati Ibrāhīmal-ladzī jā’a rabbahū bisalāmatil qalbi waṭ-ṭawiyyah.", ket: "Di langit ketujuh, Beliau bertemu dengan Nabi Ibrāhīm, nabi yang selamat hatinya dan yang mempunyai sebutan baik." },
                { ar: "وَ حَفِظَهُ مِنْ نَارِ نَمْرُوْدَ وَ عَافَاهُ؟", tr: "Wa ḥafiẓahū min nāri Namrūda wa ‘āfāh.", ket: "Nabi yang dijaga oleh Allah ta‘ālā dari sengatan panas api Namrūd." },
                { ar: "ثُمَّ رُفِعَ إِلَى سِدْرَةِ الْمُنْتَهَى إِلَى أَنْ سَمِعَ صَرِيْفَ الْأَقْلَامِ بِالْأُمُوْرِ الْمَقْضِيَّةِ؟", tr: "Tsumma rufi‘a ilā sidratil muntahā ilā an sami‘a ṣarīfal aqlāmi bil umūril maqḍiyyah.", ket: "Kemudian Beliau s.a.w. dinaikkan ke Sidrat-ul-Muntahā, sehingga Beliau dapat mendengarkan goresan Qalam (Pena) di Lauḥ-ul-Maḥfūzh." },
                { ar: "إِلَى مَقَامِ الْمُكَافَحَةِ الَّذِيْ قَرَّبَهُ اللّٰهُ فِيْهِ وَ أَدْنَاهُ؟", tr: "Ilā maqāmil mukāfaḥatil-ladzī qarrabahullāhu fīhi wa adnāh.", ket: "Sampai kepada suatu tempat yang dinamakan Mukāfaḥah, di mana Beliau s.a.w. menghadap langsung dan munajat kepada Allah." },
                { ar: "وَ أَمَاطَ لَهُ حُجُبَ الْأَنْوَارِ الْجَلَالِيَّةِ؟", tr: "Wa amāṭa lahū ḥujubal anwāril jalāliyyah.", ket: "Tersingkaplah tabir yang menutupi nur keagungan-Nya." },
                { ar: "وَ أَرَاهُ بِعَيْنَيْ رَأْسِهِ مِنْ حَضْرَةِ الرُّبُوْبِيَّةِ مَا أَرَاهُ؟", tr: "Wa arāhu bi‘ainai ra’sihī min ḥaḍratir-rubūbiyyati mā arāh.", ket: "Dengan demikian, maka Beliau s.a.w. dapat memandang-Nya dengan mata kepalanya sendiri apa yang dapat dilihatnya dari sifat Ketuhanan-Nya." },
                { ar: "وَ بَسَطَ لَهُ بُسُطَ الْإِدْلَالِ فِي الْمَجَالِ الذَّاتِيَّةِ؟", tr: "Wa basaṭa lahū busuṭal idlāli fil majālidz-dzātiyyah.", ket: "Dan terbentang baginya hamparan kasih mesra pada tempat kenyataan Dzāt-Nya." },
                { ar: "وَ فَرَضَ عَلَيْهِ وَ عَلَى أُمَّتِهِ خَمْسِيْنَ صَلَاةً ثُمَّ انْهَلَّ سَحَابُ الْفَضْلِ فَرُدَّتْ إِلَى خَمْسٍ عَمَلِيَّةٍ؟", tr: "Wa faraḍa ‘alaihi wa ‘alā ummatihī khamsīna ṣalātan tsumma anhallā saḥābul faḍli fa ruddat ilā khamsin ‘amaliyyah.", ket: "Dan Allah ta‘ālā mewajibkan kepadanya dan kepada umatnya melakukan shalat lima puluh kali (waktu). Kemudian turunlah kemurahan Tuhan, akhirnya dikurangi hingga hanya tinggal lima kali yang wajib diamalkan." },
                { ar: "وَ لَهَا أَجْرُ الْخَمْسِيْنَ كَمَا شَاءَهُ فِي الْأَزَلِ وَ قَضَاهُ؟", tr: "Wa lahā ajrul khamsīna kamā syā’ahū fil azali wa qaḍāh.", ket: "Namun, pahalanya tidak berkurang dari pahala shalat lima puluh kali, sebagaimana apa yang telah dikehendaki dan dihukumkan Allah pada zaman azali dahulu kala." },
                { ar: "ثُمَّ عَادَ فِيْ لَيْلَتِهِ وَ صَدَّقَهُ الصِّدِّيْقُ بِمَسْرَاهُ؟", tr: "Tsumma ‘āda fī lailatihī wa ṣaddaqahuṣ-ṣiddīqu bimasrāh.", ket: "Kemudian Beliau s.a.w. pulang kembali pada malam itu juga, sedangkan orang yang mau membenarkan peristiwa Isrā’ Mi‘rāj-nya itu hanya Abū Bakar Shiddīq." },
                { ar: "وَ كُلُّ ذِيْ عَقْلٍ وَ رَوِيَّةٍ؟", tr: "Wa kullu dzī ‘aqlin wa rawiyyah.", ket: "Dan orang-orang yang mempunyai pikiran yang sehat." },
                { ar: "وَ كَذَّبَتْهُ قُرَيْشٌ، وَ ارْتَدَّ مَنْ أَضَلَّهُ الشَّيْطَانُ وَ أَغْوَاهُ.", tr: "Wa kadzdzabat-hu Quraisyun, wartadda man aḍallahusy-syaiṭānu wa aghwāh.", ket: "Sebaliknya, kaum Quraisy sendiri mendustakannya dan bahkan orang yang disesatkan dan ditipu oleh syaithan makin menjadi murtad." }
            ]
        },
        {
            judul: "Al Barjanji (Bai'at Aqabah & Perjalanan Hijrah)",
            isi: [
                { ar: "عَطِّرِاللّٰهُـمَّ قَبْرَهُ الْكَرِيْمِ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمٍ", tr: "‘Aththirillāhumma qabrahul karīm ۞ bi‘arfin syadziyyin min ṣalātin wa taslīm", ket: "Semoga Allah mengharumkan dan mewangikan kuburnya (Nabi) yang mulia, dengan keharuman wangi-wangian salawat dan salam sejahtera." },
                { ar: "بِسْمِ اللّٰهِ الرَّحْمنِ الرَّحِيْمِ", tr: "Bismillāhir-raḥmānir-raḥīm", ket: "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang." },
                { ar: "ثُمَّ عَرَضَ نَفْسَهُ عَلَى الْقَبَائِلِ بِأَنَّهُ رَسُوْلُ اللّٰهِ فِي الْأَيَّامِ الْمَوْسِمِيَّةِ؟", tr: "Tsumma ‘araḍa nafsahū ‘alal qabā’ili bi annahū rasūlullāhi fil ayyāmil mausimiyyah.", ket: "Kemudian Beliau s.a.w. menyatakan dengan terus-terang tentang kerasulannya kepada seluruh suku Quraisy, pada hari-hari orang melakukan ‘ibādah haji." },
                { ar: "فَآمَنَ بِهِ سِتَّةٌ مِنَ الْأَنْصَارِ اخْتَصَّهُمُ اللّٰه بِرِضَاهُ؟", tr: "Fa āmana bihī sittatun minal anṣāri ikhtaṣṣahumullāhu biriḍāh.", ket: "Terdapat enam orang dari shahabat Anshār yang suka rela menyatakan iman kepada Rasūlullāh s.a.w." },
                { ar: "وَ حَجَّ مِنْهُمْ فِي الْقَابِلِ اثْنَا عَشَرَ رَجُلًا وَ بَايَعُوْهُ بَيْعَةً خَفِيَّةً؟", tr: "Wa ḥajja minhum fil qābili itsnā ‘asyara rajulan wa bāya‘ūhu bai‘atan khafiyyah.", ket: "Pada musim haji tahun berikutnya, telah datang pula duabelas orang dari golongan shahabat Anshār yang ber‘ibādah haji serta melakukan janji prasetia kepadanya." },
                { ar: "ثُمَّ انْصَرَفُوْا، وَ ظَهَرَ الْإِسْلَامُ بِالْمَدِيْنَةِ، فَكَانَتْ مَعْقِلَهُ وَ مَأْوَاهُ؟", tr: "Tsummanṣarafū, wa ẓaharal islāmu bil madīnati, fa kānat ma‘qilahū wa ma’wāh.", ket: "Sepulangnya mereka ke tanah airnya, maka agama Islam menjadi tersiar dan tersebar luas di kota Madīnah karena kota Madīnah itu menjadi tempat pengungsian Nabi s.a.w. dan menjadi tempat tinggalnya." },
                { ar: "وَ قَدِمَ عَلَيْهِ فِي الثَّالِثِ سَبْعُوْنَ، أَوْ ثَلَاثَةٌ، وَ امْرَأَتَانِ مِنَ الْقَبَائِلِ الْأَوْسِيَّةِ وَ الْخَزْرَجِيَّةِ؟", tr: "Wa qadima ‘alaihi fits-tsālitsi sab‘ūna, au tsalātsatun, wamra’atāni minal qabā’ilil ausiyyati wal khazrajiyyah.", ket: "Pada tahun ketiga dari Hijrah, datang lagi kepadanya rombongan tujuh puluh tiga, atau tujuh puluh lima orang lelaki dan dua orang perempuan dari suku Aus dan Khazraj." },
                { ar: "فَبَايَعُوْهُ وَ أَمَّرَ عَلَيْهِمُ اثْنَا عَشَرَ نَقِيْبًا جَحَاجِحَةً سَرَاهً؟", tr: "Fa bāya‘ūhu wa ammara ‘alaihimutsnā ‘asyara naqīban jaḥājiḥatan sarāh.", ket: "Mereka menyatakan bai‘at kepada Beliau s.a.w. Dan Beliau s.a.w. memerintahkan duabelas orang dari mereka untuk memimpinnya." },
                { ar: "فَهَاجَرَ إِلَيْهِمْ مِنْ مَكَّةَ ذُو الْمِلَّةِ الْإِسْلَامِيَّةِ؟", tr: "Fa hājara ilaihim min Makkata dzul millatil islāmiyyah.", ket: "Sejak itu, mereka lalu berkemas untuk melakukan hijrah dari Makkah menuju ke Madīnah." },
                { ar: "وَ فَارَقُوا الْأَوْطَانَ، رَغْبَةً فِيْمَا أُعِدَّ لِمَنْ هَجَرَ الْكُفْرَ وَ نَاوَاهُ؟", tr: "Wa fāraqul auṭāna, raghbatan fīmā u‘idda liman hajaral kufra wa nāwāh.", ket: "Dan mereka meninggalkan tanah airnya, karena mereka sadar dengan ampunan dan pahala orang yang mau berhijrah dan meninggalkan perbuatan kufur." },
                { ar: "وَ خَافَتْ قُرَيْشٌ أَنْ يَلْحَقَ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ بِأَصْحَابِهِ عَلَى الْفَوْرِيَّةِ؟", tr: "Wa khāfat Quraisyun an yalḥaqa ṣallallāhu ‘alaihi wa sallama bi aṣḥābihī ‘alal fauriyyah.", ket: "Melihat keadaan yang semacam ini, kaum Quraisy merasa khawatir jika Beliau s.a.w. sendiri akan menyusul hijrah mengikuti jejak para shahabatnya." },
                { ar: "فَأْتَمَرُوْا بِقَتْلِهِ، فَحَفِظَهُ اللّٰهُ مِنْ كَيْدِهِمْ وَ نَجَاهُ؟", tr: "Fa’tamarū biqatlihī, fa ḥafiẓahullāhu min kaidihim wa najāh.", ket: "Lalu mereka bersidang untuk membunuh Beliau. Akan tetap, Beliau dipelihara dan diselamatkan Allah ta‘ālā dari usaha jahat mereka." },
                { ar: "وَ أَذِنَ لَهُ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ فِي الْهِجْرَةِ، فَرَقِبَهُ الْمُشْرِكُوْنَ لِيُوْرِدُوْهُ بِزَعْمِهِمْ حِيَاضَ الْمَنِيَّةِ؟", tr: "Wa adzina lahū ṣallallāhu ‘alaihi wa sallama fil hijrati, fa raqibahul musyrikūna liyūridūhu bi za‘mihim ḥiyāḍal maniyyah.", ket: "Kemudian Beliau diidzinkan untuk berhijrah ke Madīnah. Dan rencana ini telah diketahui oleh kaum musyrikīn, kemudian mereka melakukan pengintaian dan pengepungan rumahnya, yang bermaksud untuk membunuhnya." },
                { ar: "فَخَرَجَ عَلَيْهِمْ وَ نَثَرَ عَلَى رُؤُوْسِهِمُ التُّرَابَ وَ حَثَاهُ؟", tr: "Fa kharaja ‘alaihim wa natsara ‘alā ru’ūsihimut turāba wa ḥatsāh.", ket: "Akan tetapi Beliau s.a.w. berhasil lolos keluar dari rumahnya dengan menaburkan tanah di atas kepala mereka." },
                { ar: "وَ أَمَّ غَارَ ثَوْرٍ وَ فَازَ الصِّدِّيْقُ فِيْهِ بِالْمَعِيَّةِ؟", tr: "Wa amma ghāra Tsaurin wa fāzaṣ-ṣiddīqu fīhi bil ma‘iyyah.", ket: "Dan Beliau s.a.w. berangkat menuju gua Tsaur untuk sementara waktu bersembunyi bersama-sama dengan Abū Bakar Shiddīq." },
                { ar: "وَ أَقَامَا فِيْهِ ثَلَاثًا تَحْمِي الْحَمَائِمُ وَ الْعَنَاكِبُ حِمَاهُ؟", tr: "Wa aqāmā fīhi tsalātsan taḥmil ḥamā’imu wal ‘anākibu ḥimāh.", ket: "Beliau berdua bersembunyi di gua Tsaur selama tiga hari. Mereka mendapat perlindungan dari burung-burung dan labah-labah yang membuat sarangnya di pintu gua Tsaur." },
                { ar: "ثُمَّ خَرَجَا مِنْهُ وَ هُوَ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ عَلَى خَيْرِ مَطِيَّةٍ؟", tr: "Tsumma kharajā minhu wa huwa ṣallallāhu ‘alaihi wa sallama ‘alā khairi maṭiyyah.", ket: "Kemudian pada malam Senin, Beliau berdua keluar dari gua dengan berkendaraan unta yang sangat cepat jalannya." },
                { ar: "وَ تَعَرَّضَ لَهُ سُرَاقَةُ، فَابْتَهَلَ فِيْهِ إِلَى اللّٰهِ وَ دَعَاهُ؟", tr: "Wa ta‘arraḍa lahū Surāqatu, fabtahala fīhi ilallāhi wa da‘āh.", ket: "Akan tetapi, Beliau di tengah jalan dihadang oleh Surāqah, maka berdoalah Beliau kepada Allah memohon perlindungan-Nya." },
                { ar: "فَسَاخَتْ قَوَائِمُ يَعْبُوْ بِهِ فِي الْأَرْضِ الصَّلْبَةِ القَوِيَّة؟", tr: "Fa sākhat qawā’imu ya‘bū bihī fil arḍiṣ-ṣalbati al-qawiyyah.", ket: "Tiba-tiba, keempat kaki kendaraan Surāqah terbenam ke dalam bumi yang keras." },
                { ar: "وَ سَأَلَهُ الْأَمَانَ، فَمَنَحَهُ إِيَّاهُ؟", tr: "Wa sa’alahul amāna, fa manaḥahū iyyāh.", ket: "Maka Surāqah minta ampun dan keselamatan kepada Nabi Muḥammad s.a.w. lantas Beliau s.a.w. mengampuninya." }
            ]
        },
        {
            judul: "Al Barjanji (Tiba di Madinah)",
            isi: [
                { ar: "عَطِّرِاللّٰهُـمَّ قَبْرَهُ الْكَرِيْمِ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمٍ", tr: "‘Aththirillāhumma qabrahul karīm ۞ bi‘arfin syadziyyin min ṣalātin wa taslīm", ket: "Semoga Allah mengharumkan dan mewangikan kuburnya (Nabi) yang mulia, dengan keharuman wangi-wangian salawat dan salam sejahtera." },
                { ar: "بِسْمِ اللّٰهِ الرَّحْمنِ الرَّحِيْمِ", tr: "Bismillāhir-raḥmānir-raḥīm", ket: "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang." },
                { ar: "وَ مَرَّ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ بقُدَيْدٍ عَلَى أُمِّ مَعْبَدٍ الْخُزَاعِيَّةِ؟", tr: "Wa marra ṣallallāhu ‘alaihi wa sallama bi Qudaidin ‘alā Ummi Ma‘badinil Khuzā‘iyyah.", ket: "Dalam perjalanan ke Madīnah, Beliau yang melalui perkampungan bernama Qudaid, tempat tinggal Ummi Ma'bad al-Khuza'i." },
                { ar: "وَ أَرَادَ ابْتِيَاعَ لَحْمٍ لَبَنٍ أَوْ مِنْهَا، فَلَمْ يَكُنْ خِبَاؤُهَا لشَّيْءٍ مِنْ ذلِكَ قَدْ حَوَاهُ؟", tr: "Wa arāda ibtiyā‘a laḥmin labanin au minhā, fa lam yakun khibā’uhā lisyai’in min dzālika qad ḥawāh.", ket: "Beliau bermaksud akan membeli daging atau susu daripadanya. Akan tetapi, Ummu Ma‘bad ketika itu tidak mempunyai persediaan." },
                { ar: "فَنَظَرَ إِلَى شَاةٍ فِي الْبَيْتِ قَدْ خَلَّفَهَا الْجَهْدُ عَنِ الرَّعِيَّةِ؟", tr: "Fa naẓara ilā syātin fil baiti qad khallafahal jahdu ‘anir-ra‘iyyah.", ket: "Lalu Beliau Sholallahu 'alaihi wasallam melihat seekor biri-biri kurus di rumah itu yang tidak digembalakan, karena sakit." },
                { ar: "فَاسْتَأْذَنَهَا فِيْ حَلْبِهَا، فَأَذِنَتْ وَ قَالَتْ: لَوْ كَانَ بِهَا حَلَبٌ لَأَصَبْنَاهُ؟", tr: "Fastadzanahā fī ḥalbihā, fa adzinat wa qālat: Lau kāna bihā ḥalabun la aṣabnāh.", ket: "Maka Beliau Sholallahu 'alaihi wasallam minta idzin kepadanya untuk memerah susu kambing itu. Ummu Ma‘bad tidak berkeberatan dan katanya: “Jika ada air susunya tentu sudah kami perah.”" },
                { ar: "فَمَسَحَ الضَّرْعَ مِنْهَا وَ دَعَا اللّٰهَ مَوْلَاهُ وَ وَلِيَّهُ؟", tr: "Fa masaḥaḍ-ḍar‘a minhā wa da‘allāha maulāhu wa waliyyah.", ket: "Beliau Sholallahu 'alaihi wasallam mengusapkan tangannya pada kambing itu sambil berdoa kepada Allah ta‘ālā." },
                { ar: "فَدَرَّتْ فَحَلَبَ، وَ سَقَى كُلًّا مِنَ الْقَوْمِ وَ أَرْوَاهُ؟", tr: "Fa darrat fa ḥalaba, wa saqā kullan minal qaumi wa arwāh.", ket: "Tiba-tiba, keluarlah air susu kambing itu dengan derasnya, sehingga dapat diminum untuk Beliau Sholallahu 'alaihi wasallam dan orang-orang sekitar rumah itu." },
                { ar: "ثُمَّ حَلَبَ وَ مَلَأَ الْإِنَاءَ وَ غَادَرَهُ لَدَيْهَا آيَةً جَلِيَّةً؟", tr: "Tsumma ḥalaba wa mala’al inā’a wa ghādarahū ladaihā āyatan jaliyyah.", ket: "Lalu Beliau Sholallahu 'alaihi wasallam memerah lagi. Dan setelah penuh satu bejana, ditinggalkannya buat Ummu Ma‘bad." },
                { ar: "فَجَاءَ أَبُوْ مَعْبَدٍ وَ رَأَى اللَّبَنَ، فَذَهَبَ بِهِ الْعَجَبُ إِلَى أَقْصَاهُ؟", tr: "Fa jā’a Abū Ma‘badin wa ra’al labana, fa dzahaba bihil ‘ajabu ilā aqṣāh.", ket: "Ketika Abū Ma‘bad telah datang dari bepergian dan melihat susu ada di rumahnya, maka timbul keheranannya." },
                { ar: "وَ قَالَ: أَنِّيْ لَكِ هذَا، وَ لَا حَلُوْبَ بِالْبَيْتِ تَبِضُّ بقَطْرَةٍ لَبَنِيَّة؟", tr: "Wa qāla: Annī laki hādzā, wa lā ḥalūba bil baiti tabiḍḍu biqaṭratin labaniyyah.", ket: "Katanya kepada istrinya: “Dari mana kau peroleh air susu sebanyak ini?, sedangkan kita tidak mempunyai kambing yang ada susunya.”" },
                { ar: "!فَقَالَتْ: مَرَّ بِنَا رَجُلٌ مُبَارَكٌ كَذَا وَ كَذَا جُثْمَانُهُ وَ مَعْنَاهُ؟", tr: "Fa qālat: Marra binā rajulun mubārakun kadzā wa kadzā jutsmānuhū wa ma‘nāh.", ket: "Jawab istrinya: “Tadi ada seorang lelaki yang membawa berkah datang kemari, rupanya….begini, yang sederhana tubuhnya dan lemah-lembut sifatnya." },
                { ar: "فَقَالَ هذَا صَاحِبُ قُرَيْش، وَ أَقْسَمَ بِكلِّ آلهِيَّةٍ؟", tr: "Fa qāla hādzā ṣāḥibu Quraisy, wa aqsama bikulli ālahiyyah.", ket: "Suaminya berkata: “Itulah dia, orang dari Quraisy. Dan dia terus bersumpah-sumpah." },
                { ar: "بِأَنَّهُ لَوْ رَآهُ، لَآمَنَ بِهِ وَ اتَّبَعَهُ وَ دَنَاهُ؟", tr: "Bi annahū lau ra’āhu, la āmana bihī wattaba‘ahū wa danāh.", ket: "Seandainya ia dapat melihatnya, niscaya dia beriman kepadanya dan mengikuti jejak langkahnya, serta senantiasa menemaninya." },
                { ar: "وَ قَدِمَ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ الْمَدِيْنَةَ يَوْمَ الْاِثْنَيْنِ ثَانِيْ عَشَرَ رَبِيْعِ الْأَوَّلِ، وَ أَشْرَقَتْ بِهِ أَرْجَاؤُهَا الزَّكِيَّةُ؟", tr: "Wa qadima ṣallallāhu ‘alaihi wa sallamal Madīnata yaumal itsnaini tsāniya ‘asyara Rabī‘il awwali, wa asyraqat bihī arjā’uhaz-zakiyyah.", ket: "Pada tanggal 12 Rabī‘-ul-Awwal, sampailah Beliau di Madīnah, dan tempat-tempat di Madīnah ketika itu menjadi terang-benderang sebab nūrnya." },
                { ar: "وَ تَلَقَّاهُ الْأَنْصَارُ، وَ نَزَلَ بِقُبَّاءَ وَ أَسَّسَ مَسْجِدَهَا عَلَى تَقْوَاهُ؟", tr: "Wa talaqqāhul anṣāru, wa nazala biqubbā’a wa assasa masjidahā ‘alā taqwāh.", ket: "Dan setelah sampai di sana, Beliau Sholallahu 'alaihi wasallam disambut oleh sahabat Anshār dan singgah di Qubbā’ untuk membina masjid yang berdasarkan taqwā." }
            ]
        },
        {
            judul: "Al Barjanji (Sifat & Rupa Nabi)",
            isi: [
                { ar: "عَطِّرِاللّٰهُـمَّ قَبْرَهُ الْكَرِيْمِ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمٍ", tr: "‘Aththirillāhumma qabrahul karīm ۞ bi‘arfin syadziyyin min ṣalātin wa taslīm", ket: "Semoga Allah mengharumkan dan mewangikan kuburnya (Nabi) yang mulia, dengan keharuman wangi-wangian salawat dan salam sejahtera." },
                { ar: "بِسْمِ اللّٰهِ الرَّحْمنِ الرَّحِيْمِ", tr: "Bismillāhir-raḥmānir-raḥīm", ket: "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang." },
                { ar: "وَ كَانَ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ أَكْمَلَ النَّاسِ خَلْقًا وَ خُلُقًا ذَا ذَاتٍ وَ صِفَاتٍ سَنِيَّةٍ،", tr: "Wa kāna ṣallallāhu ‘alaihi wa sallama akmalan-nāsi khalqan wa khuluqan dzā dzātin wa ṣifātin saniyyah.", ket: "Nabi Muḥammad Sholallahu 'alaihi wasallam adalah orang yang paling sempurna kejadiannya dan akhlaqnya, yang mempunyai sikap dan sifat yang luhur." },
                { ar: "مَرْبُوْعَ الْقامَةِ، أَبْيَضَ اللَّوْنِ مُشَرَّبًا بِحُمْرَةٍ وَاسِعَ الْعَيْنَيْنِ أَكْحَلَهُمَا، أَهْدَبَ الْأَشْفَارِ قَدْ مُنِحَ الزَّجَجَ حَاجِبَاهُ؟", tr: "Marbū‘al qāmati, abyaḍal launi musyarraban biḥumratin wāsi‘al ‘ainaini akḥalahumā, ahdabal asyfāri qad muniḥaz-zajaja ḥājibāh.", ket: "Sederhana tingginya, putih kulitnya agak kemerahan, dua belah matanya melebar, seolah-olah bercelak, lembut bulu matanya, dua kening melengkung dan lembut rambutnya." },
                { ar: "مُفَلَّجَ الْأَسْنَانِ، وَاسِعَ الْفَمِ حَسَنَهُ، وَاسِعَ الْجَبِيْنِ ذَا جَبْهَةٍ هِلَالِيَّةٍ،", tr: "Mufallajal asnāni, wāsi‘al fami ḥasanahū, wāsi‘al jabīni dzā jabhatin hilāliyyah.", ket: "Bergigi rapih dan putih bersih, lebar mulutnya dan terlihat menarik, lebar kanan kiri dahinya, dahinya bagaikan bulan sabit." },
                { ar: "سَهْلَ الْخَدَّيْنِ يُرَى فِيْ أَنْفِهِ بَعْضُ احْدِيْدَابٍ، حَسَنَ الْعِرْنَيْنِ أَقْنَاهُ؟", tr: "Sahlal khaddaini yurā fī anfihī ba‘ḍuḥdīdābin, ḥasanal ‘irnaini aqnāh.", ket: "Yang halus pipinya, berhidung mancung dan bagus pangkal hidungnya." },
                { ar: "بَعِيْدَ مَا بَيْنَ الْمَنْكَبَيْنِ، سَبْطَ الْكَتِفَيْنِ، ضَخْمَ الْكَرَادِيْسِ، قَلِيْلَ لَحْمِ الْعَقِبِ، كَثَّ اللِّحْيَةِ، عَظِيْمَ الرَّأْسِ، شَعْرُهُ إِلَى الشَّحْمَةِ الْأُذُنِيَّةِ،", tr: "Ba‘īda mā bainal mankibaini, sabṭal katifaini, ḍakhmal karādīsi, qalīla laḥmil ‘aqibi, katsal liḥyati, ‘aẓīmar-ra’si, sya‘ruhū ilasy-syaḥmatil udzuniyyah.", ket: "Renggang jarak antara dua tulang belikatnya, sederhana dua tapak tangannya, tulang-tulang sendinya besar, tipis tapak kakinya, tebal rambut jenggotnya, kepalanya besar, rambutnya panjang terurai hingga di bawah telinga." },
                { ar: "وَ بَيْنَ كَتِفَيْهِ خَاتَمُ النُّبُوَّةِ قَدْ عَمَّهُ النُّورُ وَ عَلَاهُ؟", tr: "Wa baina katifaihi khātamun-nubuwwati qad ‘ammahun-nūru wa ‘alāh.", ket: "Di antara dua tulang belikatnya terdapat tanda kenabian, cemerlang memancarkan cahaya." },
                { ar: "وَ عَرَقُهُ كَاللُّؤْلُؤِ، وَ عَرْفُهُ أَطْيَبُ مِنَ النَّفَحَاتِ الْمِسْكِيَّةِ،", tr: "Wa ‘araquhū kal-lu’lu’i, wa ‘ar-fuhū aṭyabu minan-nafaḥātil miskiyyah.", ket: "Air keringatnya laksana butir-butir mutiara, yang berbau (wangi) lebih semerbak dibanding dari bau minyak kasturi." },
                { ar: "وَ يَتَكَفَّأُ فِيْ مَشْيَتِهِ، كَأَنَّمَا يَنْحَطُّ مِنْ صَبَبٍ ارْتَقَاهُ؟", tr: "Wa yatakaffa’u fī masyyatihī, ka’annamā yanḥaṭṭu min ṣababin irtaqāh.", ket: "Langkahnya tenang dan sopan, jalannya condong, seolah-olah turun dari tempat yang tinggi." },
                { ar: "وَ كَانَ يُصَافِحُ الْمُصَافِحَ بِيَدِهِ الشَّرِيْفَةِ؟", tr: "Wa kāna yuṣāfiḥul muṣāfiḥa bi yadihisy-syarīfah.", ket: "Beliau Sholallahu 'alaihi wasallam suka berjabat tangan dengan orang yang mau berjabat tangan dengan tangannya yang mulia." },
                { ar: "فَيَجِدُ مِنْهَا سَائِرَ الْيَوْمِ رَائِحَةً عَبْهَرِيَّةً،", tr: "Fa yajidu minhā sā’iral yaumi rā’iḥatan ‘abhariyyah.", ket: "Dan jika berjabat tangan dengan tangannya yang mulia itu, maka bekas bau semerbak pada tangannya itu masih ada dalam beberapa hari." },
                { ar: "وَ يَضَعُهَا عَلَى رَأْسِ الصَّبِيِّ،", tr: "Wa yaḍa‘uhā ‘alā ra’siṣ-ṣabiyyi.", ket: "Jika beliau menjamah kepala anak kecil." },
                { ar: "فَيُعْرَفُ مَسُّهُ لَهُ مِنْ بَيْنِ الصِّبْيَةِ وَ يُدْرَاهُ؟", tr: "Fa yu‘rafu massuhū lahū min bainis-ṣibyati wa yudrāh.", ket: "Maka anak-anak kecil lainnya dapat mengenalnya, bahwa kepalanya bekas dijamah oleh Beliau Sholallahu 'alaihi wasallam, karena baunya yang semerbak itu." },
                { ar: "يَتَلَأْلَأُ وَجْهُهُ الشَّرِيْفُ تَلَأْلُؤَ الْقَمَرَ فِي اللَّيْلَةِ البَدْرِيَّةِ،", tr: "Yatala’la’u wajhuhusy-syarīfu tala’lu’al qamara fil lailatil badriyyah.", ket: "Wajahnya berseri-seri bagaikan bulan pada malam bulan purnama." },
                { ar: "يَقُوْلُ نَاعِتُهُ: لَمْ أَرَ قَبْلَهُ وَ لَا بَعْدَهُ مِثْلَهُ، وَ لَا بَشَرٌ يَرَاهُ؟", tr: "Yaqūlu nā‘ituhū: Lam ara qablahū wa lā ba‘dahū mitslahū, wa lā basyarun yarāh.", ket: "Orang yang biasa menyifati/mengisahkan tentang Beliau Sholallahu 'alaihi wasallam, mengatakan: “Saya belum pernah melihat seseorang yang dapat menyamai dengan Beliau Sholallahu 'alaihi wasallam, sejak dahulu hingga sekarang.”" }
            ]
        },
        {
            judul: "Al Barjanji (Akhlak & Kepribadian Nabi)",
            isi: [
                { ar: "عَطِّرِاللّٰهُـمَّ قَبْرَهُ الْكَرِيْمِ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمٍ", tr: "‘Aththirillāhumma qabrahul karīm ۞ bi‘arfin syadziyyin min ṣalātin wa taslīm", ket: "Semoga Allah mengharumkan dan mewangikan kuburnya (Nabi) yang mulia, dengan keharuman wangi-wangian salawat dan salam sejahtera." },
                { ar: "بِسْمِ اللّٰهِ الرَّحْمنِ الرَّحِيْمِ", tr: "Bismillāhir-raḥmānir-raḥīm", ket: "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang." },
                { ar: "وَ كَانَ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ شَدِيْدَ الْحَيَاءِ وَ التَّوَاضُعِ يَخْصِفُ نَعْلُهُ، وَ يَرْقَعُ ثَوْبَهُ، وَ يَحْلِبُ شَاتَهُ، وَ يَسِيْرُ فِيْ خِدْمَةِ أَهْلِهِ بِسِيْرَةٍ سَرِيَّةٍ،", tr: "Wa kāna ṣallallāhu ‘alaihi wa sallama syadīdal ḥayā’i wat-tawāḍu‘i yakhṣifu na‘lahū, wa yarqa‘u tsaubahū, wa yaḥlibu syātahū, wa yasīru fī khidmati ahlihī bisīratin sarīrah.", ket: "Beliau Sholallahu 'alaihi wasallam adalah seorang yang sangat pemalu dan tawadhu‘, mau memperbaiki terompanya sendiri, dan mau menambal pakaiannya sendiri, mau memerah kambingnya dan mau membantu keperluan dalam rumah tangganya." },
                { ar: "وَ يُحِبُّ الْفُقَرَاءَ وَ الْمَسَاكِيْنَ وَ يَجْلِسُ مَعَهُمْ، وَ يَعُوْدُ مَرْضَاهُمْ وَ يُشَيَّعُ جَنَائِزَهُمْ، وَ لَا يَحْقِرُ فَقِيْرًا أَدْقَعَهُ الْفَقْرُ وَ أَشْوَاهُ؟", tr: "Wa yuḥibbul fuqarā’a wal masākīna wa yajlisu ma‘ahum, wa ya‘ūdu marḍāhum wa yusyayya‘u janā’izahum, wa lā yaḥqiru faqīran adqa‘ahul faqru wa asywāh.", ket: "Beliau menyukai orang fakir dan miskin, dan suka duduk bersama-sama mereka, mau meninjau orang yang sakit di antara mereka, mau mengantar jenazah mereka, dan tidak mau menghina orang fakir, betapapun miskin dan melaratnya orang itu." },
                { ar: "وَ يَقْبَلُ الْمَعْذِرَةِ، وَ لَا يُقَابِلُ أَحَدًا بِمَا يَكْرَهُ، وَ يَمْشِيْ مَعَ الْأَرْمِلَةِ وَ ذَوِي الْعُبُوْدِيَّة،", tr: "Wa yaqbalul ma‘dzirati, wa lā yuqābilu aḥadan bimā yakrah, wa yamsyī ma‘al armalati wa dzawil ‘ubūdiyyah.", ket: "Beliau suka memberi maaf, dan tidak pernah membalas orang dengan yang tidak disukai, dan mau berjalan dengan orang-orang yang lemah dan para budak beliau." },
                { ar: "وَ لَا يَهَابُ الْمُلُوْك، وَ يَغْضَبُ للّٰهِ تَعَالَى وَ يَرْضَى لِرِضَاهُ؟", tr: "Wa lā yahābul mulūk, wa yaghḍabu lillāhi ta‘ālā wa yarḍā liriḍāh.", ket: "Beliau tidak pernah merasa gentar menghadapi para raja. Beliau marah karena Allah, dan ridha juga karena-Nya." },
                { ar: "وَ يَمْشِيْ خَلْفَ أَصْحَابِهِ وَ يَقُوْلُ: (خَلُّوْ ظَهْرِيْ لِلْمَلَائِكَةِ الرُّوْحَانِيَّةِ)،", tr: "Wa yamsyī khalfa aṣḥābihī wa yaqūlu: (Khallū ẓahrī lil malā’ikatir rūḥāniyyah).", ket: "Beliau berjalan di belakang para sahabatnya, Beliau berkata: “Berjalanlah kalian di depan, biarlah di belakangku untuk para malaikat.”" },
                { ar: "وَ يَرْكَبُ الْبَعِيْرَ، وَ الْفَرَسَ، وَ الْبَغْلَةَ، وَ حِمَارًا بَعْضُ الْمُلُوْكِ إِلَيْهِ أَهْدَاهُ؟", tr: "Wa yarkabul ba‘īra, wal farasa, wal baghlata, wa ḥimāran ba‘ḍul mulūki ilaihi ahdāh.", ket: "Mau berkendaraan unta, kuda, bighal, dan keledai dari hadiah sebagian raja-raja." },
                { ar: "وَ يَعْصِبُ عَلَى بَطْنِهِ الْحَجَرَ مِنَ الْجُوْعِ، وَ قَدْ أُوْتِيَ مَفَاتِيْحَ الْخَزَائِنِ الْأَرْضِيَّةِ،", tr: "Wa ya‘ṣibu ‘alā baṭnihil ḥajara minal jū‘i, wa qad ūtiya mafātīḥal khazā’inil arḍiyyah.", ket: "Untuk menanggulangi rasa lapar, maka Beliau acap kali membungkus batu dengan kain yang diikatkan pada perutnya. Padahal, kunci perbendaharaan bumi berada di tangannya." },
                { ar: "وَ رَاوَدَتْهُ الْجِبَالُ بِأَنْ تَكُوْنَ لَهُ ذَهَبًا فَأَبَاهُ؟", tr: "Wa rāwadathul jibālu bi an takūna lahū dzahaban fa abāh.", ket: "Dan gunung-gunung menawarkan diri untuk dijadikan gunung emas untuk keperluannya, tetapi ditolaknya." },
                { ar: "وَ كَانَ صَلَّى اللّٰهُ عَلَيْهِ وَ سَلَّمَ يُقِلُّ اللَّغْوَ، وَ يَبْدَأُ مَنْ لَقِيَهُ بِالسَّلَامِ،", tr: "Wa kāna ṣallallāhu ‘alaihi wa sallama yuqillul laghwa, wa yabda’u man laqiyahū bis-salām.", ket: "Beliau tidak suka bicara, melainkan seperlunya saja. Dan Beliau suka mulai memberi salam kepada orang yang dijumpainya." },
                { ar: "وَ يُطِيْلُ الصَّلَاةَ وَ يَقْصُرُ الْخُطَبَ الْجُمَعِيَّةَ،", tr: "Wa yuṭīluṣ-ṣalāta wa yaqṣurul khuṭabal jumu‘iyyah.", ket: "Beliau suka memperlamakan shalat dan mempersingkat khutbah Jum‘at." },
                { ar: "وَ يَتَأَلَّفُ أَهْلَ الشَّرَفِ، وَ يُكْرِمُ أَهْلَ الْفَضْلِ، وَ يَمْزَحُ وَ لَا يَقُوْلُ إِلَّا حَقًّا يُحِبُّهُ اللّٰهُ تَعَالَى وَ يَرْضَاهُ؟", tr: "Wa yata’allafu ahlasy-syarafi, wa yukrimu ahlal faḍli, wa yamzaḥu wa lā yaqūlu illā ḥaqqan yuḥibbuhullāhu ta‘ālā wa yarḍāh.", ket: "Beliau menyukai orang yang mulia, menghormati orang yang utama, bersenda-gurau dengan sahabat-sahabatnya. Dan Beliau tidak pernah berbicara melainkan yang benar-benar saja, yang disukai Allah ta‘ala dan diridhā’i-Nya." },
                { ar: "وَ هَا هُنَا وَقَفَ بِنَا جَوَادُ الْمَقَالِ عَنِ الْطِّرَادِ فِي الْحَلْبَةِ الْبَيَانِيَّة،", tr: "Wa hā hunā waqafa binā jawādul maqāli ‘aniṭ-ṭirādi fil ḥalbatil bayāniyyah.", ket: "Hanya sampai di sini kita cukupkan dahulu tentang kisah kehidupan Nabi Muḥammad Sholallahu 'alaihi wasallam." },
                { ar: "وَ بَلَغَ ضَاعِنُ الْإِمْلَاءِ فِيْ فَدَافِدِ الْإِيْضَاحِ مُنْتَهَاهُ؟", tr: "Wa balagha ḍā‘inul imlā’i fī fadāfidil īḍāḥi muntahāh.", ket: "Dan mudah-mudahan riwayat ini akan memberikan kejelasan tentang kisah kehidupan Beliau Sholallahu 'alaihi wasallam, mendatangkan faedah dan kepuasan bagi para pembaca." }
            ]
        },
        {
            judul: "Ya Nabi Salam Alaika",
            isi: [
                { ar: "اَللّٰهُـمَّ صَلِّ وَسَلِّمْ وَبَارِكْ عَلَيْهِ", tr: "Allâhumma shalli wa sallim wa bârik ‘alaih", ket: "Ya Allah, berilah salawat dan salam serta berkah atas Nabi s.a.w." },
                { ar: "يَانَبِى سَلَامٌ عَلَيْكَ ۞ يَارَسُوْلَ سَلَامٌ عَلَيْكَ", tr: "Yaa Nabii Salamun Alaika, Yaa Rosuul Salamun Alaika", ket: "Wahai Nabi, Wahai Rasul, salam sejahtera untukmu." },
                { ar: "يَاحَبِيْبْ سَلَامٌ عَلَيْكَ ۞ صَلَوَاتُ اللّٰهِ عَلَيْكَ", tr: "Yaa Habiib Salam Alaika, Sholawaa Tullooh Alaika", ket: "Wahai kekasih Allah, salam sejahteraan Rahmat Allah untukmu." },
                { ar: "أَشْرَقَ الْبَدْرُ عَلَيْنَا ۞ فَاخْتَفَتْ مِنْهُ الْبُدُوْرُ", tr: "Asyrokol Badru Alainaa, Fakh Tafatc Minhul Buduuru", ket: "Bulan purnama telah terbit menyinari kami, pudarlah purnama-purnama lainnya." },
                { ar: "مِثْلَ حُسْنِكْ مَا رَأَيْنَا ۞ قَطُّ يَاوَجْهَ السُّرُوْرِ", tr: "Mitslahus Nikmaa Ro Ainaa, Quth Thuyaa Wajhassuruuri", ket: "Belum pernah aku melihat keelokan sepertimu wahai orang yang berwajah riang." },
                { ar: "أَنْتَ شَمْسٌ أَنْتَ بَدْرٌ ۞ أَنْتَ نُوْرٌ فَوْقَ نُوْرِ", tr: "Angta Syam Sun Antabadru, Angtanuu Rungfauqonuri", ket: "Engkau bagai matahari, engkau bagai bulan purnama, engkau cahaya di atas cahaya." },
                { ar: "أَنْتَ إِكْسِيْرُ وَغَالِى ۞ أَنْتَ مِصْبَاحُ الصُّدُوْرِ", tr: "Angta Iksiiruwwagholii, Angtamish Baahush Shuduuri", ket: "Engkau bagaikan emas murni yang mahal harganya. Engkaulah pelita hati." },
                { ar: "يَاحَبِيْبِى يَامُحَمَّدْ ۞ يَاعَرُوْسَ الْخَافِقَيْنِ", tr: "Yaa Habiibii Yaa Muhammadu, Yaa A'Ruusal Khoofi Qoini", ket: "Wahai kekasihku, Wahai Muhammad ﷺ wahai pengantin tanah timur dan barat (sedunia)." },
                { ar: "يَامُؤَيَّدْ يَامُمَجَّدْ ۞ يَاإِمَامَ الْقِبْلَتَيْنِ", tr: "Yaa Mu Ayyad Yaa Mumajjad, Yaa Imaa Mal Qiblataini", ket: "Wahai nabi yang dikuatkan (dengan wahyu) diagungkan, wahai imam dua arah kiblat." },
                { ar: "مَنْ رَاَى وَجْهَكَ يَسْعَدْ ۞ يَاكَرِيْمَ الْوَالِدَيْنِ", tr: "Marro Aawajhaka Yas A'D, Yaakariimalwalidaini", ket: "Siapapun yang melihat wajahmu pasti bahagia. Wahai orang yang mulia kedua orang tuanya." },
                { ar: "حَوْضُكَ الصَّافِى الْمُبَرَّدْ ۞ وِرْدُنَا يَوْمَ النُّشُوْرِ", tr: "Haudhukash Shoofil Mubarrod, Wirdunaa Yaumannusyuuri", ket: "Telagamu jernih dan dingin, yang akan kami datangi di hari kiamat kelak." },
                { ar: "مَا رَاَيْنَا الْعِيْسَ حَنَّتْ ۞ بِالسُّرَى إِلَّا إِلَيْكَ", tr: "Maa Ro Ainaal I'Isahannatc, Bissuroo Illaa Ilaika", ket: "Pernah melihat unta putih berbalur hitam berdenting berjalan malam kecuali unta yang datang kepadamu." },
                { ar: "وَالْغَمَامَةْ قَدْ أَظَلَتْ ۞ وَالْمَلَا صَلُّوْا عَلَيْكَ", tr: "Walghomaa Mat Qod Azhollatc, Wal Malaa Sholluu Alaika", ket: "Tebal selalu memayungimu, seluruh tingkatan (dan) golongan manusia mengucapkan sholawat kepadamu." },
                { ar: "وَأَتَاكَ الْعُوْدُ يَبْكِى ۞ وَتَذَلَّلْ بَيْنَ يَدَيْكَ", tr: "Wa Ataakal Uuduyabkii, Watadzallalbaina Yadaika", ket: "Pohon-pohon datang kepadamu menangis bersimpuh, dan merasahina dihadapanmu." },
                { ar: "وَاسْتَجَارَتْ يَاحَبِيْبِىْ ۞ عِنْدَكَ الظَّبْيُ النُّفُوْرِ", tr: "Wastajaa Rotc Yaa Habiibii, I'Ndakazh Zhobyunnufuuru", ket: "Kijang gesit datang memohon keselamatan kepadamu wahai kekasih." },
                { ar: "عِنْدَمَا شَدُّو الْمَحَامِلْ ۞ وَتَنَادَوْا لِلرَّحِيْلِ", tr: "'Indamaa Syaduul Mahaamil, Watanaa Daulirrohiil", ket: "Ketika serombongan berkemas dan menyerukan untuk berangkat." },
                { ar: "جِئْتُهُمْ وَالدَّمْعُ سَآئِلْ ۞ قُلْتُ قِفْ لِى يَادَلِيْلُ", tr: "Ji Tuhum Waddam Usaa Il, Qultuqiflii Yaa Daadaliilu", ket: "Kudatangi mereka dengan berlinang air mata, seraya kuucapkan “tunggulah wahai pimpinan rombongan." },
                { ar: "هَلْ تُحَمِّلْ لِى رَسَائِلْ ۞ أَيُّهَا الشَّوْقُ الْجَزِيْلُ", tr: "Hal Tuhammil Lii Rosaa Iil, Ayyuhaa Syaauquljaziilu", ket: "Apakah engkau membawakan surat untukku yang berisikan kerinduan yang mendalam." },
                { ar: "نَحْوَهَا تِيْكَ الْمَنَازِلْ ۞ بِالْعَشِيِّ وَالْبُكُوْرِ", tr: "Nahwahaa Tiikalmanaazzil, Bil A'Siyyi Walbukuuri", ket: "Seperti membawakanmu ke tempat yang jauh, ketika petang dan paginya datang." },
                { ar: "كُلُّ مَنْ فِى الْكَوْنِ هَامُوْا ۞ فِيْكَ يَابَاهِى الْجَبِيْنِ", tr: "Kullumang Fil Kauni Haamuu, Fiikayaa Baahiil Jabiini", ket: "Jagad raya ini bingung (disebabkan karena rindu) kepadamu wahai orang yang bersinar kedua keningnya." },
                { ar: "وَلَهُمْ فِيْكَ غَرَامُ ۞ وَاشْتِيَاقُ وَحَنِيْنُ", tr: "Walahum Fiikaghoromun, Waasy Tiyaa Quwwahaniinun", ket: "Mereka terpikat, tergila-gila dan meronta-ronta dengamu tentang sifat-sifatmu." },
                { ar: "فِى مَعَانِيْكَ اْلأَنَامُ ۞ قَدْ تَبَدَتْ حَائِرِيْنَ", tr: "Fiima 'Aaniikal Anaamu, Qodtabbadatc Haa Iriina", ket: "Para makhluk berbeda pendapat dan bingung tidak mampu menyifati dengan sempurna." },
                { ar: "أَنْتَ لِلرُّسْلِ خِتَامُ ۞ أَنْتَ لِلْمَوْلَى شَكُوْرُ", tr: "Angta Lirrusuli Jitaamu, Angtalil Maulaa Syakuuru", ket: "Engkau adalah penutup para utusan, Engkau adalah orang yang paling banyak bersyukur kepada Allah." },
                { ar: "عَبْدُكَ الْمِسْكِيْنُ يَرْجُوْ ۞ فَضْلَكَ الْجَمُّ اْلغَفِيْرُ", tr: "'Andukalmiskiinuyarjuu, Fadhlaka Jammal Ghofiiru", ket: "Hambamu yang miskin berharap anugerah-Mu yang banyak lagi merata." },
                { ar: "فِيْكَ قَدْ اَحْسَنْتُ ظَنِّى ۞ يَابَشِيْرُ يَانَذِيْرُ", tr: "Fiika Qod Ahsantu Zhonnii, Yaa Basyiiru Yaa Nadziiru", ket: "Aku berbaik sangka kepadamu wahai pemberi kabar gembira dan pemberi peringatan." },
                { ar: "فَأَغِثْنِى وَأَجِرْنِى ۞ يَامُجِيْرُ مِنَ السَّعِيْرِ", tr: "Fa Aghiyatsii Yaa Malaadzii, Fii Mulimmaatil Umuuri", ket: "Maka tolonglah aku dan selamatkanlah aku wahai penyelamat, penyelamat dari neraka Sa’ir." },
                { ar: "يَاغِيَاثِى يَامَلَاذِىْ ۞ فِى مُلِمَّاتِ اْلأُمُوْرِ", tr: "Ya ghiyaatsi yaa malaadzii, fii mulimmaatil umuuri", ket: "Wahai penolongku, wahai tempat berlindungku dalam perkara-perkara yang menyulitkan." },
                { ar: "سَعْدَ عَبْدٌ قَدْ تَمَلَّى ۞ وَانْجَلَى عَنْهُ الْحَزِيْنُ", tr: "Sa'da ngabdungqod tamalla, wanjala nganhul haziinu", ket: "Berbahagialah dan hilanglah kesusahan hamba yang senang kepadamu." },
                { ar: "فِيْكَ يَابَدْرٌ تَجَلَّى ۞ فَلَكَ الْوَصْفُ الْحَسِيْنُ", tr: "fiika yaa badrun tajalla, falakal washful hasiinu", ket: "Wahai bulan purnama yang nampak terang, bagimu sifat yang bagus." },
                { ar: "لَيْسَ أَزْكَى مِنْكَ أصْلًا ۞ قَطُّ يَاجَدَّ الْحُسَيْنِ", tr: "Laysa Azkaa Mingkaa Ashlan, Qothuyaa Jaddal Husaini", ket: "Tiada orang yang orang tuanya lebih suci darimu sama sekali wahai kakek hasan dan Husain." },
                { ar: "فَعَلَيْكَ اللّٰهُ صَلَّى ۞ دَائِمًا طُوْلَ الدُّهُوْرِ", tr: "Fa'Alaikalloohushollaa, Da Imaan Thuuladuhuuri", ket: "Maka padamulah sholawat Allah ﷻ selamanya sepanjang masa." },
                { ar: "يَاوَلِيَ الْحَسَنَاتِ ۞ يَارَفِيْعَ الدَّرَجَاتِ", tr: "Yaa Waliyyaal Hasanaati, Yaarofii'Addarojaati", ket: "Wahai Dzat Penguasa kebaikan, Wahai Dzat Yang Berpangkat Tinggi." },
                { ar: "كَفِّرْ عَنِّيَ الذُّنُوْبَ ۞ وَاغْفِرْ عَنِّى السَّيَّئَاتِ", tr: "Kaffir Anniddunuuba, Waghfir 'Annissayyi'Aati", ket: "Hapuslah dosa-dosaku dan ampunilah kesalahan-kesalahanku." },
                { ar: "أَنْتَ غَفَّارُ الْخَطَايَا ۞ وَالذُّنُوْبِ الْمُوْبِقَاتِ", tr: "Angtaghoffaarul Khothooyaa, Waddunuubil Muubiqooti", ket: "Engkau adalah Maha Pengampun atas kesalahan-kesalahan dan dosa-dosa yang merusakkan." },
                { ar: "أَنْتَ سَتَّارُ الْمَسَوِىْ ۞ وَمُقِيْلُ الْعَثَرَاتِ", tr: "Angtasattaarul Masaawii, Wamuqiilul A'Sarootsi", ket: "Engkau adalah Yang menutupi kejelekan dan Yang Menyelamatkanku dari kesalahan." },
                { ar: "عَالِمُ السَّرِّ وَأَخْفَى ۞ مُسْتَجِيْبُ الدَّعَوَاتِ", tr: "Aalimussirriwa Akhfaa, Mustajiibudda A'Waati", ket: "Engkau Maha Mengetahui rahasia dan kesamaran. Engkau adalah Pengabul segala pinta (doa)." },
                { ar: "رَبِّ فَارْحَمْنَا جَمِيْعًا ۞ بِجَمِيْعِ الصَّالِحَاتِ", tr: "Robbifaarhamnaa Jamii Aa, Bijami'Ish Shoolahaati", ket: "Tuhan, belas kasihanilah kami semua dengan mampu menjalankan amal baik." },
                { ar: "وَصَلَاةُ اللّٰهِ تَغْشَا ۞ عَدَّ تَحْرِيْرِ السُّطُوْرِ", tr: "Washolatulloohi Taghsyaa, 'Addatahriirissuthuuri", ket: "Tuhan, belas kasihanilah kami semua dengan mampu menjalankan amal baik." },
                { ar: "أَحْمَدَ الْهَادِىْ مُحَمَّدْ ۞ صَاحِبَ الْوَجْهِ الْمُنِيْرِ", tr: "Ahmadal Haadii Muhammad, Shoohibaawaj Hilmuniiri", ket: "Ahmad sang petunjuk yaitu Muhammad ﷺ pemilik wajah yang bersinar." }
            ]
        }
    ]
};
